/*
 * JUnit 4 test suite for {@link org.apache.commons.lang3.text.translate.LookupTranslator}.
 *
 * The tests cover:
 *  1. Construction with {@code null} and empty lookup tables.
 *  2. Correct calculation of the internal {@code shortest} and {@code longest} values.
 *  3. Simple key/value translation.
 *  4. Greedy (longest‑match) behaviour.
 *  5. Fallback to a shorter key when the longest key cannot be matched because of
 *     input length.
 *  6. Behaviour when a key that does not implement content‑based {@code equals/hashCode}
 *     (e.g., {@code StringBuilder}) is used.
 *  7. Multiple translations within the same input string.
 *
 * The helper method {@code translateWhole} mimics the behaviour of
 * {@code CharSequenceTranslator.translate(CharSequence)} – it repeatedly calls the
 * package‑private {@code translate(CharSequence, int, Writer)} method.
 */

package org.apache.commons.lang3.text.translate;

import static org.junit.Assert.*;

import java.io.IOException;
import java.io.StringWriter;
import java.lang.reflect.Field;
import java.util.HashMap;

import org.junit.Test;

/**
 * Test class for {@link LookupTranslator}.
 */
public class LookupTranslatorTest {

    /**
     * Utility that applies a {@link LookupTranslator} to an entire string,
     * emulating {@code CharSequenceTranslator.translate(CharSequence)}.
     */
    private static String translateWhole(LookupTranslator translator, String input) throws IOException {
        StringWriter out = new StringWriter(input.length() * 2);
        int pos = 0;
        while (pos < input.length()) {
            int consumed = translator.translate(input, pos, out);
            if (consumed == 0) {
                // No translation – copy the original character.
                out.write(input.charAt(pos));
                pos++;
            } else {
                // Translation occured – advance by the number of consumed characters.
                pos += consumed;
            }
        }
        return out.toString();
    }

    @Test
    public void testConstructorWithNullLookupDoesNothing() throws IOException {
        LookupTranslator lt = new LookupTranslator(null);
        // With no entries the translator must leave the input untouched.
        String input = "anything";
        assertEquals(input, translateWhole(lt, input));

        // Verify internal state via reflection – shortest should be MAX_VALUE,
        // longest should be 0.
        try {
            Field shortestField = LookupTranslator.class.getDeclaredField("shortest");
            Field longestField  = LookupTranslator.class.getDeclaredField("longest");
            shortestField.setAccessible(true);
            longestField.setAccessible(true);
            assertEquals(Integer.MAX_VALUE, shortestField.getInt(lt));
            assertEquals(0, longestField.getInt(lt));
        } catch (ReflectiveOperationException e) {
            fail("Reflection error: " + e);
        }
    }

    @Test
    public void testConstructorWithEmptyLookupDoesNothing() throws IOException {
        LookupTranslator lt = new LookupTranslator(new CharSequence[0][]);
        String input = "xyz";
        assertEquals(input, translateWhole(lt, input));

        // Internal fields should be same as the null case.
        try {
            Field shortestField = LookupTranslator.class.getDeclaredField("shortest");
            Field longestField  = LookupTranslator.class.getDeclaredField("longest");
            shortestField.setAccessible(true);
            longestField.setAccessible(true);
            assertEquals(Integer.MAX_VALUE, shortestField.getInt(lt));
            assertEquals(0, longestField.getInt(lt));
        } catch (ReflectiveOperationException e) {
            fail("Reflection error: " + e);
        }
    }

    @Test
    public void testSimpleTranslation() throws IOException {
        // Single entry: "a" -> "A"
        LookupTranslator lt = new LookupTranslator(new CharSequence[][]{
            {"a", "A"}
        });

        assertEquals("A", translateWhole(lt, "a"));
        assertEquals("Abc", translateWhole(lt, "abc"));
        assertEquals("bc", translateWhole(lt, "bc")); // 'a' not present
    }

    @Test
    public void testGreedyLongestMatch() throws IOException {
        // Two overlapping keys: "ab" -> "X", "abc" -> "Y"
        LookupTranslator lt = new LookupTranslator(new CharSequence[][]{
            {"ab", "X"},
            {"abc", "Y"}
        });

        // Input "abc" should match the longer key "abc" and produce "Y"
        assertEquals("Y", translateWhole(lt, "abc"));

        // Input "abx" should match the shorter key "ab" (since "abc" not present)
        assertEquals("Xx", translateWhole(lt, "abx"));
    }

    @Test
    public void testFallbackWhenLongestExceedsInputLength() throws IOException {
        // Keys of length 2 and 3
        LookupTranslator lt = new LookupTranslator(new CharSequence[][]{
            {"ab", "X"},
            {"abc", "Y"}
        });

        // Input length is only 2; longest (3) cannot be tried, but the
        // translator must still match the 2‑character key.
        assertEquals("Xc", translateWhole(lt, "abc"));
        // Input "ab" (exact length 2) should translate via the 2‑char key.
        assertEquals("X", translateWhole(lt, "ab"));
    }

    @Test
    public void testKeyWithNonStringCharSequenceNotMatched() throws IOException {
        // Use a StringBuilder as the key – it does NOT have content‑based equals()
        // and therefore will not match a String produced by subSequence().
        CharSequence key = new StringBuilder("foo");
        LookupTranslator lt = new LookupTranslator(new CharSequence[][]{
            {key, "bar"}
        });

        // Because the runtime key is a StringBuilder, looking up with a String will fail.
        assertEquals("foo", translateWhole(lt, "foo"));
        // Ensure that a normal String key works as a control.
        LookupTranslator lt2 = new LookupTranslator(new CharSequence[][]{
            {"foo", "bar"}
        });
        assertEquals("bar", translateWhole(lt2, "foo"));
    }

    @Test
    public void testMultipleTranslationsInSingleString() throws IOException {
        // Map a few HTML entities.
        LookupTranslator htmlEscaper = new LookupTranslator(new CharSequence[][]{
            {"<", "&lt;"},
            {">", "&gt;"},
            {"&", "&amp;"},
            {"\"", "&quot;"}
        });

        String input = "a < b && c > d \"quote\"";
        String expected = "a &lt; b &amp;&amp; c &gt; d &quot;quote&quot;";
        assertEquals(expected, translateWhole(htmlEscaper, input));
    }

    @Test
    public void testShortestAndLongestValuesViaReflection() {
        // Prepare a lookup with keys of lengths 1, 3, and 5.
        LookupTranslator lt = new LookupTranslator(new CharSequence[][]{
            {"x", "X"},
            {"xyz", "XYZ"},
            {"12345", "NUM"}
        });

        try {
            Field shortestField = LookupTranslator.class.getDeclaredField("shortest");
            Field longestField  = LookupTranslator.class.getDeclaredField("longest");
            shortestField.setAccessible(true);
            longestField.setAccessible(true);
            int shortest = shortestField.getInt(lt);
            int longest  = longestField.getInt(lt);
            assertEquals(1, shortest);
            assertEquals(5, longest);
        } catch (ReflectiveOperationException e) {
            fail("Could not access private fields: " + e);
        }
    }

    @Test
    public void testTranslateReturnsZeroWhenNoMatch() throws IOException {
        LookupTranslator lt = new LookupTranslator(new CharSequence[][]{
            {"abc", "X"}
        });

        StringWriter out = new StringWriter();
        // Position 0: input is "z", not matching any key
        int consumed = lt.translate("zab", 0, out);
        assertEquals(0, consumed);
        assertEquals("", out.toString());

        // Ensure that the higher level translateWhole copies the original character.
        assertEquals("zab", translateWhole(lt, "zab"));
    }

    @Test
    public void testTranslateDoesNotModifyWriterOnZeroMatch() throws IOException {
        LookupTranslator lt = new LookupTranslator(new CharSequence[][]{
            {"hello", "hi"}
        });

        StringWriter out = new StringWriter();
        out.write('X'); // pre‑populate writer
        int consumed = lt.translate("world", 0, out);
        assertEquals(0, consumed);
        // Writer must still contain the pre‑written character only.
        assertEquals("X", out.toString());
    }
}

package org.apache.commons.lang3.text.translate;

import static org.junit.Assert.*;

import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;

import org.junit.Test;

/**
 * Comprehensive JUnit4 test suite for {@link LookupTranslator}.
 *
 * The tests cover:
 * <ul>
 *   <li>Construction with null, empty and normal lookup tables.</li>
 *   <li>Correct handling of the {@code shortest} and {@code longest} boundaries.</li>
 *   <li>Greedy (longest‑match) translation behaviour.</li>
 *   <li>Behaviour when no match is found.</li>
 *   <li>Case‑sensitivity and duplicate‑key handling.</li>
 *   <li>Effect of using a non‑String {@link CharSequence} as a key.</li>
 * </ul>
 */
public class LookupTranslatorTest {

    /** Utility method that invokes {@link LookupTranslator#translate(CharSequence, int, Writer)} */
    private static int translate(LookupTranslator lt, CharSequence input, Writer out) throws IOException {
        return lt.translate(input, 0, out);
    }

    @Test
    public void testSimpleTranslation() throws IOException {
        LookupTranslator lt = new LookupTranslator(new CharSequence[][]{
                {"a", "b"}
        });

        StringWriter sw = new StringWriter();
        int consumed = translate(lt, "a", sw);
        assertEquals("Exactly one character should be consumed", 1, consumed);
        assertEquals("Simple mapping should replace 'a' with 'b'", "b", sw.toString());
    }

    @Test
    public void testNoMatchReturnsZeroAndWritesNothing() throws IOException {
        LookupTranslator lt = new LookupTranslator(new CharSequence[][]{
                {"x", "y"}
        });

        StringWriter sw = new StringWriter();
        int consumed = translate(lt, "z", sw);
        assertEquals("When no mapping exists, 0 characters should be consumed", 0, consumed);
        assertEquals("Writer must remain empty when there is no match", "", sw.toString());
    }

    @Test
    public void testGreedyLongestMatch() throws IOException {
        // Two overlapping keys: "ab" (longer) and "a" (shorter)
        LookupTranslator lt = new LookupTranslator(new CharSequence[][]{
                {"ab", "LONG"},
                {"a", "SHORT"}
        });

        StringWriter sw = new StringWriter();
        int consumed = translate(lt, "ab", sw);
        assertEquals("Greedy algorithm must consume the longest key", 2, consumed);
        assertEquals("Output must correspond to the longest key", "LONG", sw.toString());
    }

    @Test
    public void testPartialMatchWhenInputShorterThanLongestKey() throws IOException {
        // Longest key length = 4, but input only 3 characters
        LookupTranslator lt = new LookupTranslator(new CharSequence[][]{
                {"abcd", "X"}
        });

        StringWriter sw = new StringWriter();
        int consumed = translate(lt, "abc", sw);
        assertEquals("When input is shorter than any key, no characters are consumed", 0, consumed);
        assertEquals("Writer must stay empty because no key fits", "", sw.toString());
    }

    @Test
    public void testConstructorWithNullLookup() throws IOException {
        LookupTranslator lt = new LookupTranslator(null);
        StringWriter sw = new StringWriter();
        int consumed = translate(lt, "anything", sw);
        assertEquals("Null lookup table must behave as empty table", 0, consumed);
        assertEquals("No output should be produced", "", sw.toString());
    }

    @Test
    public void testConstructorWithEmptyLookupArray() throws IOException {
        LookupTranslator lt = new LookupTranslator(new CharSequence[0][]);
        StringWriter sw = new StringWriter();
        int consumed = translate(lt, "foo", sw);
        assertEquals("Empty lookup array must behave like empty table", 0, consumed);
        assertEquals("Writer must stay empty", "", sw.toString());
    }

    @Test
    public void testDuplicateKeyOverridesPrevious() throws IOException {
        // The second entry for "dup" should overwrite the first one.
        LookupTranslator lt = new LookupTranslator(new CharSequence[][]{
                {"dup", "first"},
                {"dup", "second"}
        });

        StringWriter sw = new StringWriter();
        int consumed = translate(lt, "dup", sw);
        assertEquals(3, consumed);
        assertEquals("second", sw.toString());
    }

    @Test
    public void testCaseSensitivity() throws IOException {
        LookupTranslator lt = new LookupTranslator(new CharSequence[][]{
                {"Key", "VALUE"}
        });

        StringWriter sw1 = new StringWriter();
        int consumed1 = translate(lt, "Key", sw1);
        assertEquals(3, consumed1);
        assertEquals("VALUE", sw1.toString());

        StringWriter sw2 = new StringWriter();
        int consumed2 = translate(lt, "key", sw2);
        assertEquals("Different case must not match", 0, consumed2);
        assertEquals("", sw2.toString());
    }

    @Test
    public void testNonStringCharSequenceKeyDoesNotMatch() throws IOException {
        // Using StringBuilder as the key – it will NOT match a String input because
        // StringBuilder does not override equals to compare content.
        CharSequence keyBuilder = new StringBuilder("sb");
        LookupTranslator lt = new LookupTranslator(new CharSequence[][]{
                {keyBuilder, "RESULT"}
        });

        StringWriter sw = new StringWriter();
        int consumed = translate(lt, "sb", sw);
        assertEquals("Lookup with non‑String key must fail to match a String subsequence", 0, consumed);
        assertEquals("", sw.toString());
    }

    @Test
    public void testMultipleTranslationsInSequence() throws IOException {
        // This test simulates processing a longer input by repeatedly calling translate()
        // advancing the index manually.
        LookupTranslator lt = new LookupTranslator(new CharSequence[][]{
                {"ab", "X"},
                {"c", "Y"},
                {"d", "Z"}
        });

        String input = "abcd";
        StringBuilder result = new StringBuilder();
        int index = 0;
        while (index < input.length()) {
            StringWriter sw = new StringWriter();
            int consumed = lt.translate(input, index, sw);
            if (consumed == 0) {
                // No mapping – copy the original character
                result.append(input.charAt(index));
                index++;
            } else {
                result.append(sw.toString());
                index += consumed;
            }
        }
        assertEquals("Expected combined translation X Y Z", "XYZ", result.toString());
    }
}

package org.apache.commons.lang3.text.translate;

import static org.junit.Assert.*;

import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;

import org.junit.Before;
import org.junit.Test;

/**
 * Test suite for {@link LookupTranslator}.
 *
 * The tests cover:
 *   • basic translation,
 *   • greedy longest‑match behaviour,
 *   • handling of empty / null lookup tables,
 *   • duplicate key handling,
 *   • boundary conditions when the index is near the end of the input,
 *   • propagation of IOException from the Writer,
 *   • and the expected NPE when a null input is supplied.
 */
public class LookupTranslatorTest {

    private LookupTranslator simpleTranslator;
    private LookupTranslator greedyTranslator;
    private LookupTranslator emptyTranslator;
    private LookupTranslator nullLookupTranslator;
    private LookupTranslator duplicateKeyTranslator;

    @Before
    public void setUp() {
        // 1. simple one‑to‑one mapping
        simpleTranslator = new LookupTranslator(new CharSequence[][]{
                {"a", "b"}
        });

        // 2. greedy mapping – both "a" and "ab" exist
        greedyTranslator = new LookupTranslator(new CharSequence[][]{
                {"a", "x"},
                {"ab", "y"}
        });

        // 3. empty lookup (no mappings)
        emptyTranslator = new LookupTranslator(new CharSequence[0][]);

        // 4. null lookup argument
        nullLookupTranslator = new LookupTranslator(null);

        // 5. duplicate key – last mapping should win
        duplicateKeyTranslator = new LookupTranslator(new CharSequence[][]{
                {"k", "first"},
                {"k", "second"}
        });
    }

    /** Helper that runs translate() and returns the written string. */
    private String translate(LookupTranslator lt, CharSequence input, int index) throws IOException {
        StringWriter out = new StringWriter();
        int consumed = lt.translate(input, index, out);
        // we return both the output and the consumed length for assertions
        return consumed + "|" + out.toString();
    }

    // ------------------------------------------------------------------------
    // Basic functionality tests
    // ------------------------------------------------------------------------

    @Test
    public void testSimpleTranslation() throws IOException {
        String result = translate(simpleTranslator, "a", 0);
        assertEquals("1|b", result); // consumed 1 char, wrote "b"
    }

    @Test
    public void testGreedyLongestMatch() throws IOException {
        // Input "ab" should match the longer key "ab" → "y"
        String result = translate(greedyTranslator, "ab", 0);
        assertEquals("2|y", result);
    }

    @Test
    public void testNoMatchReturnsZero() throws IOException {
        String result = translate(simpleTranslator, "z", 0);
        assertEquals("0|", result); // nothing written, zero chars consumed
    }

    @Test
    public void testIndexNearEnd() throws IOException {
        // longest key in greedyTranslator is 2 ("ab")
        // index = 1, input length = 2 => only one char left, should try "b" (no match)
        String result = translate(greedyTranslator, "ab", 1);
        assertEquals("0|", result);
    }

    // ------------------------------------------------------------------------
    // Edge‑case tests
    // ------------------------------------------------------------------------

    @Test
    public void testEmptyLookupArray() throws IOException {
        String result = translate(emptyTranslator, "anything", 0);
        assertEquals("0|", result);
    }

    @Test
    public void testNullLookupArray() throws IOException {
        String result = translate(nullLookupTranslator, "anything", 0);
        assertEquals("0|", result);
    }

    @Test
    public void testDuplicateKeyKeepsLastValue() throws IOException {
        String result = translate(duplicateKeyTranslator, "k", 0);
        assertEquals("1|second", result);
    }

    @Test(expected = IOException.class)
    public void testWriterIOExceptionPropagates() throws IOException {
        LookupTranslator lt = new LookupTranslator(new CharSequence[][]{
                {"a", "b"}
        });
        Writer badWriter = new Writer() {
            @Override public void write(char[] cbuf, int off, int len) throws IOException {
                throw new IOException("forced");
            }
            @Override public void flush() {}
            @Override public void close() {}
        };
        lt.translate("a", 0, badWriter); // should throw IOException
    }

    @Test(expected = NullPointerException.class)
    public void testInputNullThrowsNPE() throws IOException {
        simpleTranslator.translate(null, 0, new StringWriter());
    }
}

/****************************************************************************************
 * JUnit‑4 test suite for {@link org.apache.commons.lang3.text.translate.LookupTranslator}
 *
 * The tests are written from the perspective of three “experts”.  Each expert contributes
 * one test case per public method, covering typical usage, edge‑cases and error
 * scenarios.  The suite therefore exercises:
 *
 *   • Constructor behaviour (calculation of shortest/longest, handling of null/empty
 *     lookup tables, duplicate keys, and different CharSequence implementations)
 *
 *   • {@code translate(...)} – greedy longest‑match algorithm, boundary handling,
 *     non‑matching input, and propagation of {@link IOException}
 *
 * The tests use reflection to inspect the private fields {@code shortest} and
 * {@code longest} because they are part of the contract of the translator.
 *
 * Author:  simulated “expert” collaboration
 * Version: JUnit‑4 (compatible with Java 8+)
 ****************************************************************************************/

package org.apache.commons.lang3.text.translate;

import static org.junit.Assert.*;

import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.lang.reflect.Field;
import java.util.Arrays;

import org.junit.Before;
import org.junit.Test;

/**
 * Comprehensive test cases for {@link LookupTranslator}.
 */
public class LookupTranslatorTest {

    private LookupTranslator translator;

    /** Helper to read the private {@code shortest} field via reflection. */
    private static int getShortest(LookupTranslator lt) throws Exception {
        Field f = LookupTranslator.class.getDeclaredField("shortest");
        f.setAccessible(true);
        return f.getInt(lt);
    }

    /** Helper to read the private {@code longest} field via reflection. */
    private static int getLongest(LookupTranslator lt) throws Exception {
        Field f = LookupTranslator.class.getDeclaredField("longest");
        f.setAccessible(true);
        return f.getInt(lt);
    }

    /**
     * -------------------------------------------------------------------------
     * Expert 1 – Constructor validation (shortest / longest calculation)
     * -------------------------------------------------------------------------
     */
    @Test
    public void testConstructorCalculatesShortestAndLongest() throws Exception {
        // lookup table with keys of length 1, 2 and 3
        CharSequence[][] table = {
                {"a", "1"},
                {"ab", "2"},
                {"abc", "3"}
        };
        translator = new LookupTranslator(table);

        assertEquals("Shortest key length should be 1", 1, getShortest(translator));
        assertEquals("Longest key length should be 3", 3, getLongest(translator));
    }

    /**
     * -------------------------------------------------------------------------
     * Expert 2 – Translate method – greedy longest‑match behaviour
     * -------------------------------------------------------------------------
     */
    @Test
    public void testTranslateGreedyLongestMatch() throws IOException {
        CharSequence[][] table = {
                {"a", "1"},
                {"ab", "2"},
                {"abc", "3"}
        };
        translator = new LookupTranslator(table);

        StringWriter out = new StringWriter();
        int consumed = translator.translate("abc", 0, out);

        assertEquals("Translator should consume the whole longest match (3 chars)", 3, consumed);
        assertEquals("Output should be the value for the longest key", "3", out.toString());
    }

    /**
     * -------------------------------------------------------------------------
     * Expert 3 – Translate method – fallback to shorter match when longer does not exist
     * -------------------------------------------------------------------------
     */
    @Test
    public void testTranslateFallsBackToShorterMatch() throws IOException {
        CharSequence[][] table = {
                {"a", "1"},
                {"ab", "2"},
                {"abc", "3"}
        };
        translator = new LookupTranslator(table);

        StringWriter out = new StringWriter();
        int consumed = translator.translate("abx", 0, out);

        assertEquals("Should fall back to the 'ab' entry (2 chars)", 2, consumed);
        assertEquals("Output should be the value for the 'ab' key", "2", out.toString());
    }

    /**
     * -------------------------------------------------------------------------
     * Expert 1 – Constructor with null lookup array
     * -------------------------------------------------------------------------
     */
    @Test
    public void testConstructorWithNullLookup() throws Exception {
        translator = new LookupTranslator((CharSequence[][]) null);

        // With a null lookup the internal shortest should stay at MAX_VALUE and longest at 0
        assertEquals(Integer.MAX_VALUE, getShortest(translator));
        assertEquals(0, getLongest(translator));

        // translate must simply return 0 and not throw any exception
        StringWriter out = new StringWriter();
        int consumed = translator.translate("anything", 0, out);
        assertEquals("No translation possible, should return 0", 0, consumed);
        assertEquals("Writer must stay empty", "", out.toString());
    }

    /**
     * -------------------------------------------------------------------------
     * Expert 2 – Empty lookup (no var‑args entries)
     * -------------------------------------------------------------------------
     */
    @Test
    public void testConstructorWithEmptyLookup() throws Exception {
        translator = new LookupTranslator(); // empty var‑args

        assertEquals(Integer.MAX_VALUE, getShortest(translator));
        assertEquals(0, getLongest(translator));

        StringWriter out = new StringWriter();
        int consumed = translator.translate("test", 0, out);
        assertEquals(0, consumed);
        assertEquals("", out.toString());
    }

    /**
     * -------------------------------------------------------------------------
     * Expert 3 – Translate with no matching key
     * -------------------------------------------------------------------------
     */
    @Test
    public void testTranslateNoMatchReturnsZero() throws IOException {
        CharSequence[][] table = { {"x", "X"} };
        translator = new LookupTranslator(table);

        StringWriter out = new StringWriter();
        int consumed = translator.translate("abc", 0, out);

        assertEquals("When nothing matches, translate should return 0", 0, consumed);
        assertEquals("Writer must remain untouched when no match", "", out.toString());
    }

    /**
     * -------------------------------------------------------------------------
     * Expert 1 – Boundary handling when input is shorter than the longest key
     * -------------------------------------------------------------------------
     */
    @Test
    public void testTranslateRespectsInputBoundary() throws IOException {
        // longest key is 4, but input length is only 3
        CharSequence[][] table = { {"abcd", "Z"} };
        translator = new LookupTranslator(table);

        StringWriter out = new StringWriter();
        int consumed = translator.translate("abc", 0, out);

        // No match because the only key is longer than the remaining input
        assertEquals(0, consumed);
        assertEquals("", out.toString());
    }

    /**
     * -------------------------------------------------------------------------
     * Expert 2 – Propagation of IOException from the Writer
     * -------------------------------------------------------------------------
     */
    @Test(expected = IOException.class)
    public void testTranslatePropagatesIOException() throws IOException {
        CharSequence[][] table = { {"boom", "B"} };
        translator = new LookupTranslator(table);

        Writer badWriter = new Writer() {
            @Override public void write(char[] cbuf, int off, int len) throws IOException {
                throw new IOException("forced failure");
            }
            @Override public void flush() throws IOException {}
            @Override public void close() throws IOException {}
        };

        // This call must throw the IOException defined above
        translator.translate("boom", 0, badWriter);
    }

    /**
     * -------------------------------------------------------------------------
     * Expert 3 – Using non‑String CharSequence implementations as keys/values
     * -------------------------------------------------------------------------
     */
    @Test
    public void testLookupWithDifferentCharSequenceImplementations() throws IOException {
        // Use StringBuilder for the key and value – they are not Strings but implement CharSequence
        CharSequence key = new StringBuilder("key");
        CharSequence value = new StringBuilder("val");
        CharSequence[][] table = { { key, value } };

        translator = new LookupTranslator(table);

        StringWriter out = new StringWriter();
        int consumed = translator.translate("key", 0, out);

        assertEquals(3, consumed);
        assertEquals("val", out.toString());
    }

    /**
     * -------------------------------------------------------------------------
     * Expert 1 – Duplicate keys – the last entry should win (Map.put overwrites)
     * -------------------------------------------------------------------------
     */
    @Test
    public void testDuplicateKeysLastOneWins() throws IOException {
        CharSequence[][] table = {
                {"dup", "first"},
                {"dup", "second"} // should overwrite the previous entry
        };
        translator = new LookupTranslator(table);

        StringWriter out = new StringWriter();
        int consumed = translator.translate("dup", 0, out);

        assertEquals(3, consumed);
        assertEquals("second", out.toString());
    }

    /**
     * -------------------------------------------------------------------------
     * Expert 2 – Translate at a non‑zero index (partial scanning)
     * -------------------------------------------------------------------------
     */
    @Test
    public void testTranslateFromNonZeroIndex() throws IOException {
        CharSequence[][] table = {
                {"foo", "F"},
                {"bar", "B"}
        };
        translator = new LookupTranslator(table);

        StringWriter out = new StringWriter();
        // Input "xxfoobar", start at index 2 (the first 'f')
        int consumed = translator.translate("xxfoobar", 2, out);

        assertEquals(3, consumed); // matches "foo"
        assertEquals("F", out.toString());
    }

    /**
     * -------------------------------------------------------------------------
     * Expert 3 – Verify that translate does *not* modify the writer when
     *           the matching key has an empty replacement.
     * -------------------------------------------------------------------------
     */
    @Test
    public void testTranslateWithEmptyReplacement() throws IOException {
        CharSequence[][] table = { {"empty", ""} };
        translator = new LookupTranslator(table);

        StringWriter out = new StringWriter();
        int consumed = translator.translate("empty", 0, out);

        assertEquals(5, consumed);
        assertEquals("", out.toString()); // writer stays empty
    }

    /**
     * -------------------------------------------------------------------------
     * Expert 1 – Verify that the translator is greedy even when multiple keys
     *           share the same prefix.
     * -------------------------------------------------------------------------
     */
    @Test
    public void testGreedyWhenPrefixesOverlap() throws IOException {
        CharSequence[][] table = {
                {"a", "1"},
                {"ab", "2"},
                {"abc", "3"},
                {"abcd", "4"}
        };
        translator = new LookupTranslator(table);

        StringWriter out = new StringWriter();
        int consumed = translator.translate("abcd", 0, out);

        assertEquals(4, consumed);
        assertEquals("4", out.toString()); // longest match wins
    }

    /**
     * -------------------------------------------------------------------------
     * Expert 2 – Verify that translate returns 0 when the remaining input
     *           length is smaller than the shortest key.
     * -------------------------------------------------------------------------
     */
    @Test
    public void testTranslateWhenRemainingShorterThanShortestKey() throws IOException {
        CharSequence[][] table = { {"xyz", "Z"} };
        translator = new LookupTranslator(table); // shortest = 3, longest = 3

        StringWriter out = new StringWriter();
        // Start at index 2 of "ab" – only 0 chars left
        int consumed = translator.translate("ab", 2, out);

        assertEquals(0, consumed);
        assertEquals("", out.toString());
    }

    /**
     * -------------------------------------------------------------------------
     * Expert 3 – Verify that a null input CharSequence causes a NullPointerException
     *           (the contract of CharSequenceTranslator does not guard against it).
     * -------------------------------------------------------------------------
     */
    @Test(expected = NullPointerException.class)
    public void testTranslateWithNullInputThrowsNPE() throws IOException {
        CharSequence[][] table = { {"a", "A"} };
        translator = new LookupTranslator(table);

        translator.translate(null, 0, new StringWriter());
    }

    /**
     * -------------------------------------------------------------------------
     * Expert 1 – Verify that a null Writer causes a NullPointerException
     * -------------------------------------------------------------------------
     */
    @Test(expected = NullPointerException.class)
    public void testTranslateWithNullWriterThrowsNPE() throws IOException {
        CharSequence[][] table = { {"a", "A"} };
        translator = new LookupTranslator(table);

        translator.translate("a", 0, null);
    }

    /**
     * -------------------------------------------------------------------------
     * Expert 2 – Verify that an out‑of‑range index throws IndexOutOfBoundsException
     * -------------------------------------------------------------------------
     */
    @Test(expected = IndexOutOfBoundsException.class)
    public void testTranslateWithInvalidIndexThrowsIOOBE() throws IOException {
        CharSequence[][] table = { {"a", "A"} };
        translator = new LookupTranslator(table);

        // index larger than input length
        translator.translate("a", 5, new StringWriter());
    }

    /**
     * -------------------------------------------------------------------------
     * Expert 3 – Verify that the internal map uses String keys (as per LANG‑882)
     * -------------------------------------------------------------------------
     */
    @Test
    public void testInternalKeyIsString() throws Exception {
        // Provide a key that is not a String (StringBuilder)
        CharSequence key = new StringBuilder("k");
        CharSequence value = "v";
        CharSequence[][] table = { { key, value } };

        translator = new LookupTranslator(table);

        // Access the private map via reflection and check the actual key type
        Field mapField = LookupTranslator.class.getDeclaredField("lookupMap");
        mapField.setAccessible(true);
        @SuppressWarnings("unchecked")
        java.util.Map<CharSequence, CharSequence> map = (java.util.Map<CharSequence, CharSequence>) mapField.get(translator);

        // The map should contain a String key, not the original StringBuilder instance
        assertTrue("Map should contain exactly one entry", map.size() == 1);
        CharSequence storedKey = map.keySet().iterator().next();
        assertTrue("Stored key should be a java.lang.String", storedKey instanceof String);
        assertEquals("k", storedKey.toString());

        // Normal translation must still work
        StringWriter out = new StringWriter();
        int consumed = translator.translate("k", 0, out);
        assertEquals(1, consumed);
        assertEquals("v", out.toString());
    }
}

/**
 * JUnit 4 test cases for {@link org.apache.commons.lang3.text.translate.LookupTranslator}.
 *
 * The tests cover:
 * <ul>
 *   <li>Construction with normal, empty and {@code null} lookup tables.</li>
 *   <li>Basic translation functionality.</li>
 *   <li>Greedy (longest‑match) behaviour.</li>
 *   <li>Edge conditions such as input shorter than the shortest key,
 *       index out of bounds and {@code null} arguments.</li>
 *   <li>Exception propagation from the {@link java.io.Writer}.</li>
 * </ul>
 */
package org.apache.commons.lang3.text.translate;

import static org.junit.Assert.*;

import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;

import org.junit.Test;

/**
 * Comprehensive test suite for {@code LookupTranslator}.
 */
public class LookupTranslatorTest {

    /* --------------------------------------------------------------
     * Helper writer that deliberately throws an IOException.
     * -------------------------------------------------------------- */
    private static class ThrowingWriter extends Writer {
        @Override
        public void write(char[] cbuf, int off, int len) throws IOException {
            throw new IOException("forced");
        }

        @Override
        public void flush() throws IOException {
            // no‑op
        }

        @Override
        public void close() throws IOException {
            // no‑op
        }
    }

    /* --------------------------------------------------------------
     * 1. Basic translation – single‑character mapping.
     * -------------------------------------------------------------- */
    @Test
    public void testBasicSingleCharTranslation() throws IOException {
        LookupTranslator lt = new LookupTranslator(new CharSequence[][]{
                {"a", "b"}
        });
        StringWriter out = new StringWriter();
        int consumed = lt.translate("a", 0, out);
        assertEquals("Should consume one character", 1, consumed);
        assertEquals("b", out.toString());
    }

    /* --------------------------------------------------------------
     * 2. Greedy (longest match) behaviour.
     *    Both "a" and "ab" are defined – the longer key must win.
     * -------------------------------------------------------------- */
    @Test
    public void testGreedyLongestMatch() throws IOException {
        LookupTranslator lt = new LookupTranslator(new CharSequence[][]{
                {"a", "X"},
                {"ab", "Y"}
        });
        StringWriter out = new StringWriter();
        int consumed = lt.translate("ab", 0, out);
        assertEquals("Should consume two characters (longest match)", 2, consumed);
        assertEquals("Y", out.toString());
    }

    /* --------------------------------------------------------------
     * 3. No match when input is shorter than the shortest key.
     * -------------------------------------------------------------- */
    @Test
    public void testNoMatchWhenInputTooShort() throws IOException {
        LookupTranslator lt = new LookupTranslator(new CharSequence[][]{
                {"abc", "Z"}
        });
        StringWriter out = new StringWriter();
        int consumed = lt.translate("ab", 0, out);
        assertEquals("Should not consume any characters", 0, consumed);
        assertEquals("", out.toString());
    }

    /* --------------------------------------------------------------
     * 4. Constructor with null lookup array – should behave as empty map.
     * -------------------------------------------------------------- */
    @Test
    public void testConstructorWithNullLookup() throws IOException {
        LookupTranslator lt = new LookupTranslator((CharSequence[][]) null);
        StringWriter out = new StringWriter();
        int consumed = lt.translate("anything", 0, out);
        assertEquals("Empty translator must not consume characters", 0, consumed);
        assertEquals("", out.toString());
    }

    /* --------------------------------------------------------------
     * 5. Constructor with empty var‑args – also results in an empty map.
     * -------------------------------------------------------------- */
    @Test
    public void testConstructorWithEmptyLookup() throws IOException {
        LookupTranslator lt = new LookupTranslator();
        StringWriter out = new StringWriter();
        int consumed = lt.translate("test", 0, out);
        assertEquals(0, consumed);
        assertEquals("", out.toString());
    }

    /* --------------------------------------------------------------
     * 6. Null input to {@code translate} – should throw NPE.
     * -------------------------------------------------------------- */
    @Test(expected = NullPointerException.class)
    public void testTranslateNullInput() throws IOException {
        LookupTranslator lt = new LookupTranslator(new CharSequence[][]{
                {"a", "b"}
        });
        lt.translate(null, 0, new StringWriter());
    }

    /* --------------------------------------------------------------
     * 7. Index beyond input length – should return 0 and not modify writer.
     * -------------------------------------------------------------- */
    @Test
    public void testIndexBeyondInputLength() throws IOException {
        LookupTranslator lt = new LookupTranslator(new CharSequence[][]{
                {"a", "b"}
        });
        StringWriter out = new StringWriter();
        int consumed = lt.translate("abc", 5, out); // index > length
        assertEquals(0, consumed);
        assertEquals("", out.toString());
    }

    /* --------------------------------------------------------------
     * 8. Writer that throws IOException – the exception must propagate.
     * -------------------------------------------------------------- */
    @Test(expected = IOException.class)
    public void testIOExceptionPropagation() throws IOException {
        LookupTranslator lt = new LookupTranslator(new CharSequence[][]{
                {"a", "b"}
        });
        Writer throwingWriter = new ThrowingWriter();
        lt.translate("a", 0, throwingWriter);
    }

    /* --------------------------------------------------------------
     * 9. Multiple entries with same key – later entry overwrites earlier.
     * -------------------------------------------------------------- */
    @Test
    public void testDuplicateKeyOverrides() throws IOException {
        LookupTranslator lt = new LookupTranslator(new CharSequence[][]{
                {"key", "first"},
                {"key", "second"} // should replace "first"
        });
        StringWriter out = new StringWriter();
        int consumed = lt.translate("key", 0, out);
        assertEquals(3, consumed);
        assertEquals("second", out.toString());
    }

    /* --------------------------------------------------------------
     * 10. Verify that the translator respects the supplied index
     *     (partial translation inside a larger string).
     * -------------------------------------------------------------- */
    @Test
    public void testTranslateFromMiddleOfInput() throws IOException {
        LookupTranslator lt = new LookupTranslator(new CharSequence[][]{
                {"bc", "X"}
        });
        StringWriter out = new StringWriter();
        int consumed = lt.translate("abcde", 1, out); // start at 'b'
        assertEquals(2, consumed);
        assertEquals("X", out.toString());
    }
}

