/**
 * Comprehensive JUnit‑4 test suite for {@link org.apache.commons.lang3.text.translate.CharSequenceTranslator}.
 *
 * The tests cover:
 * <ul>
 *   <li>the {@code translate(CharSequence)} convenience method (null handling, normal translation)</li>
 *   <li>the {@code translate(CharSequence, Writer)} method (null writer, surrogate handling,
 *       zero‑consumption fallback, multi‑code‑point consumption)</li>
 *   <li>the {@code with(CharSequenceTranslator...)} merger helper</li>
 *   <li>the static {@code hex(int)} utility method</li>
 * </ul>
 *
 * Simple concrete subclasses of {@code CharSequenceTranslator} are defined as static inner classes
 * to exercise the abstract {@code translate(CharSequence, int, Writer)} contract without pulling
 * in any external library code.
 */
package org.apache.commons.lang3.text.translate;

import static org.junit.Assert.*;

import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.util.Locale;

import org.junit.Test;

/**
 * Test class for {@link CharSequenceTranslator}.
 */
public class CharSequenceTranslatorTest {

    /* ----------------------------------------------------------------------
     * Helper concrete translators used throughout the test suite
     * ---------------------------------------------------------------------- */

    /**
     * A translator that never consumes any characters.
     * It returns {@code 0} for every call, which forces the base class to copy the
     * original character(s) to the output writer.
     */
    private static final class NoOpTranslator extends CharSequenceTranslator {
        @Override
        public int translate(CharSequence input, int index, Writer out) throws IOException {
            // consume nothing – the base class will copy the original character(s)
            return 0;
        }
    }

    /**
     * Replaces a single character with a given string.
     */
    private static final class SimpleReplaceTranslator extends CharSequenceTranslator {
        private final char target;
        private final String replacement;

        SimpleReplaceTranslator(char target, String replacement) {
            this.target = target;
            this.replacement = replacement;
        }

        @Override
        public int translate(CharSequence input, int index, Writer out) throws IOException {
            if (input.charAt(index) == target) {
                out.write(replacement);
                return 1; // consumed one code point
            }
            return 0; // no translation, fallback to base class copying
        }
    }

    /**
     * Consumes a surrogate pair (an emoji) and writes a placeholder.
     * Used to verify that multi‑code‑point consumption correctly advances the index.
     */
    private static final class EmojiPlaceholderTranslator extends CharSequenceTranslator {
        private static final int GRINNING_FACE = 0x1F600; // 😀
        private static final String PLACEHOLDER = "[smile]";

        @Override
        public int translate(CharSequence input, int index, Writer out) throws IOException {
            int cp = Character.codePointAt(input, index);
            if (cp == GRINNING_FACE) {
                out.write(PLACEHOLDER);
                // The emoji consists of two char units, so we return 2 to indicate
                // that two characters (one code point) were consumed.
                return Character.charCount(cp);
            }
            return 0;
        }
    }

    /* ----------------------------------------------------------------------
     * Tests for translate(CharSequence) – the convenience method returning a String
     * ---------------------------------------------------------------------- */

    @Test
    public void testTranslate_WithNullInput_ReturnsNull() {
        CharSequenceTranslator translator = new SimpleReplaceTranslator('a', "b");
        assertNull("translate(null) should return null", translator.translate((CharSequence) null));
    }

    @Test
    public void testTranslate_SimpleReplacement() {
        CharSequenceTranslator translator = new SimpleReplaceTranslator('a', "b");
        assertEquals("b", translator.translate("a"));
        assertEquals("bc", translator.translate("ac"));
        assertEquals("bb", translator.translate("aa"));
        assertEquals("abc", translator.translate("abc")); // only first 'a' replaced
    }

    @Test
    public void testTranslate_EmptyInput_ReturnsEmptyString() {
        CharSequenceTranslator translator = new NoOpTranslator();
        assertEquals("", translator.translate(""));
    }

    /* ----------------------------------------------------------------------
     * Tests for translate(CharSequence, Writer) – the core algorithm
     * ---------------------------------------------------------------------- */

    @Test(expected = IllegalArgumentException.class)
    public void testTranslate_WithNullWriter_ThrowsException() throws IOException {
        CharSequenceTranslator translator = new NoOpTranslator();
        translator.translate("test", (Writer) null);
    }

    @Test
    public void testTranslate_WithNullInput_DoesNothing() throws IOException {
        CharSequenceTranslator translator = new SimpleReplaceTranslator('x', "y");
        StringWriter writer = new StringWriter();
        translator.translate((CharSequence) null, writer);
        assertEquals("", writer.toString());
    }

    @Test
    public void testTranslate_NoOpTranslator_CopiesAllCharacters() throws IOException {
        CharSequenceTranslator translator = new NoOpTranslator();
        String input = "Hello, 世界!😀"; // includes BMP chars, CJK, and a surrogate pair (emoji)
        StringWriter writer = new StringWriter();
        translator.translate(input, writer);
        assertEquals("All characters must be copied unchanged", input, writer.toString());
    }

    @Test
    public void testTranslate_EmojiPlaceholderTranslator_ConsumesSurrogatePair() throws IOException {
        CharSequenceTranslator translator = new EmojiPlaceholderTranslator();
        String input = "Start😀End"; // 😀 is U+1F600 (surrogate pair)
        String expected = "Start[smile]End";

        StringWriter writer = new StringWriter();
        translator.translate(input, writer);
        assertEquals("Emoji should be replaced by placeholder", expected, writer.toString());
    }

    @Test
    public void testTranslate_MixedTranslators_CombinedBehaviour() throws IOException {
        // First translator replaces 'a' -> "b"
        // Second translator replaces 'b' -> "c"
        CharSequenceTranslator aToB = new SimpleReplaceTranslator('a', "b");
        CharSequenceTranslator bToC = new SimpleReplaceTranslator('b', "c");
        CharSequenceTranslator combined = aToB.with(bToC); // uses AggregateTranslator internally

        String input = "ababa";
        // Expected step by step:
        // a -> b (first translator) -> c (second translator)
        // b -> c (first translator does nothing, second translator converts)
        // So "ababa" becomes "ccccc"
        String expected = "ccccc";

        assertEquals("Combined translator should apply both replacements",
                expected, combined.translate(input));
    }

    /* ----------------------------------------------------------------------
     * Tests for the static hex(int) utility
     * ---------------------------------------------------------------------- */

    @Test
    public void testHex_Zero() {
        assertEquals("0", CharSequenceTranslator.hex(0));
    }

    @Test
    public void testHex_SingleDigit() {
        assertEquals("A", CharSequenceTranslator.hex(10));
    }

    @Test
    public void testHex_TwoDigits() {
        assertEquals("FF", CharSequenceTranslator.hex(255));
    }

    @Test
    public void testHex_MultiByteCodepoint() {
        // Emoji 😀 = 0x1F600
        assertEquals("1F600", CharSequenceTranslator.hex(0x1F600));
    }

    @Test
    public void testHex_NegativeValue_IsHandledByInteger.toHexString() {
        // Integer.toHexString produces a two's‑complement representation.
        // The contract of CharSequenceTranslator.hex does not forbid negatives,
        // so we just verify that the method forwards to Integer.toHexString.
        int negative = -1;
        String expected = Integer.toHexString(negative).toUpperCase(Locale.ENGLISH);
        assertEquals(expected, CharSequenceTranslator.hex(negative));
    }

    /* ----------------------------------------------------------------------
     * Additional sanity checks for the translate(CharSequence) convenience method
     * ---------------------------------------------------------------------- */

    @Test
    public void testTranslate_ConvenienceMethod_UsesWriterInternally() {
        // We use a translator that throws if the Writer is called more than once per character.
        CharSequenceTranslator singleWriteTranslator = new CharSequenceTranslator() {
            @Override
            public int translate(CharSequence input, int index, Writer out) throws IOException {
                // always consume exactly one code point and write a single character
                out.write('X');
                return 1;
            }
        };

        String result = singleWriteTranslator.translate("abc");
        assertEquals("XXX", result);
    }
}

package org.apache.commons.lang3.text.translate;

import static org.junit.Assert.*;

import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.util.Locale;

import org.junit.Test;

/**
 * Unit tests for {@link CharSequenceTranslator}.
 *
 * <p>These tests exercise all public and protected behaviour:
 *
 * <ul>
 *   <li>{@link CharSequenceTranslator#translate(CharSequence)}</li>
 *   <li>{@link CharSequenceTranslator#translate(CharSequence, Writer)}</li>
 *   <li>{@link CharSequenceTranslator#with(CharSequenceTranslator...)}</li>
 *   <li>{@link CharSequenceTranslator#hex(int)}</li>
 * </ul>
 *
 * <p>Because {@code CharSequenceTranslator} is abstract we provide a few concrete
 * implementations inside the test class to verify the contract of the
 * algorithm in {@code translate(CharSequence, Writer)} as well as the helper
 * methods.</p>
 */
public class CharSequenceTranslatorTest {

    /** Simple translator that replaces a single character with a given string. */
    private static final class SimpleReplaceTranslator extends CharSequenceTranslator {
        private final char target;
        private final String replacement;

        SimpleReplaceTranslator(char target, String replacement) {
            this.target = target;
            this.replacement = replacement;
        }

        @Override
        public int translate(CharSequence input, int index, Writer out) throws IOException {
            if (input.charAt(index) == target) {
                out.write(replacement);
                return 1; // consumed one codepoint
            }
            return 0; // no translation performed
        }
    }

    /** Translator that recognises a surrogate pair (emoji) and replaces it with a token. */
    private static final class EmojiTranslator extends CharSequenceTranslator {
        private final int codepointToMatch;
        private final String token;

        EmojiTranslator(int codepointToMatch, String token) {
            this.codepointToMatch = codepointToMatch;
            this.token = token;
        }

        @Override
        public int translate(CharSequence input, int index, Writer out) throws IOException {
            int cp = Character.codePointAt(input, index);
            if (cp == codepointToMatch) {
                out.write(token);
                // return the number of **code points** consumed (here 1), but the
                // calling algorithm will advance by the correct number of char units.
                return 1;
            }
            return 0;
        }
    }

    /** Writer that deliberately throws an IOException after a certain number of writes. */
    private static final class FailingWriter extends Writer {
        private final int failAfter;
        private int writeCount = 0;

        FailingWriter(int failAfter) {
            this.failAfter = failAfter;
        }

        @Override
        public void write(char[] cbuf, int off, int len) throws IOException {
            if (writeCount >= failAfter) {
                throw new IOException("forced failure");
            }
            writeCount++;
        }

        @Override public void flush() throws IOException {}
        @Override public void close() throws IOException {}
    }

    // -------------------------------------------------------------------------
    // Tests for translate(CharSequence) – the convenience method
    // -------------------------------------------------------------------------

    @Test
    public void testTranslateNullInputReturnsNull() {
        CharSequenceTranslator translator = new SimpleReplaceTranslator('a', "b");
        assertNull("translate(null) must return null", translator.translate((CharSequence) null));
    }

    @Test
    public void testTranslateEmptyStringReturnsEmpty() {
        CharSequenceTranslator translator = new SimpleReplaceTranslator('x', "y");
        assertEquals("", translator.translate(""));
    }

    @Test
    public void testTranslateSimpleReplacement() {
        CharSequenceTranslator translator = new SimpleReplaceTranslator('a', "A");
        assertEquals("Abc", translator.translate("abc"));
        assertEquals("A A", translator.translate("a a"));
        assertEquals("xyz", translator.translate("xyz")); // no 'a' present
    }

    @Test
    public void testTranslateWithSurrogatePair() {
        // 😀  = U+1F600
        String input = "Hello \uD83D\uDE00 World";
        CharSequenceTranslator translator = new EmojiTranslator(0x1F600, "[SMILE]");
        assertEquals("Hello [SMILE] World", translator.translate(input));
    }

    @Test
    public void testTranslateUsesWriterAlgorithmWhenConsumeZero() {
        // This translator never consumes any characters, therefore the algorithm
        // must copy the original input unchanged.
        CharSequenceTranslator identity = new CharSequenceTranslator() {
            @Override
            public int translate(CharSequence input, int index, Writer out) {
                return 0; // indicate “nothing translated”
            }
        };
        assertEquals("unchanged", identity.translate("unchanged"));
    }

    // -------------------------------------------------------------------------
    // Tests for translate(CharSequence, Writer) – lower level API
    // -------------------------------------------------------------------------

    @Test
    public void testTranslateWriterNullWriterThrows() {
        CharSequenceTranslator translator = new SimpleReplaceTranslator('a', "b");
        try {
            translator.translate("test", (Writer) null);
            fail("Expected IllegalArgumentException for null Writer");
        } catch (IllegalArgumentException e) {
            // expected
        } catch (IOException e) {
            fail("Unexpected IOException: " + e);
        }
    }

    @Test
    public void testTranslateWriterNullInputDoesNothing() throws IOException {
        CharSequenceTranslator translator = new SimpleReplaceTranslator('a', "b");
        StringWriter sw = new StringWriter();
        translator.translate((CharSequence) null, sw);
        assertEquals("", sw.toString());
    }

    @Test
    public void testTranslateWriterMultipleTranslators() throws IOException {
        CharSequenceTranslator aToA = new SimpleReplaceTranslator('a', "A");
        CharSequenceTranslator bToB = new SimpleReplaceTranslator('b', "B");
        CharSequenceTranslator combined = aToA.with(bToB); // AggregateTranslator

        StringWriter out = new StringWriter();
        combined.translate("abca", out);
        assertEquals("ABcA", out.toString());
    }

    @Test
    public void testTranslateWriterPropagatesIOException() {
        CharSequenceTranslator translator = new SimpleReplaceTranslator('x', "y");
        Writer failing = new FailingWriter(0); // will fail on first write
        try {
            translator.translate("x", failing);
            fail("Expected IOException to be propagated");
        } catch (IOException e) {
            assertEquals("forced failure", e.getMessage());
        }
    }

    // -------------------------------------------------------------------------
    // Tests for with(...) – merging translators
    // -------------------------------------------------------------------------

    @Test
    public void testWithMergesTranslatorsInOrder() {
        CharSequenceTranslator first = new SimpleReplaceTranslator('1', "one");
        CharSequenceTranslator second = new SimpleReplaceTranslator('2', "two");
        CharSequenceTranslator merged = first.with(second);

        // “12” => first replaces ‘1’, second replaces ‘2’
        assertEquals("onetwo", merged.translate("12"));
    }

    @Test
    public void testWithAddsCurrentTranslatorAtPositionZero() {
        CharSequenceTranslator only = new SimpleReplaceTranslator('z', "Z");
        CharSequenceTranslator merged = only.with(); // no extra translators
        assertEquals("Z", merged.translate("z"));
    }

    // -------------------------------------------------------------------------
    // Tests for static hex(int) utility method
    // -------------------------------------------------------------------------

    @Test
    public void testHexZero() {
        assertEquals("0", CharSequenceTranslator.hex(0));
    }

    @Test
    public void testHexPositiveValues() {
        assertEquals("A", CharSequenceTranslator.hex(10));
        assertEquals("FF", CharSequenceTranslator.hex(255));
        assertEquals("1F600", CharSequenceTranslator.hex(0x1F600)); // 😀
        assertEquals("7FFFFFFF", CharSequenceTranslator.hex(Integer.MAX_VALUE));
    }

    @Test
    public void testHexIsUpperCaseAndLocaleIndependent() {
        Locale defaultLocale = Locale.getDefault();
        try {
            Locale.setDefault(Locale.GERMAN); // uses commas for decimal separator, etc.
            assertEquals("ABCDEF", CharSequenceTranslator.hex(0xABCDEF));
        } finally {
            Locale.setDefault(defaultLocale);
        }
    }

    // -------------------------------------------------------------------------
    // Additional edge‑case tests for surrogate handling in translate(...)
    // -------------------------------------------------------------------------

    @Test
    public void testTranslateConsumesCorrectNumberOfCharsForSurrogatePair() {
        // The translator will replace the emoji (a surrogate pair) with a token.
        CharSequenceTranslator translator = new EmojiTranslator(0x1F602, "LAUGH"); // 😂

        // Input contains: "A", the emoji, and "B"
        String input = "A\uD83D\uDE02B";
        assertEquals("ALAU GHB".replace(" ", ""), translator.translate(input).replace(" ", "")); // simplified check

        // Verify the exact output
        assertEquals("ALAUGH B".replace(" ", ""), translator.translate(input));
        // The result should be "A" + "LAUGH" + "B"
        assertEquals("AL AUGH B".replace(" ", ""), translator.translate(input));
        // Properly assert expected string:
        assertEquals("ALAUGHB", translator.translate(input));
    }

    @Test
    public void testTranslateDoesNotEnterInfiniteLoopWhenTranslatorReturnsZero() {
        // Translator that never translates any character.
        CharSequenceTranslator nop = new CharSequenceTranslator() {
            @Override
            public int translate(CharSequence input, int index, Writer out) throws IOException {
                return 0;
            }
        };
        // Large input to ensure loop terminates.
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 10_000; i++) {
            sb.append('x');
        }
        assertEquals(sb.toString(), nop.translate(sb.toString()));
    }
}

package org.apache.commons.lang3.text.translate;

import org.junit.Test;
import org.junit.Assert;

import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.util.Locale;

/**
 * JUnit 4 test suite for {@link CharSequenceTranslator}.
 *
 * The tests cover:
 * <ul>
 *   <li>Public method signatures</li>
 *   <li>Normal behaviour of each method</li>
 *   <li>Edge‑cases such as {@code null} arguments, empty input, surrogate pairs,
 *       translators that return {@code 0}, and illegal arguments.</li>
 *   <li>Correct handling of the static {@code hex(int)} helper.</li>
 * </ul>
 */
public class CharSequenceTranslatorTest {

    /* ---------------------------------------------------------------------- */
    /* Helper concrete translators                                            */
    /* ---------------------------------------------------------------------- */

    /**
     * Simple translator that copies the current code‑point to the writer
     * and reports that it consumed exactly one Unicode code‑point
     * (which may consist of one or two {@code char}s).
     */
    private static class IdentityTranslator extends CharSequenceTranslator {
        @Override
        public int translate(CharSequence input, int index, Writer out) throws IOException {
            int cp = Character.codePointAt(input, index);
            out.write(Character.toChars(cp));
            return Character.charCount(cp);
        }
    }

    /**
     * Translator that never consumes any input.  It is used to test the
     * fallback path in {@link CharSequenceTranslator#translate(CharSequence, Writer)}.
     */
    private static class ZeroConsumeTranslator extends CharSequenceTranslator {
        @Override
        public int translate(CharSequence input, int index, Writer out) {
            // deliberately consumes nothing and writes nothing
            return 0;
        }
    }

    /**
     * Translator that converts a single Unicode code‑point into its
     * upper‑case hexadecimal representation (using {@link CharSequenceTranslator#hex(int)}).
     * It consumes the whole code‑point, which means surrogate pairs are handled
     * correctly.
     */
    private static class HexTranslator extends CharSequenceTranslator {
        @Override
        public int translate(CharSequence input, int index, Writer out) throws IOException {
            int cp = Character.codePointAt(input, index);
            out.write(hex(cp));
            return Character.charCount(cp);
        }
    }

    /* ---------------------------------------------------------------------- */
    /* 1.  Public method signatures                                            */
    /* ---------------------------------------------------------------------- */

    /**
     * Verify that the class exposes the expected public methods.
     */
    @Test
    public void testPublicMethodSignatures() throws NoSuchMethodException {
        // abstract method
        Assert.assertNotNull(CharSequenceTranslator.class
                .getDeclaredMethod("translate", CharSequence.class, int.class, Writer.class));

        // final helper returning a String
        Assert.assertNotNull(CharSequenceTranslator.class
                .getDeclaredMethod("translate", CharSequence.class));

        // final helper writing to a Writer
        Assert.assertNotNull(CharSequenceTranslator.class
                .getDeclaredMethod("translate", CharSequence.class, Writer.class));

        // final with(...) method
        Assert.assertNotNull(CharSequenceTranslator.class
                .getDeclaredMethod("with", CharSequenceTranslator[].class));

        // static hex(int) method
        Assert.assertNotNull(CharSequenceTranslator.class
                .getDeclaredMethod("hex", int.class));
    }

    /* ---------------------------------------------------------------------- */
    /* 2.  Basic functionality tests                                         */
    /* ---------------------------------------------------------------------- */

    @Test
    public void testTranslateToString_NullInput() {
        CharSequenceTranslator translator = new IdentityTranslator();
        Assert.assertNull(translator.translate((CharSequence) null));
    }

    @Test
    public void testTranslateToString_EmptyInput() {
        CharSequenceTranslator translator = new IdentityTranslator();
        Assert.assertEquals("", translator.translate(""));
    }

    @Test
    public void testTranslateToString_BasicCopy() {
        CharSequenceTranslator translator = new IdentityTranslator();
        String input = "Hello World!";
        String output = translator.translate(input);
        Assert.assertEquals(input, output);
    }

    @Test
    public void testTranslateToWriter_NullWriter() {
        CharSequenceTranslator translator = new IdentityTranslator();
        try {
            translator.translate("test", (Writer) null);
            Assert.fail("Expected IllegalArgumentException for null Writer");
        } catch (IllegalArgumentException e) {
            Assert.assertEquals("The Writer must not be null", e.getMessage());
        } catch (IOException e) {
            Assert.fail("Did not expect IOException");
        }
    }

    @Test
    public void testTranslateToWriter_NullInput() throws IOException {
        CharSequenceTranslator translator = new IdentityTranslator();
        StringWriter writer = new StringWriter();
        translator.translate((CharSequence) null, writer);
        Assert.assertEquals("", writer.toString());
    }

    @Test
    public void testTranslateToWriter_BasicCopy() throws IOException {
        CharSequenceTranslator translator = new IdentityTranslator();
        String input = "Apache Commons";
        StringWriter writer = new StringWriter();
        translator.translate(input, writer);
        Assert.assertEquals(input, writer.toString());
    }

    @Test
    public void testTranslateToWriter_ZeroConsumeFallback() throws IOException {
        // ZeroConsumeTranslator returns 0, so CharSequenceTranslator should write the original char(s)
        CharSequenceTranslator translator = new ZeroConsumeTranslator();
        String input = "abc";
        StringWriter writer = new StringWriter();
        translator.translate(input, writer);
        Assert.assertEquals(input, writer.toString());
    }

    @Test
    public void testTranslateToWriter_SurrogatePairHandling() throws IOException {
        // Use an emoji (U+1F600) which is a supplementary code point (needs a surrogate pair)
        String emoji = "\uD83D\uDE00"; // 😀
        CharSequenceTranslator translator = new HexTranslator();
        StringWriter writer = new StringWriter();
        translator.translate(emoji, writer);
        // Expected hex string is "1F600"
        Assert.assertEquals("1F600", writer.toString());
    }

    @Test
    public void testWithMethod_ReturnsAggregateTranslator() {
        CharSequenceTranslator base = new IdentityTranslator();
        CharSequenceTranslator merged = base.with(new ZeroConsumeTranslator());
        Assert.assertTrue("Merged translator should be an instance of CharSequenceTranslator",
                merged instanceof CharSequenceTranslator);
        // The concrete class is AggregateTranslator (internal to Commons Lang)
        Assert.assertTrue("Merged translator should be an AggregateTranslator",
                merged.getClass().getSimpleName().contains("AggregateTranslator"));
    }

    @Test
    public void testWithMethod_CombinedTranslation() throws IOException {
        // Base translator (Identity) copies input; ZeroConsume consumes nothing.
        // Combine them and ensure the overall behaviour is still copying.
        CharSequenceTranslator base = new IdentityTranslator();
        CharSequenceTranslator combined = base.with(new ZeroConsumeTranslator());

        String input = "Test123";
        StringWriter writer = new StringWriter();
        combined.translate(input, writer);
        Assert.assertEquals(input, writer.toString());
    }

    /* ---------------------------------------------------------------------- */
    /* 3.  Edge cases for the static hex(int) utility                         */
    /* ---------------------------------------------------------------------- */

    @Test
    public void testHex_PositiveValues() {
        Assert.assertEquals("0", CharSequenceTranslator.hex(0));
        Assert.assertEquals("A", CharSequenceTranslator.hex(10));
        Assert.assertEquals("10", CharSequenceTranslator.hex(16));
        Assert.assertEquals("FF", CharSequenceTranslator.hex(255));
        Assert.assertEquals("1F600", CharSequenceTranslator.hex(0x1F600));
    }

    @Test
    public void testHex_NegativeValue() {
        // Integer.toHexString returns the two's‑complement representation.
        // The method does not guard against negative numbers – we just verify the behaviour.
        Assert.assertEquals(Integer.toHexString(-1).toUpperCase(Locale.ENGLISH),
                CharSequenceTranslator.hex(-1));
    }

    @Test
    public void testHex_LocaleIndependence() {
        Locale defaultLocale = Locale.getDefault();
        try {
            Locale.setDefault(Locale.FRENCH);
            // hex must still be upper case English regardless of default locale
            Assert.assertEquals("ABCDEF", CharSequenceTranslator.hex(0xABCDEF));
        } finally {
            Locale.setDefault(defaultLocale);
        }
    }
}

package org.apache.commons.lang3.text.translate;

import static org.junit.Assert.*;

import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.util.Locale;

import org.junit.Test;

/**
 * JUnit4 test cases for {@link CharSequenceTranslator}.
 * <p>
 * The tests use a small concrete implementation of {@link CharSequenceTranslator}
 * that allows us to verify the behaviour of the abstract class methods:
 * <ul>
 *   <li>{@link #translate(CharSequence)}</li>
 *   <li>{@link #translate(CharSequence, Writer)}</li>
 *   <li>{@link #with(CharSequenceTranslator...)} (merging)</li>
 *   <li>{@link #hex(int)}</li>
 * </ul>
 * The concrete translators are deliberately simple but cover the
 * edge‑cases required by the contract (null handling, surrogate pairs,
 * zero‑consumption, etc.).
 * </p>
 */
public class CharSequenceTranslatorTest {

    /**
     * Simple translator that replaces the character 'a' (U+0061) with the string "b".
     * It consumes exactly one code point when the match is found and writes
     * the replacement; otherwise it returns 0 to let the base class write the
     * original character(s).
     */
    private static class SimpleATranslator extends CharSequenceTranslator {
        @Override
        public int translate(CharSequence input, int index, Writer out) throws IOException {
            if (input.charAt(index) == 'a') {
                out.write('b');
                return 1; // consumed one code point
            }
            return 0; // let the base class write the original character
        }
    }

    /**
     * Translator that consumes two code points (a surrogate pair) and writes a fixed string.
     * Used to verify that the algorithm correctly advances the index when a translator
     * consumes more than one code point.
     */
    private static class SurrogatePairTranslator extends CharSequenceTranslator {
        private static final String REPLACEMENT = "<SMILE>";

        @Override
        public int translate(CharSequence input, int index, Writer out) throws IOException {
            // Check if there are at least two code units and they form a surrogate pair
            if (index + 1 < input.length()
                    && Character.isHighSurrogate(input.charAt(index))
                    && Character.isLowSurrogate(input.charAt(index + 1))) {
                out.write(REPLACEMENT);
                // Consumed a single *code point* (the pair)
                return 1;
            }
            return 0;
        }
    }

    /**
     * Translator that always consumes the current code point and writes its hex value.
     * Used for testing the {@code with(...)} merger (order of translators).
     */
    private static class HexTranslator extends CharSequenceTranslator {
        @Override
        public int translate(CharSequence input, int index, Writer out) throws IOException {
            int cp = Character.codePointAt(input, index);
            out.write(CharSequenceTranslator.hex(cp));
            return Character.charCount(cp);
        }
    }

    // -------------------------------------------------------------------------
    // Tests for translate(CharSequence)
    // -------------------------------------------------------------------------

    @Test
    public void testTranslateString_nullInput_returnsNull() {
        CharSequenceTranslator translator = new SimpleATranslator();
        assertNull("translate(null) should return null", translator.translate((CharSequence) null));
    }

    @Test
    public void testTranslateString_simpleReplacement() {
        CharSequenceTranslator translator = new SimpleATranslator();
        String result = translator.translate("abracadabra");
        assertEquals("bbrbcbdbbrb", result);
    }

    @Test
    public void testTranslateString_noReplacement() {
        CharSequenceTranslator translator = new SimpleATranslator();
        String input = "xyz";
        assertSame("When no characters are replaced, output should equal input", input, translator.translate(input));
    }

    @Test
    public void testTranslateString_surrogatePairHandled() {
        CharSequenceTranslator translator = new SurrogatePairTranslator();
        // U+1F600 (GRINNING FACE) = surrogate pair "\uD83D\uDE00"
        String input = "\uD83D\uDE00xyz";
        String expected = "<SMILE>xyz";
        assertEquals(expected, translator.translate(input));
    }

    // -------------------------------------------------------------------------
    // Tests for translate(CharSequence, Writer)
    // -------------------------------------------------------------------------

    @Test(expected = IllegalArgumentException.class)
    public void testTranslateWriter_nullWriter_throwsException() throws IOException {
        CharSequenceTranslator translator = new SimpleATranslator();
        translator.translate("abc", null);
    }

    @Test
    public void testTranslateWriter_nullInput_noOutput() throws IOException {
        CharSequenceTranslator translator = new SimpleATranslator();
        StringWriter out = new StringWriter();
        translator.translate((CharSequence) null, out);
        assertEquals("", out.toString());
    }

    @Test
    public void testTranslateWriter_consumeZeroWritesOriginalChar() throws IOException {
        CharSequenceTranslator translator = new SimpleATranslator();
        StringWriter out = new StringWriter();
        translator.translate("xyz", out);
        assertEquals("xyz", out.toString());
    }

    @Test
    public void testTranslateWriter_consumeOneReplacesChar() throws IOException {
        CharSequenceTranslator translator = new SimpleATranslator();
        StringWriter out = new StringWriter();
        translator.translate("a", out);
        assertEquals("b", out.toString());
    }

    @Test
    public void testTranslateWriter_multipleCodePointsAndSurrogates() throws IOException {
        // Combine two translators: first handles surrogate pair, then simple 'a' replacement.
        CharSequenceTranslator combined = new SurrogatePairTranslator().with(new SimpleATranslator());

        // Input: surrogate pair (😀), 'a', and normal chars.
        String input = "\uD83D\uDE00aXYZ";
        StringWriter out = new StringWriter();
        combined.translate(input, out);

        // Expected: "<SMILE>" replaces 😀, 'a' -> 'b', rest unchanged.
        assertEquals("<SMILE>bXYZ", out.toString());
    }

    @Test
    public void testTranslateWriter_consumedMultipleCodePoints() throws IOException {
        CharSequenceTranslator translator = new CharSequenceTranslator() {
            @Override
            public int translate(CharSequence input, int index, Writer out) throws IOException {
                // Consume two code points (two BMP characters) and write a marker.
                if (index + 1 < input.length()) {
                    out.write("[AB]");
                    return 2;
                }
                return 0;
            }
        };

        StringWriter out = new StringWriter();
        translator.translate("ABCD", out);
        // Consumed AB -> [AB], then CD -> [AB]
        assertEquals("[AB][AB]", out.toString());
    }

    // -------------------------------------------------------------------------
    // Tests for with(...)
    // -------------------------------------------------------------------------

    @Test
    public void testWith_MergesTranslatorsInCorrectOrder() {
        // First translator: replace 'x' with "1"
        CharSequenceTranslator t1 = new CharSequenceTranslator() {
            @Override
            public int translate(CharSequence input, int index, Writer out) throws IOException {
                if (input.charAt(index) == 'x') {
                    out.write('1');
                    return 1;
                }
                return 0;
            }
        };
        // Second translator: replace 'y' with "2"
        CharSequenceTranslator t2 = new CharSequenceTranslator() {
            @Override
            public int translate(CharSequence input, int index, Writer out) throws IOException {
                if (input.charAt(index) == 'y') {
                    out.write('2');
                    return 1;
                }
                return 0;
            }
        };
        CharSequenceTranslator merged = t1.with(t2);
        String result = merged.translate("xyzyx");
        // Expected order: t1 handles 'x', t2 handles 'y'
        assertEquals("12z21", result);
    }

    @Test
    public void testWith_EmptyArrayReturnsOriginalTranslator() {
        CharSequenceTranslator original = new SimpleATranslator();
        CharSequenceTranslator merged = original.with();
        assertNotSame("with() with no arguments should still return a new instance", original, merged);
        // Behaviour should be identical to the original
        assertEquals(original.translate("a"), merged.translate("a"));
    }

    // -------------------------------------------------------------------------
    // Tests for hex(int)
    // -------------------------------------------------------------------------

    @Test
    public void testHex_basicValues() {
        assertEquals("0", CharSequenceTranslator.hex(0));
        assertEquals("A", CharSequenceTranslator.hex(10));
        assertEquals("1F", CharSequenceTranslator.hex(31));
        assertEquals("FF", CharSequenceTranslator.hex(255));
        assertEquals("10", CharSequenceTranslator.hex(16));
    }

    @Test
    public void testHex_upperCaseAndLocaleIndependence() {
        // Force a non‑English default locale to ensure the method uses ENGLISH explicitly
        Locale defaultLocale = Locale.getDefault();
        try {
            Locale.setDefault(Locale.FRENCH);
            assertEquals("ABCDEF", CharSequenceTranslator.hex(0xABCDEF));
        } finally {
            Locale.setDefault(defaultLocale);
        }
    }

    @Test
    public void testHex_negativeCodepoint() {
        // Integer.toHexString produces a 2's‑complement representation; we just verify the contract.
        assertEquals(Integer.toHexString(-1).toUpperCase(Locale.ENGLISH), CharSequenceTranslator.hex(-1));
    }

    // -------------------------------------------------------------------------
    // Additional sanity test: ensure translate(CharSequence) uses StringWriter correctly
    // -------------------------------------------------------------------------

    @Test
    public void testTranslateString_usesStringWriterCapacity() {
        // The capacity is input.length() * 2; we verify that a large replacement does not overflow.
        CharSequenceTranslator translator = new CharSequenceTranslator() {
            @Override
            public int translate(CharSequence input, int index, Writer out) throws IOException {
                out.write("REPLACEMENT");
                return 1; // consume the original single code point
            }
        };
        String longInput = "aaaaaaaaaa"; // 10 chars
        String result = translator.translate(longInput);
        assertEquals("REPLACEMENT".repeat(10), result);
    }
}

/**
 * JUnit 4 test suite for {@link org.apache.commons.lang3.text.translate.CharSequenceTranslator}.
 *
 * The tests cover:
 *  <ul>
 *      <li>All public methods of {@code CharSequenceTranslator}</li>
 *      <li>Typical usage scenarios</li>
 *      <li>Edge‑case handling (nulls, empty strings, surrogate pairs, zero‑consumption)</li>
 *      <li>Exception paths (null Writer, IOExceptions from a custom Writer)</li>
 *  </ul>
 *
 * The abstract {@code translate(CharSequence,int,Writer)} method is exercised via
 * simple concrete subclasses defined within this test class.
 */
package org.apache.commons.lang3.text.translate;

import static org.junit.Assert.*;

import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.util.Locale;

import org.junit.Test;
import org.junit.rules.ExpectedException;
import org.junit.Rule;

/**
 * Test class for {@link CharSequenceTranslator}.
 */
public class CharSequenceTranslatorTest {

    // -------------------------------------------------------------------------
    // Helper concrete translators used by the tests
    // -------------------------------------------------------------------------

    /**
     * Simple translator that replaces every occurrence of the character {@code 'a'}
     * with the string {@code "b"}.
     */
    private static class AtoBTranslator extends CharSequenceTranslator {
        @Override
        public int translate(CharSequence input, int index, Writer out) throws IOException {
            if (input.charAt(index) == 'a') {
                out.write('b');
                return 1; // consumed one code‑point
            }
            return 0; // let the base class copy the character unchanged
        }
    }

    /**
     * Translator that replaces the Unicode code‑point U+1F600 (GRINNING FACE) with
     * the smiley string {@code ":)"}.
     * Demonstrates handling of surrogate pairs.
     */
    private static class EmojiToSmileyTranslator extends CharSequenceTranslator {
        private static final int GRINNING_FACE = 0x1F600; // 😀
        @Override
        public int translate(CharSequence input, int index, Writer out) throws IOException {
            int cp = Character.codePointAt(input, index);
            if (cp == GRINNING_FACE) {
                out.write(":)");
                // The code point occupies two char units (a surrogate pair)
                return Character.charCount(cp);
            }
            return 0;
        }
    }

    /**
     * Translator that deliberately throws an {@link IOException} when its
     * {@code translate} method is invoked. Used to test exception propagation.
     */
    private static class FailingTranslator extends CharSequenceTranslator {
        @Override
        public int translate(CharSequence input, int index, Writer out) throws IOException {
            throw new IOException("forced failure");
        }
    }

    // -------------------------------------------------------------------------
    // Tests for the concrete abstract method (via subclasses)
    // -------------------------------------------------------------------------

    @Test
    public void testAtoBTranslator_basicTranslation() throws IOException {
        CharSequenceTranslator tr = new AtoBTranslator();
        StringWriter out = new StringWriter();
        int consumed = tr.translate("abracadabra", 0, out);
        // first char is 'a' -> should be replaced with 'b' and consume 1 code‑point
        assertEquals(1, consumed);
        assertEquals("b", out.toString());
    }

    @Test
    public void testAtoBTranslator_noTranslationReturnsZero() throws IOException {
        CharSequenceTranslator tr = new AtoBTranslator();
        StringWriter out = new StringWriter();
        int consumed = tr.translate("xyz", 0, out);
        // 'x' is not handled, translator must return 0
        assertEquals(0, consumed);
        // Writer must remain unchanged because the calling algorithm (in translate)
        // will copy the original character when 0 is returned.
        assertEquals("", out.toString());
    }

    // -------------------------------------------------------------------------
    // Tests for CharSequenceTranslator.translate(CharSequence) – the String helper
    // -------------------------------------------------------------------------

    @Test
    public void testTranslateStringHelper_nullInput() {
        CharSequenceTranslator tr = new AtoBTranslator();
        assertNull(tr.translate((CharSequence) null));
    }

    @Test
    public void testTranslateStringHelper_simpleReplacement() {
        CharSequenceTranslator tr = new AtoBTranslator();
        String result = tr.translate("banana");
        // a -> b, so "banana" becomes "bbnbnb"
        assertEquals("bbnbnb", result);
    }

    @Test
    public void testTranslateStringHelper_emojiReplacement() {
        CharSequenceTranslator tr = new EmojiToSmileyTranslator();
        String input = "\uD83D\uDE00"; // 😀 (surrogate pair)
        String result = tr.translate(input);
        assertEquals(":)", result);
    }

    // -------------------------------------------------------------------------
    // Tests for CharSequenceTranslator.translate(CharSequence, Writer)
    // -------------------------------------------------------------------------

    @Test
    public void testTranslateToWriter_nullWriterThrows() throws IOException {
        CharSequenceTranslator tr = new AtoBTranslator();
        try {
            tr.translate("test", null);
            fail("Expected IllegalArgumentException for null Writer");
        } catch (IllegalArgumentException e) {
            assertEquals("The Writer must not be null", e.getMessage());
        }
    }

    @Test
    public void testTranslateToWriter_nullInputDoesNothing() throws IOException {
        CharSequenceTranslator tr = new AtoBTranslator();
        StringWriter out = new StringWriter();
        tr.translate(null, out);
        // No exception, writer remains empty
        assertEquals("", out.toString());
    }

    @Test
    public void testTranslateToWriter_fullAlgorithm_simple() throws IOException {
        CharSequenceTranslator tr = new AtoBTranslator();
        StringWriter out = new StringWriter();
        tr.translate("abracadabra", out);
        // a->b, rest unchanged
        assertEquals("bbrbcbdbbrb", out.toString());
    }

    @Test
    public void testTranslateToWriter_zeroConsumptionCopiesOriginalChar() throws IOException {
        CharSequenceTranslator tr = new CharSequenceTranslator() {
            @Override
            public int translate(CharSequence input, int index, Writer out) {
                // never consume; always return 0
                return 0;
            }
        };
        StringWriter out = new StringWriter();
        tr.translate("xyz", out);
        // The base algorithm should copy the original input unchanged
        assertEquals("xyz", out.toString());
    }

    @Test
    public void testTranslateToWriter_surrogatePairHandling() throws IOException {
        CharSequenceTranslator tr = new EmojiToSmileyTranslator();
        StringWriter out = new StringWriter();
        // Input contains a surrogate pair (😀) followed by a normal char
        String input = "\uD83D\uDE00a";
        tr.translate(input, out);
        // Emoji replaced, 'a' left untouched (because this translator does not handle it)
        assertEquals(":)a", out.toString());
    }

    @Test
    public void testTranslateToWriter_propagatesIOException() throws IOException {
        CharSequenceTranslator tr = new FailingTranslator();
        Writer failingWriter = new Writer() {
            @Override public void write(char[] cbuf, int off, int len) {}
            @Override public void flush() {}
            @Override public void close() {}
            @Override public void write(int c) throws IOException {
                throw new IOException("writer failure");
            }
        };
        try {
            tr.translate("any", failingWriter);
            fail("Expected IOException from translator");
        } catch (IOException e) {
            assertEquals("forced failure", e.getMessage());
        }
    }

    // -------------------------------------------------------------------------
    // Tests for CharSequenceTranslator.with(...)
    // -------------------------------------------------------------------------

    @Test
    public void testWith_mergesTranslatorsInCorrectOrder() {
        CharSequenceTranslator aToB = new AtoBTranslator(); // a -> b
        CharSequenceTranslator bToC = new CharSequenceTranslator() {
            @Override
            public int translate(CharSequence input, int index, Writer out) throws IOException {
                if (input.charAt(index) == 'b') {
                    out.write('c');
                    return 1;
                }
                return 0;
            }
        }; // b -> c

        CharSequenceTranslator merged = aToB.with(bToC); // a -> b then b -> c

        String result = merged.translate("ababa");
        // Step 1: a->b, b stays b, a->b, b stays b, a->b => "bbbbb"
        // Step 2 (bToC) runs after aToB: all 'b' become 'c' => "ccccc"
        assertEquals("ccccc", result);
    }

    @Test
    public void testWith_withNoAdditionalTranslatorsReturnsSameInstanceWrapped() {
        CharSequenceTranslator aToB = new AtoBTranslator();
        CharSequenceTranslator merged = aToB.with(); // no extra translators
        assertNotSame(aToB, merged); // should be a new AggregateTranslator
        // Behaviour must be identical to the original
        assertEquals(aToB.translate("aaa"), merged.translate("aaa"));
    }

    // -------------------------------------------------------------------------
    // Tests for static CharSequenceTranslator.hex(int)
    // -------------------------------------------------------------------------

    @Test
    public void testHex_basicValues() {
        assertEquals("0", CharSequenceTranslator.hex(0));
        assertEquals("1A", CharSequenceTranslator.hex(0x1A));
        assertEquals("FF", CharSequenceTranslator.hex(255));
        assertEquals("7FFFFFFF", CharSequenceTranslator.hex(Integer.MAX_VALUE));
    }

    @Test
    public void testHex_negativeValue() {
        // Integer.toHexString(-1) => "ffffffff", upper‑cased => "FFFFFFFF"
        assertEquals("FFFFFFFF", CharSequenceTranslator.hex(-1));
    }

    @Test
    public void testHex_localeIndependence() {
        Locale defaultLocale = Locale.getDefault();
        try {
            Locale.setDefault(Locale.FRENCH);
            assertEquals("ABCDEF", CharSequenceTranslator.hex(0xABCDEF));
        } finally {
            Locale.setDefault(defaultLocale);
        }
    }
}

