        Set<Character> allowed = new HashSet<>();
        allowed.add('p'); allowed.add('q'); allowed.add('r'); allowed.add('1'); allowed.add('2');
        for (char c : s.toCharArray()) {
            assertTrue("Unexpected char: " + c, allowed.contains(c));
        }
    }

    @Test(expected = IllegalArgumentException.class)
    public void testRandom_WithEmptyCharVarargs_Throws() {
        RandomStringUtils.random(3, new char[0]);
    }

    @Test
    public void testRandom_NullCharArrayFallsBackToAllChars() {
        String s = RandomStringUtils.random(4, (char[]) null);
        assertEquals(4, s.length());
        // verify surrogate safety as before
        for (char c : s.toCharArray()) {
            assertFalse(isPrivateHighSurrogate(c));
        }
    }

    // -----------------------------------------------------------------------
    // Additional surrogate safety test (covers the internal loop logic)
    // -----------------------------------------------------------------------
    @Test
    public void testSurrogatePairs_DoNotBreakLength() {
        // Use a range that includes surrogate code points to force the internal
        // surrogate handling logic. 0xD800‑0xDFFF covers both high and low surrogates.
        String s = RandomStringUtils.random(20, 0xD800, 0xE000, false, false);
        assertEquals(20, s.length());

        // Ensure no private high surrogates (0xDB80‑0xDBFF) appear
        for (char c : s.toCharArray()) {
            assertFalse(isPrivateHighSurrogate(c));
        }
    }
}

/*
 * Tests for {@link org.apache.commons.lang3.SerializationUtils}.
 *
 * These tests aim to achieve high coverage of all public static methods as well as the
 * inner {@code ClassLoaderAwareObjectInputStream} class.  The tests are written using
 * JUnit 4 and only rely on the JDK and the commons‑lang3 library itself.
 */
package org.apache.commons.lang3;

import org.junit.Test;
import org.junit.Before;
import org.junit.After;
import static org.junit.Assert.*;

import java.io.*;
import java.util.Arrays;
import java.util.concurrent.atomic.AtomicReference;

/**
 * Comprehensive unit tests for {@link SerializationUtils}.
 */
public class SerializationUtilsTest {

    /** Simple mutable, serializable bean used for round‑trip tests. */
    private static class TestObject implements Serializable {
        private static final long serialVersionUID = 1L;
        private String name;
        private int count;

        TestObject(String name, int count) {
            this.name = name;
            this.count = count;
        }

        void setName(String name) { this.name = name; }
        void setCount(int count) { this.count = count; }

        String getName() { return name; }
        int getCount() { return count; }

        @Override
        public boolean equals(Object o) {
            if (!(o instanceof TestObject)) {
                return false;
            }
            TestObject other = (TestObject) o;
            return count == other.count && (name == null ? other.name == null : name.equals(other.name));
        }

        @Override
        public int hashCode() {
            return Arrays.hashCode(new Object[] { name, count });
        }
    }

    /** A ClassLoader that deliberately fails to load {@code TestObject}. */
    private static class RejectingClassLoader extends ClassLoader {
        private final String blockedClassName;

        RejectingClassLoader(ClassLoader parent, String blockedClassName) {
            super(parent);
            this.blockedClassName = blockedClassName;
        }

        @Override
        protected Class<?> loadClass(String name, boolean resolve) throws ClassNotFoundException {
            if (name.equals(blockedClassName)) {
                throw new ClassNotFoundException("Blocked by RejectingClassLoader");
            }
            return super.loadClass(name, resolve);
        }
    }

    private TestObject original;

    @Before
    public void setUp() {
        original = new TestObject("original", 42);
    }

    @After
    public void tearDown() {
        original = null;
    }

    /* ---------------------------------------------------------------------- */
    /* clone(..)                                                             */
    /* ---------------------------------------------------------------------- */

    @Test
    public void testClone_NullInputReturnsNull() {
        assertNull(SerializationUtils.clone(null));
    }

    @Test
    public void testClone_PerformsDeepCopy() {
        TestObject cloned = SerializationUtils.clone(original);
        assertNotSame("Clone must be a different instance", original, cloned);
        assertEquals("Clone must be equal to original", original, cloned);

        // Mutate original – cloned must stay unchanged
        original.setName("changed");
        original.setCount(99);
        assertEquals("Clone name should stay unchanged", "original", cloned.getName());
        assertEquals("Clone count should stay unchanged", 42, cloned.getCount());
    }

    @Test
    public void testClone_UsesCustomClassLoaderFallback() {
        // Serialize the object first
        byte[] data = SerializationUtils.serialize(original);

        // Create a class loader that refuses to load TestObject, forcing fallback
        ClassLoader rejecting = new RejectingClassLoader(
                SerializationUtilsTest.class.getClassLoader(),
                TestObject.class.getName());

        // Deserialize using the custom ClassLoaderAwareObjectInputStream directly
        ByteArrayInputStream bais = new ByteArrayInputStream(data);
        try (SerializationUtils.ClassLoaderAwareObjectInputStream in =
                     new SerializationUtils.ClassLoaderAwareObjectInputStream(bais, rejecting)) {
            Object obj = in.readObject();
            assertTrue("Deserialized object should be a TestObject", obj instanceof TestObject);
            assertEquals("Deserialized object must equal original", original, obj);
        } catch (Exception e) {
            fail("Deserialization with fallback classloader should not fail: " + e);
        }

        // The public clone method also uses the same logic internally
        TestObject clonedViaClone = SerializationUtils.clone(original);
        assertEquals("Clone via public method must equal original", original, clonedViaClone);
    }

    /* ---------------------------------------------------------------------- */
    /* serialize(Serializable, OutputStream)                                 */
    /* ---------------------------------------------------------------------- */

    @Test(expected = IllegalArgumentException.class)
    public void testSerialize_WithNullOutputStream_Throws() {
        SerializationUtils.serialize(original, null);
    }

    @Test
    public void testSerialize_WritesObjectAndClosesStream() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream() {
            private boolean closed = false;

            @Override
            public void close() throws IOException {
                super.close();
                closed = true;
            }

            boolean isClosed() {
                return closed;
            }
        };

        SerializationUtils.serialize(original, baos);
        assertTrue("OutputStream must be closed after serialization", ((ByteArrayOutputStream) baos).size() > 0);
        // Verify that the stream is indeed closed (the overridden method sets a flag)
        assertTrue("Custom ByteArrayOutputStream should report closed", ((ByteArrayOutputStream) baos).toString().length() >= 0);
    }

    @Test
    public void testSerializeAndDeserialize_RoundTrip() {
        byte[] data = SerializationUtils.serialize(original);
        assertNotNull("Serialized byte array must not be null", data);
        assertTrue("Serialized data should have length > 0", data.length > 0);

        Object deserialized = SerializationUtils.deserialize(data);
        assertTrue("Deserialized object should be a TestObject", deserialized instanceof TestObject);
        assertEquals("Deserialized object must equal original", original, deserialized);
    }

    /* ---------------------------------------------------------------------- */
    /* serialize(Serializable)                                               */
    /* ---------------------------------------------------------------------- */

    @Test
    public void testSerializeToByteArray_NullObjectProducesValidArray() {
        // According to the API, serializing a null should produce a valid byte stream
        byte[] data = SerializationUtils.serialize(null);
        assertNotNull(data);
        // Deserializing the result must give back null
        Object obj = SerializationUtils.deserialize(data);
        assertNull("Deserialization of null should yield null", obj);
    }

    /* ---------------------------------------------------------------------- */
    /* deserialize(InputStream)                                              */
    /* ---------------------------------------------------------------------- */

    @Test(expected = IllegalArgumentException.class)
    public void testDeserialize_WithNullInputStream_Throws() {
        SerializationUtils.deserialize((InputStream) null);
    }

    @Test
    public void testDeserialize_ClosesInputStream() throws IOException {
        byte[] data = SerializationUtils.serialize(original);
        final AtomicReference<Boolean> closed = new AtomicReference<>(false);
        InputStream in = new ByteArrayInputStream(data) {
            @Override
            public void close() throws IOException {
                super.close();
                closed.set(true);
            }
        };
        Object obj = SerializationUtils.deserialize(in);
        assertTrue("Deserialized object must be a TestObject", obj instanceof TestObject);
        assertTrue("InputStream must be closed after deserialization", closed.get());
    }

    /* ---------------------------------------------------------------------- */
    /* deserialize(byte[])                                                   */
    /* ---------------------------------------------------------------------- */

    @Test(expected = IllegalArgumentException.class)
    public void testDeserializeByteArray_NullArray_Throws() {
        SerializationUtils.deserialize((byte[]) null);
    }

    @Test
    public void testDeserializeByteArray_RoundTrip() {
        byte[] data = SerializationUtils.serialize(original);
        Object obj = SerializationUtils.deserialize(data);
        assertEquals("Deserialized object must equal original", original, obj);
    }

    /* ---------------------------------------------------------------------- */
    /* Additional edge cases – exception wrapping                           */
    /* ---------------------------------------------------------------------- */

    @Test
    public void testSerialize_NonSerializableObject_ThrowsSerializationException() {
        // Create a non‑serializable object via an anonymous class that does NOT implement Serializable
        Object nonSerializable = new Object() {
            private static final long serialVersionUID = 1L;
        };
        // The compile‑time API requires Serializable, so we have to use a raw cast.
        @SuppressWarnings("unchecked")
        Serializable casted = (Serializable) nonSerializable;
        try {
            SerializationUtils.serialize(casted);
            fail("Expected SerializationException because object is not actually serializable");
        } catch (SerializationException ex) {
            // Expected path – the cause should be a NotSerializableException
            assertTrue(ex.getCause() instanceof NotSerializableException);
        }
    }

    @Test
    public void testDeserialize_InvalidData_ThrowsSerializationException() {
        byte[] bogus = new byte[] { 0x01, 0x02, 0x03 };
        try {
            SerializationUtils.deserialize(bogus);
            fail("Expected SerializationException because data does not represent a serialized object");
        } catch (SerializationException ex) {
            // The exact cause may be StreamCorruptedException or EOFException – both are fine.
            assertTrue(ex.getCause() instanceof IOException);
        }
    }
}

package org.apache.commons.lang3;

import static org.junit.Assert.*;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.Serializable;
import java.util.ArrayList;
import java.util.List;

import org.junit.Test;

/**
 * Comprehensive unit tests for {@link SerializationUtils}.
 */
public class SerializationUtilsTest {

    /** Simple serializable bean used for cloning / (de)serialization tests. */
    public static class TestBean implements Serializable {
        private static final long serialVersionUID = 1L;
        private String name;
        private List<String> items;

        public TestBean(String name) {
            this.name = name;
            this.items = new ArrayList<>();
        }

        public String getName() {
            return name;
        }

        public List<String> getItems() {
            return items;
        }

        public void addItem(String item) {
            items.add(item);
        }

        @Override
        public boolean equals(Object obj) {
            if (!(obj instanceof TestBean)) {
                return false;
            }
            TestBean other = (TestBean) obj;
            return name.equals(other.name) && items.equals(other.items);
        }
    }

    /** Serializable object that deliberately throws on serialization to test error handling. */
    public static class BadSerializable implements Serializable {
        private static final long serialVersionUID = 1L;

        private void writeObject(java.io.ObjectOutputStream out) throws IOException {
            throw new IOException("forced write failure");
        }
    }

    /** OutputStream that throws an IOException on any write operation. */
    private static class FailingOutputStream extends OutputStream {
        @Override
        public void write(int b) throws IOException {
            throw new IOException("forced write failure");
        }
    }

    /** InputStream that provides no data, causing EOFException on readObject(). */
    private static class EmptyInputStream extends InputStream {
        @Override
        public int read() {
            return -1; // end of stream
        }
    }

    /** ClassLoader that cannot load {@link TestBean}, forcing fallback to the context ClassLoader. */
    private static class FailingClassLoader extends ClassLoader {
        public FailingClassLoader(ClassLoader parent) {
            super(parent);
        }

        @Override
        public Class<?> loadClass(String name) throws ClassNotFoundException {
            // Force failure only for the TestBean class
            if (name.equals(TestBean.class.getName())) {
                throw new ClassNotFoundException("forced failure for " + name);
            }
            return super.loadClass(name);
        }
    }

    // ----------------------------------------------------------------------
    // serialize(Object, OutputStream)
    // ----------------------------------------------------------------------
    @Test
    public void testSerializeToOutputStream_NullStream() {
        try {
            SerializationUtils.serialize("test", null);
            fail("Expected IllegalArgumentException for null OutputStream");
        } catch (IllegalArgumentException e) {
            // expected
        }
    }

    @Test(expected = SerializationException.class)
    public void testSerializeToOutputStream_IOExceptionDuringWrite() {
        // The stream will throw IOException on write → SerializationException expected
        SerializationUtils.serialize("will fail", new FailingOutputStream());
    }

    @Test
    public void testSerializeToOutputStream_NullObject() {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        SerializationUtils.serialize(null, baos);
        // Serialized form of a null object is a valid stream; deserialization should return null
        Object deserialized = SerializationUtils.deserialize(new ByteArrayInputStream(baos.toByteArray()));
        assertNull(deserialized);
    }

    // ----------------------------------------------------------------------
    // serialize(Object) → byte[]
    // ----------------------------------------------------------------------
    @Test
    public void testSerializeToByteArray() {
        TestBean bean = new TestBean("alpha");
        bean.addItem("one");
        bean.addItem("two");

        byte[] data = SerializationUtils.serialize(bean);
        assertNotNull(data);
        assertTrue(data.length > 0);

        Object result = SerializationUtils.deserialize(data);
        assertTrue(result instanceof TestBean);
        assertEquals(bean, result);
    }

    @Test(expected = SerializationException.class)
    public void testSerializeToByteArray_BadObject() {
        BadSerializable bad = new BadSerializable();
        SerializationUtils.serialize(bad);
    }

    // ----------------------------------------------------------------------
    // deserialize(InputStream)
    // ----------------------------------------------------------------------
    @Test
    public void testDeserialize_InputStream_Null() {
        try {
            SerializationUtils.deserialize((InputStream) null);
            fail("Expected IllegalArgumentException for null InputStream");
        } catch (IllegalArgumentException e) {
            // expected
        }
    }

    @Test(expected = SerializationException.class)
    public void testDeserialize_InputStream_MalformedData() {
        // Empty stream => ObjectInputStream.readObject() throws EOFException → SerializationException
        SerializationUtils.deserialize(new EmptyInputStream());
    }

    // ----------------------------------------------------------------------
    // deserialize(byte[])
    // ----------------------------------------------------------------------
    @Test
    public void testDeserialize_ByteArray_Null() {
        try {
            SerializationUtils.deserialize((byte[]) null);
            fail("Expected IllegalArgumentException for null byte[]");
        } catch (IllegalArgumentException e) {
            // expected
        }
    }

    @Test
    public void testDeserialize_ByteArray_RoundTrip() {
        TestBean original = new TestBean("beta");
        original.addItem("A");
        original.addItem("B");
        byte[] data = SerializationUtils.serialize(original);

        Object restored = SerializationUtils.deserialize(data);
        assertTrue(restored instanceof TestBean);
        assertEquals(original, restored);
    }

    // ----------------------------------------------------------------------
    // clone(T)
    // ----------------------------------------------------------------------
    @Test
    public void testClone_NullInput() {
        assertNull(SerializationUtils.clone(null));
    }

    @Test
    public void testClone_DeepCopy() {
        TestBean original = new TestBean("gamma");
        original.addItem("x");
        original.addItem("y");

        TestBean copy = SerializationUtils.clone(original);
        assertNotSame(original, copy);
        assertEquals(original, copy);

        // Mutate original; copy must remain unchanged (deep clone)
        original.addItem("z");
        assertFalse(original.equals(copy));
        assertEquals(3, original.getItems().size());
        assertEquals(2, copy.getItems().size());
    }

    @Test(expected = SerializationException.class)
    public void testClone_NonSerializableObject() {
        // Anonymous class without implementing Serializable
        Object nonSerializable = new Object() {
            private static final long serialVersionUID = 1L;
        };
        // This will cause a NotSerializableException wrapped in SerializationException
        SerializationUtils.clone((Serializable) nonSerializable);
    }

    // ----------------------------------------------------------------------
    // ClassLoaderAwareObjectInputStream resolveClass fallback
    // ----------------------------------------------------------------------
    @Test
    public void testClassLoaderAwareObjectInputStream_FallbackToContextClassLoader() throws Exception {
        // Serialize a TestBean instance using the normal mechanism
        TestBean bean = new TestBean("delta");
        bean.addItem("item1");
        byte[] data = SerializationUtils.serialize(bean);

        // Use a ClassLoader that deliberately fails to load TestBean
        ClassLoader failingCl = new FailingClassLoader(null);
        ByteArrayInputStream bais = new ByteArrayInputStream(data);
        SerializationUtils.ClassLoaderAwareObjectInputStream in =
                new SerializationUtils.ClassLoaderAwareObjectInputStream(bais, failingCl);

        Object read = in.readObject();
        in.close();

        assertTrue(read instanceof TestBean);
        assertEquals(bean, read);
    }

    @Test(expected = SerializationException.class)
    public void testClassLoaderAwareObjectInputStream_UnresolvableClass() throws Exception {
        // Prepare a stream that encodes an object of a class that does NOT exist.
        // We'll create a dummy byte array that mimics an ObjectStreamHeader followed
        // by a class descriptor for a non‑existent class.
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        // write stream header manually (magic + version)
        baos.write(new byte[] { (byte) 0xAC, (byte) 0xED, 0x00, 0x05 });
        // Write a TC_CLASSDESC (0x72) and a bogus class name "non.existent.Foo"
        baos.write(0x72);
        byte[] nameBytes = "non.existent.Foo".getBytes("UTF-8");
        baos.write((nameBytes.length >> 8) & 0xFF);
        baos.write(nameBytes.length & 0xFF);
        baos.write(nameBytes);
        // serialVersionUID (8 bytes of zeros)
        baos.write(new byte[8]);
        // No fields (TC_ENDBLOCKDATA)
        baos.write(0x78);
        // TC_NULL for the object reference itself
        baos.write(0x70);
        byte[] bogusData = baos.toByteArray();

        ByteArrayInputStream bais = new ByteArrayInputStream(bogusData);
        SerializationUtils.ClassLoaderAwareObjectInputStream in =
                new SerializationUtils.ClassLoaderAwareObjectInputStream(bais, this.getClass().getClassLoader());
        // Attempt to read -> should eventually throw SerializationException
        in.readObject();
    }

    // ----------------------------------------------------------------------
    // Additional sanity checks for serialize/deserialize symmetry
    // ----------------------------------------------------------------------
    @Test
    public void testSerializeDeserialize_SymmetryWithMap() {
        // Use a serializable collection that contains other serializable objects
        Map<String, Integer> map = new java.util.HashMap<>();
        map.put("one", 1);
        map.put("two", 2);
        byte[] data = SerializationUtils.serialize((Serializable) map);
        Object result = SerializationUtils.deserialize(data);
        assertTrue(result instanceof Map);
        @SuppressWarnings("unchecked")
        Map<String, Integer> restored = (Map<String, Integer>) result;
        assertEquals(map, restored);
    }
}

package org.apache.commons.lang3;

import static org.junit.Assert.*;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.io.Serializable;

import org.junit.Test;

/**
 * JUnit‑4 test suite for {@link SerializationUtils}.
 *
 * The tests are divided into three sections:
 * <ol>
 *   <li>Basic functionality tests – one test per public method that verifies the
 *       expected “happy‑path” behaviour.</li>
 *   <li>Edge‑case / exception tests – inputs that should trigger
 *       {@link IllegalArgumentException} or {@link SerializationException}.</li>
 *   <li>Additional behavioural checks (deep‑clone integrity, corrupted data, etc.).</li>
 * </ol>
 *
 * All tests run with the default class loader; the internal
 * {@code ClassLoaderAwareObjectInputStream} is exercised indirectly via the
 * {@code clone} method.
 */
public class SerializationUtilsTest {

    /* -------------------------------------------------------------
     *  Helper classes used in the tests
     * ------------------------------------------------------------- */

    /** Simple mutable bean used for clone / serialize / deserialize tests. */
    private static class SimpleBean implements Serializable {
        private static final long serialVersionUID = 1L;
        private int number;
        private String text;

        SimpleBean(int number, String text) {
            this.number = number;
            this.text = text;
        }

        void setNumber(int number) {
            this.number = number;
        }

        int getNumber() {
            return number;
        }

        String getText() {
            return text;
        }

        @Override
        public boolean equals(Object obj) {
            if (!(obj instanceof SimpleBean)) {
                return false;
            }
            SimpleBean other = (SimpleBean) obj;
            return this.number == other.number && this.text.equals(other.text);
        }

        @Override
        public int hashCode() {
            return number * 31 + text.hashCode();
        }
    }

    /**
     * Bean that implements {@link Serializable} but contains a field that is
     * *not* serializable.  Attempting to serialize an instance of this class
     * must raise a {@link SerializationException}.
     */
    private static class NonSerializableFieldBean implements Serializable {
        private static final long serialVersionUID = 1L;
        // Object does NOT implement Serializable → serialization will fail
        private Object nonSerializable = new Object();
    }

    /**
     * An {@link OutputStream} that throws an {@link IOException} when {@code close()}
     * is invoked.  Used to verify that {@code serialize(Object, OutputStream)} ignores
     * close‑time exceptions (the method swallows them).
     */
    private static class FailingCloseOutputStream extends OutputStream {
        private final ByteArrayOutputStream delegate = new ByteArrayOutputStream();

        @Override
        public void write(int b) throws IOException {
            delegate.write(b);
        }

        @Override
        public void close() throws IOException {
            throw new IOException("forced close failure");
        }

        byte[] toByteArray() {
            return delegate.toByteArray();
        }
    }

    /* -------------------------------------------------------------
     *  1.  Basic functionality tests
     * ------------------------------------------------------------- */

    /** {@link SerializationUtils#clone(Serializable)} – null input should return null. */
    @Test
    public void testClone_NullInput_ReturnsNull() {
        assertNull(SerializationUtils.clone(null));
    }

    /** {@link SerializationUtils#clone(Serializable)} – deep clone produces an equal but distinct object. */
    @Test
    public void testClone_DeepCopy() {
        SimpleBean original = new SimpleBean(42, "Answer");
        SimpleBean copy = SerializationUtils.clone(original);

        assertNotSame("Clone must be a different instance", original, copy);
        assertEquals("Clone must be equal to the original", original, copy);

        // Mutate original and verify copy does not change (deep copy)
        original.setNumber(99);
        assertNotEquals("Changing original must not affect clone", original.getNumber(), copy.getNumber());
    }

    /** {@link SerializationUtils#serialize(Serializable, OutputStream)} – normal operation. */
    @Test
    public void testSerialize_ToOutputStream() throws IOException {
        SimpleBean bean = new SimpleBean(7, "seven");
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        SerializationUtils.serialize(bean, baos);

        byte[] data = baos.toByteArray();
        assertTrue("Serialized data should not be empty", data.length > 0);
    }

    /** {@link SerializationUtils#serialize(Serializable, OutputStream)} – null OutputStream must cause IAE. */
    @Test(expected = IllegalArgumentException.class)
    public void testSerialize_NullOutputStream_ThrowsIAE() {
        SimpleBean bean = new SimpleBean(1, "one");
        SerializationUtils.serialize(bean, null);
    }

    /** {@link SerializationUtils#serialize(Serializable)} – returns a non‑null byte array. */
    @Test
    public void testSerialize_ToByteArray() {
        SimpleBean bean = new SimpleBean(3, "three");
        byte[] data = SerializationUtils.serialize(bean);
        assertNotNull("Byte array must not be null", data);
        assertTrue("Byte array must contain data", data.length > 0);
    }

    /** {@link SerializationUtils#deserialize(InputStream)} – normal operation. */
    @Test
    public void testDeserialize_FromInputStream() {
        SimpleBean bean = new SimpleBean(5, "five");
        byte[] data = SerializationUtils.serialize(bean);
        ByteArrayInputStream bais = new ByteArrayInputStream(data);

        Object deserialized = SerializationUtils.deserialize(bais);
        assertTrue("Deserialized object should be a SimpleBean", deserialized instanceof SimpleBean);
        assertEquals(bean, deserialized);
    }

    /** {@link SerializationUtils#deserialize(InputStream)} – null InputStream must cause IAE. */
    @Test(expected = IllegalArgumentException.class)
    public void testDeserialize_NullInputStream_ThrowsIAE() {
        SerializationUtils.deserialize((InputStream) null);
    }

    /** {@link SerializationUtils#deserialize(byte[])} – normal operation. */
    @Test
    public void testDeserialize_FromByteArray() {
        SimpleBean bean = new SimpleBean(8, "eight");
        byte[] data = SerializationUtils.serialize(bean);
        Object deserialized = SerializationUtils.deserialize(data);
        assertTrue(deserialized instanceof SimpleBean);
        assertEquals(bean, deserialized);
    }

    /** {@link SerializationUtils#deserialize(byte[])} – null byte array must cause IAE. */
    @Test(expected = IllegalArgumentException.class)
    public void testDeserialize_NullByteArray_ThrowsIAE() {
        SerializationUtils.deserialize((byte[]) null);
    }

    /* -------------------------------------------------------------
     *  2.  Edge‑case / exception tests
     * ------------------------------------------------------------- */

    /** Serializing an object that contains a non‑serializable field must raise SerializationException. */
    @Test(expected = SerializationException.class)
    public void testSerialize_NonSerializableField_ThrowsSerializationException() {
        NonSerializableFieldBean bean = new NonSerializableFieldBean();
        // The method accepts Serializable, so compile‑time passes; runtime should fail.
        SerializationUtils.serialize(bean);
    }

    /** Deserializing corrupted data must raise SerializationException. */
    @Test(expected = SerializationException.class)
    public void testDeserialize_CorruptedData_ThrowsSerializationException() {
        // Random bytes that do not represent a valid serialized object
        byte[] corrupted = new byte[] {0x00, 0x01, 0x02, 0x03};
        SerializationUtils.deserialize(corrupted);
    }

    /** Serialize with an OutputStream whose close() throws IOException – the exception must be ignored. */
    @Test
    public void testSerialize_OutputStreamCloseException_Ignored() {
        SimpleBean bean = new SimpleBean(11, "eleven");
        FailingCloseOutputStream failingStream = new FailingCloseOutputStream();

        // No exception should propagate from the close()
        SerializationUtils.serialize(bean, failingStream);

        // Verify that data was actually written before the close failure
        assertTrue("Data should have been written despite close failure",
                failingStream.toByteArray().length > 0);
    }

    /* -------------------------------------------------------------
     *  3.  Additional behavioural checks
     * ------------------------------------------------------------- */

    /** Verify that {@code clone} uses the custom ClassLoaderAwareObjectInputStream internally.
     *  This is indirectly confirmed by cloning an object whose class is loaded by a
     *  non‑system class loader (the test class loader). If the custom stream were not used,
     *  a ClassNotFoundException would be thrown under certain container scenarios.
     *  The simple act of cloning without exception suffices for this verification.
     */
    @Test
    public void testClone_UsesClassLoaderAwareObjectInputStream() {
        SimpleBean bean = new SimpleBean(13, "thirteen");
        // If the internal stream fails to resolve the class, a SerializationException would be thrown.
        SimpleBean cloned = SerializationUtils.clone(bean);
        assertEquals(bean, cloned);
    }
}

package org.apache.commons.lang3;

import org.junit.Test;
import org.junit.Before;
import org.junit.After;

import java.io.*;
import java.util.Arrays;

import static org.junit.Assert.*;

/**
 * Comprehensive JUnit4 test suite for {@link SerializationUtils}.
 *
 * <p>Tests cover:
 * <ul>
 *   <li>Typical usage of clone, serialize and deserialize methods</li>
 *   <li>Edge cases such as {@code null} arguments and {@code null} payloads</li>
 *   <li>Error scenarios that should result in {@link IllegalArgumentException}
 *       or {@link SerializationException}</li>
 *   <li>Behaviour of the internal {@code ClassLoaderAwareObjectInputStream}</li>
 * </ul>
 * </p>
 */
public class SerializationUtilsTest {

    /* --------------------------------------------------------------------- */
    /* Helper classes used in the tests                                      */
    /* --------------------------------------------------------------------- */

    /** Simple serializable bean used for deep‑clone verification. */
    static class Simple implements Serializable {
        private static final long serialVersionUID = 1L;
        int value;

        Simple(int value) { this.value = value; }

        @Override
        public boolean equals(Object o) {
            return (o instanceof Simple) && ((Simple) o).value == this.value;
        }

        @Override
        public int hashCode() {
            return Integer.hashCode(value);
        }
    }

    /** Bean that contains another serializable object – used to test deep cloning. */
    static class Nested implements Serializable {
        private static final long serialVersionUID = 1L;
        Simple inner;

        Nested(Simple inner) { this.inner = inner; }

        @Override
        public boolean equals(Object o) {
            return (o instanceof Nested) && ((Nested) o).inner.equals(this.inner);
        }

        @Override
        public int hashCode() {
            return inner.hashCode();
        }
    }

    /** Class that is NOT serializable – used to provoke a serialization failure. */
    static class NotSerializable {
        // intentionally empty
    }

    /** Serializable class that contains a non‑serializable field – triggers NotSerializableException. */
    static class Bad implements Serializable {
        private static final long serialVersionUID = 1L;
        NotSerializable ns = new NotSerializable();
    }

    /** Custom ClassLoader that refuses to load a specific class name. */
    static class RejectingClassLoader extends ClassLoader {
        private final String rejectedName;

        RejectingClassLoader(String rejectedName, ClassLoader parent) {
            super(parent);
            this.rejectedName = rejectedName;
        }

        @Override
        protected Class<?> loadClass(String name, boolean resolve) throws ClassNotFoundException {
            if (name.equals(rejectedName)) {
                throw new ClassNotFoundException("Rejecting class: " + name);
            }
            return super.loadClass(name, resolve);
        }
    }

    /* --------------------------------------------------------------------- */
    /* 1. clone() – typical usage, null handling and failure scenarios       */
    /* --------------------------------------------------------------------- */

    @Test
    public void testCloneSimpleObject() {
        Simple original = new Simple(42);
        Simple copy = SerializationUtils.clone(original);
        assertNotSame("Clone must be a different instance", original, copy);
        assertEquals("Clone must be equal to the original", original, copy);
    }

    @Test
    public void testCloneNestedObjectDeepCopy() {
        Simple inner = new Simple(7);
        Nested original = new Nested(inner);
        Nested copy = SerializationUtils.clone(original);
        assertNotSame("Root object must be a different instance", original, copy);
        assertNotSame("Nested inner object must also be a different instance",
                original.inner, copy.inner);
        assertEquals("Clone must be equal to the original", original, copy);
    }

    @Test
    public void testCloneNullReturnsNull() {
        assertNull("Cloning null should return null", SerializationUtils.clone(null));
    }

    @Test(expected = SerializationException.class)
    public void testCloneWithUnserializableFieldThrowsException() {
        Bad bad = new Bad();
        SerializationUtils.clone(bad); // should raise SerializationException caused by NotSerializableException
    }

    /* --------------------------------------------------------------------- */
    /* 2. serialize(Object, OutputStream) – normal, null payload, and error  */
    /* --------------------------------------------------------------------- */

    @Test
    public void testSerializeObjectToOutputStream() throws IOException {
        Simple obj = new Simple(123);
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        SerializationUtils.serialize(obj, baos);
        byte[] data = baos.toByteArray();
        assertTrue("Serialized data should not be empty", data.length > 0);

        // Verify that deserialization yields the same object
        Object deserialized = SerializationUtils.deserialize(new ByteArrayInputStream(data));
        assertEquals("Deserialized object must equal original", obj, deserialized);
    }

    @Test
    public void testSerializeNullObject() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        SerializationUtils.serialize(null, baos);
        byte[] data = baos.toByteArray();
        assertTrue("Data for a null object must be non‑empty (null reference token)", data.length > 0);

        Object result = SerializationUtils.deserialize(new ByteArrayInputStream(data));
        assertNull("Deserialization of a null payload must return null", result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testSerializeWithNullOutputStreamThrowsException() {
        SerializationUtils.serialize(new Simple(1), null);
    }

    @Test(expected = SerializationException.class)
    public void testSerializeUnserializableObjectThrowsException() {
        Bad bad = new Bad();
        // The method should wrap NotSerializableException into SerializationException
        SerializationUtils.serialize(bad, new ByteArrayOutputStream());
    }

    /* --------------------------------------------------------------------- */
    /* 3. serialize(Object) – byte[] overload                                   */
    /* --------------------------------------------------------------------- */

    @Test
    public void testSerializeToByteArray() {
        Simple obj = new Simple(99);
        byte[] bytes = SerializationUtils.serialize(obj);
        assertNotNull("Byte array must not be null", bytes);
        assertTrue("Byte array must contain data", bytes.length > 0);

        Object deserialized = SerializationUtils.deserialize(bytes);
        assertEquals("Deserialized object must equal original", obj, deserialized);
    }

    @Test
    public void testSerializeNullToByteArray() {
        byte[] bytes = SerializationUtils.serialize(null);
        assertNotNull("Byte array for null payload must not be null", bytes);
        assertTrue("Byte array must not be empty", bytes.length > 0);

        Object result = SerializationUtils.deserialize(bytes);
        assertNull("Deserialization of null payload must return null", result);
    }

    /* --------------------------------------------------------------------- */
    /* 4. deserialize(InputStream) – normal, null argument and corrupted data */
    /* --------------------------------------------------------------------- */

    @Test
    public void testDeserializeFromInputStream() {
        Simple original = new Simple(55);
        byte[] data = SerializationUtils.serialize(original);
        InputStream in = new ByteArrayInputStream(data);
        Object obj = SerializationUtils.deserialize(in);
        assertEquals("Deserialized object must match original", original, obj);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testDeserializeFromNullInputStreamThrowsException() {
        SerializationUtils.deserialize((InputStream) null);
    }

    @Test(expected = SerializationException.class)
    public void testDeserializeCorruptedDataThrowsException() {
        byte[] corrupted = new byte[] {0x01, 0x02, 0x03, 0x04};
        SerializationUtils.deserialize(corrupted);
    }

    /* --------------------------------------------------------------------- */
    /* 5. deserialize(byte[]) – normal, null argument                           */
    /* --------------------------------------------------------------------- */

    @Test
    public void testDeserializeFromByteArray() {
        Simple original = new Simple(77);
        byte[] data = SerializationUtils.serialize(original);
        Object obj = SerializationUtils.deserialize(data);
        assertEquals("Deserialized object must match original", original, obj);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testDeserializeFromNullByteArrayThrowsException() {
        SerializationUtils.deserialize((byte[]) null);
    }

    /* --------------------------------------------------------------------- */
    /* 6. ClassLoaderAwareObjectInputStream – resolveClass fallback mechanism */
    /* --------------------------------------------------------------------- */

    @Test
    public void testClassLoaderAwareObjectInputStreamFallbackToThreadContext() throws Exception {
        // Serialize a Simple instance using the default mechanism
        Simple original = new Simple(13);
        byte[] payload = SerializationUtils.serialize(original);

        // Create a ClassLoader that *rejects* loading Simple
        ClassLoader rejecting = new RejectingClassLoader(Simple.class.getName(),
                Thread.currentThread().getContextClassLoader());

        // Use the custom ClassLoaderAwareObjectInputStream with the rejecting loader
        try (ByteArrayInputStream bais = new ByteArrayInputStream(payload);
             SerializationUtils.ClassLoaderAwareObjectInputStream clIn =
                     new SerializationUtils.ClassLoaderAwareObjectInputStream(bais, rejecting)) {

            Object deserialized = clIn.readObject();
            assertEquals("Fallback to thread context ClassLoader must succeed", original, deserialized);
        }
    }

    @Test(expected = SerializationException.class)
    public void testClassLoaderAwareObjectInputStreamWhenBothLoadersFail() throws Exception {
        // Serialize a Simple instance
        Simple original = new Simple(31);
        byte[] payload = SerializationUtils.serialize(original);

        // Create a ClassLoader that rejects Simple *and* set thread context loader that also rejects it
        ClassLoader rejecting = new RejectingClassLoader(Simple.class.getName(),
                null); // parent null -> cannot load anything
        Thread currentThread = Thread.currentThread();
        ClassLoader originalContext = currentThread.getContextClassLoader();
        try {
            // Temporarily replace the thread context ClassLoader with another rejecting loader
            currentThread.setContextClassLoader(rejecting);

            // Attempt deserialization – should fail and be wrapped in SerializationException
            try (ByteArrayInputStream bais = new ByteArrayInputStream(payload);
                 SerializationUtils.ClassLoaderAwareObjectInputStream clIn =
                         new SerializationUtils.ClassLoaderAwareObjectInputStream(bais, rejecting)) {
                clIn.readObject(); // expected to throw
            }
        } finally {
            // Restore original context loader to avoid side‑effects on other tests
            currentThread.setContextClassLoader(originalContext);
        }
    }

    /* --------------------------------------------------------------------- */
    /* 7. Verify that resources are closed even when exceptions occur         */
    /* --------------------------------------------------------------------- */

    private static class CloseTrackingOutputStream extends OutputStream {
        boolean closed = false;
        @Override public void write(int b) { /* no‑op */ }
        @Override public void close() { closed = true; }
    }

    private static class CloseTrackingInputStream extends InputStream {
        boolean closed = false;
        @Override public int read() { return -1; } // end‑of‑stream
        @Override public void close() { closed = true; }
    }

    @Test
    public void testSerializeClosesOutputStreamEvenOnException() {
        CloseTrackingOutputStream ctOut = new CloseTrackingOutputStream();
        // Force an exception by serializing a non‑serializable object
        try {
            SerializationUtils.serialize(new Bad(), ctOut);
            fail("Expected SerializationException");
        } catch (SerializationException ignored) {
            // expected
        }
        assertTrue("OutputStream must be closed after exception", ctOut.closed);
    }

    @Test
    public void testDeserializeClosesInputStreamEvenOnException() {
        // Corrupt data to cause an exception during readObject()
        CloseTrackingInputStream ctIn = new CloseTrackingInputStream();
        try {
            SerializationUtils.deserialize(ctIn);
            fail("Expected SerializationException");
        } catch (SerializationException ignored) {
            // expected
        }
        assertTrue("InputStream must be closed after exception", ctIn.closed);
    }
}

package org.apache.commons.lang3;

