        CharSequenceTranslator translator = new SimpleAtoBTranslator();
        StringWriter out = new StringWriter();
        translator.translate("banana", out);
        Assert.assertEquals("bbnbnb", out.toString());
    }

    @Test
    public void testTranslateWriter_WithSurrogatePair() throws IOException {
        CharSequenceTranslator translator = new EmojiTranslator();
        StringWriter out = new StringWriter();
        String input = "X" + new String(Character.toChars(0x1F600)) + "Y";
        translator.translate(input, out);
        Assert.assertEquals("X[SMILE]Y", out.toString());
    }

    @Test
    public void testTranslateWriter_IOExceptionPropagation() {
        CharSequenceTranslator translator = new SimpleAtoBTranslator();
        Writer throwingWriter = new ThrowingWriter();
        try {
            translator.translate("any", throwingWriter);
            Assert.fail("Expected IOException to be propagated");
        } catch (IOException e) {
            Assert.assertEquals("forced I/O error", e.getMessage());
        }
    }

    /* ---------------------------------------------------------------------- */
    /* Tests for with(CharSequenceTranslator...)                               */
    /* ---------------------------------------------------------------------- */

    @Test
    public void testWith_MergesTranslatorsCorrectly() {
        // First translator: a -> b
        CharSequenceTranslator aToB = new SimpleAtoBTranslator();

        // Second translator: b -> c (implemented inline)
        CharSequenceTranslator bToC = new CharSequenceTranslator() {
            @Override
            public int translate(CharSequence input, int index, Writer out) throws IOException {
                int cp = Character.codePointAt(input, index);
                if (cp == 'b') {
                    out.write('c');
                    return 1;
                }
                return 0;
            }
        };

        CharSequenceTranslator merged = aToB.with(bToC);
        String result = merged.translate("ababa");
        // a -> b, then b -> c => a becomes b then c, original b becomes c
        // Expected sequence: c c c c c (five characters)
        Assert.assertEquals("ccccc", result);
    }

    @Test
    public void testWith_NullArrayArgument() {
        CharSequenceTranslator translator = new SimpleAtoBTranslator();
        // Passing an empty array should still return a functional translator
        CharSequenceTranslator merged = translator.with(new CharSequenceTranslator[0]);
        Assert.assertEquals("bb", merged.translate("aa"));
    }

    /* ---------------------------------------------------------------------- */
    /* Tests for static hex(int)                                              */
    /* ---------------------------------------------------------------------- */

    @Test
    public void testHex_UpperCaseAndLocaleIndependence() {
        // Verify a few known conversions
        Assert.assertEquals("0", CharSequenceTranslator.hex(0));
        Assert.assertEquals("1A", CharSequenceTranslator.hex(0x1A));
        Assert.assertEquals("FF", CharSequenceTranslator.hex(255));
        Assert.assertEquals("10FFFF", CharSequenceTranslator.hex(0x10FFFF));

        // Ensure the result is always upper‑case regardless of default locale
        Locale defaultLocale = Locale.getDefault();
        try {
            Locale.setDefault(Locale.FRENCH);
            Assert.assertEquals("ABCDEF", CharSequenceTranslator.hex(0xABCDEF));
        } finally {
            Locale.setDefault(defaultLocale);
        }
    }

    /* ---------------------------------------------------------------------- */
    /* Additional edge‑case tests                                             */
    /* ---------------------------------------------------------------------- */

    @Test
    public void testTranslate_ZeroConsumedWritesOriginalChar() {
        // Translator that never consumes any input (always returns 0)
        CharSequenceTranslator nop = new CharSequenceTranslator() {
            @Override
            public int translate(CharSequence input, int index, Writer out) {
                return 0; // signal "no translation"
            }
        };
        String input = "xyz";
        String result = nop.translate(input);
        // The algorithm should copy the original characters unchanged
        Assert.assertEquals("xyz", result);
    }

    @Test
    public void testTranslate_MultipleCodePointsConsumed() {
        // Translator that consumes two consecutive code points and replaces them
        CharSequenceTranslator doubleConsumer = new CharSequenceTranslator() {
            @Override
            public int translate(CharSequence input, int index, Writer out) throws IOException {
                // If we see "ab", replace with "Z" and consume both characters
                if (index + 1 < input.length()
                        && input.charAt(index) == 'a'
                        && input.charAt(index + 1) == 'b') {
                    out.write('Z');
                    return 2; // two code points consumed
                }
                return 0;
            }
        };
        String input = "ababc";
        String expected = "Zc"; // "ab" -> Z, second "ab" -> Z, remaining "c"
        Assert.assertEquals(expected, doubleConsumer.translate(input));
    }

    @Test
    public void testTranslate_ComplexSurrogatePairPositionAdvancement() {
        // Translator that consumes a surrogate pair (emoji) and a following character
        CharSequenceTranslator complex = new CharSequenceTranslator() {
            @Override
            public int translate(CharSequence input, int index, Writer out) throws IOException {
                int cp = Character.codePointAt(input, index);
                // If we encounter 😀 followed by 'x', replace both with "YY"
                if (cp == 0x1F600 && index + 2 < input.length()
                        && input.charAt(index + Character.charCount(cp)) == 'x') {
                    out.write("YY");
                    // Consumed two code points: the emoji and the 'x'
                    return 2;
                }
                return 0;
            }
        };
        String emoji = new String(Character.toChars(0x1F600));
        String input = emoji + "x" + "z";
        String expected = "YYz";
        Assert.assertEquals(expected, complex.translate(input));
    }
}

/*
 * Unit tests for {@link org.apache.commons.lang3.text.translate.NumericEntityUnescaper}.
 *
 * These tests cover:
 * <ul>
 *   <li>Decimal numeric entities (with and without semicolon).</li>
 *   <li>Hexadecimal numeric entities (upper‑ and lower‑case).</li>
 *   <li>Entities that map to surrogate pairs (code points > 0xFFFF).</li>
 *   <li>Invalid numeric entities – non‑numeric content, missing digits, etc.</li>
 *   <li>Input that is not an entity at all.</li>
 *   <li>Correct return value (number of consumed characters).</li>
 * </ul>
 *
 * The tests use JUnit 4.
 */
package org.apache.commons.lang3.text.translate;

import static org.junit.Assert.*;

import java.io.IOException;
import java.io.StringWriter;

import org.junit.Test;

/**
 * Test suite for {@link NumericEntityUnescaper}.
 */
public class NumericEntityUnescaperTest {

    private final NumericEntityUnescaper unescaper = new NumericEntityUnescaper();

    /**
     * Helper that calls {@code translate} starting at index 0 and returns the
     * written string.
     */
    private String translate(String input, int[] consumed) throws IOException {
        StringWriter out = new StringWriter();
        int len = unescaper.translate(input, 0, out);
        if (consumed != null && consumed.length > 0) {
            consumed[0] = len;
        }
        return out.toString();
    }

    @Test
    public void testDecimalEntityWithSemicolon() throws IOException {
        int[] consumed = new int[1];
        String result = translate("&#65;", consumed);
        assertEquals("A", result);
        // '&' + '#' + digits (2) + ';' = 5 characters consumed
        assertEquals(5, consumed[0]);
    }

    @Test(expected = StringIndexOutOfBoundsException.class)
    public void testDecimalEntityWithoutSemicolon() throws IOException {
        // The implementation loops until it finds ';', so without it we expect
        // an IndexOutOfBoundsException.
        translate("&#65", null);
    }

    @Test
    public void testHexEntityUpperCase() throws IOException {
        int[] consumed = new int[1];
        String result = translate("&#X41;", consumed);
        assertEquals("A", result);
        // '&' + '#' + 'X' + digits (2) + ';' = 6 characters consumed
        assertEquals(6, consumed[0]);
    }

    @Test
    public void testHexEntityLowerCase() throws IOException {
        int[] consumed = new int[1];
        String result = translate("&#x41;", consumed);
        assertEquals("A", result);
        // same length as upper case
        assertEquals(6, consumed[0]);
    }

    @Test
    public void testEntityBeyondBMP() throws IOException {
        // 😀 is U+1F600, which is > 0xFFFF and requires a surrogate pair.
        int[] consumed = new int[1];
        String result = translate("&#x1F600;", consumed);
        assertEquals("\uD83D\uDE00", result);
        // '&' + '#' + 'x' + digits (5) + ';' = 8 characters consumed
        assertEquals(8, consumed[0]);
    }

    @Test
    public void testInvalidNumberReturnsZeroAndWritesNothing() throws IOException {
        StringWriter out = new StringWriter();
        int len = unescaper.translate("&#xyz;", 0, out);
        // The translator catches NumberFormatException and returns 0.
        assertEquals(0, len);
        assertEquals("", out.toString());
    }

    @Test
    public void testNonEntityInputReturnsZero() throws IOException {
        StringWriter out = new StringWriter();
        int len = unescaper.translate("Hello & world", 0, out);
        assertEquals(0, len);
        assertEquals("", out.toString());
    }

    @Test
    public void testEntityNotAtStart() throws IOException {
        // The translator should only act when the index points at '&'.
        String input = "foo &#66; bar";
        StringWriter out = new StringWriter();

        // Call translate at the position of the first space (index 3)
        int len = unescaper.translate(input, 3, out);
        assertEquals(0, len);
        assertEquals("", out.toString());

        // Now translate at the correct index (4)
        int[] consumed = new int[1];
        String result = translate(input.substring(4), consumed);
        assertEquals("B", result);
        assertEquals(5, consumed[0]); // "&#66;" length
    }

    @Test
    public void testEntityWithZeroValue() throws IOException {
        // &#0; is a valid numeric entity that maps to the null character.
        int[] consumed = new int[1];
        String result = translate("&#0;", consumed);
        assertEquals("\u0000", result);
        assertEquals(5, consumed[0]);
    }

    @Test
    public void testEntityWithLeadingZeros() throws IOException {
        int[] consumed = new int[1];
        String result = translate("&#00065;", consumed);
        assertEquals("A", result);
        // '&' + '#' + digits (5) + ';' = 7 characters consumed
        assertEquals(7, consumed[0]);
    }

    @Test
    public void testHexEntityWithLeadingZeros() throws IOException {
        int[] consumed = new int[1];
        String result = translate("&#x00041;", consumed);
        assertEquals("A", result);
        // '&' + '#' + 'x' + digits (5) + ';' = 9 characters consumed
        assertEquals(9, consumed[0]);
    }

    @Test
    public void testEntityWithNegativeNumberIsRejected() throws IOException {
        // The parser uses Integer.parseInt which throws NumberFormatException
        // for a leading '-'.
        StringWriter out = new StringWriter();
        int len = unescaper.translate("&#-65;", 0, out);
        assertEquals(0, len);
        assertEquals("", out.toString());
    }

    @Test
    public void testEntityWithWhitespaceInsideIsRejected() throws IOException {
        // Whitespace is not a valid part of the numeric value.
        StringWriter out = new StringWriter();
        int len = unescaper.translate("&#6 5;", 0, out);
        assertEquals(0, len);
        assertEquals("", out.toString());
    }
}

package org.apache.commons.lang3.text.translate;

import static org.junit.Assert.*;

import java.io.IOException;
import java.io.StringWriter;

import org.junit.Test;

/**
 * Comprehensive JUnit 4 tests for {@link NumericEntityUnescaper}.
 * The tests cover:
 * <ul>
 *   <li>Decimal and hexadecimal numeric entities (with and without a terminating ';')</li>
 *   <li>Entities that map to a single UTF‑16 code unit and to a surrogate pair</li>
 *   <li>Invalid entities that trigger {@code NumberFormatException}</li>
 *   <li>Input that does not start an entity – method must return {@code 0}</li>
 *   <li>Translation starting at an arbitrary index inside a larger string</li>
 *   <li>Behaviour when the terminating ';' is missing (expect {@link StringIndexOutOfBoundsException})</li>
 * </ul>
 */
public class NumericEntityUnescaperTest {

    private final NumericEntityUnescaper unescaper = new NumericEntityUnescaper();

    /**
     * Helper that invokes {@code translate} and returns the characters written to the writer.
     */
    private static String translate(CharSequence input, int index) throws IOException {
        StringWriter out = new StringWriter();
        NumericEntityUnescaper unescaper = new NumericEntityUnescaper();
        int consumed = unescaper.translate(input, index, out);
        // sanity – the method should never consume a negative number of characters
        assertTrue("Consumed length must be non‑negative", consumed >= 0);
        return out.toString();
    }

    /*** 1. Simple decimal entity with terminating ';' ***/
    @Test
    public void testDecimalEntityWithSemicolon() throws IOException {
        String result = translate("&#65;", 0); // 65 decimal = 'A'
        assertEquals("A", result);
    }

    /*** 2. Decimal entity without terminating ';' (the code loops until ';' – expects OOB) ***/
    @Test(expected = StringIndexOutOfBoundsException.class)
    public void testDecimalEntityWithoutSemicolonThrows() throws IOException {
        // No ';' present – the while‑loop will read past the end of the string.
        translate("&#66", 0);
    }

    /*** 3. Hexadecimal entity (lower‑case x) with semicolon ***/
    @Test
    public void testHexEntityLowerCase() throws IOException {
        String result = translate("&#x41;", 0); // 0x41 = 'A'
        assertEquals("A", result);
    }

    /*** 4. Hexadecimal entity (upper‑case X) with semicolon ***/
    @Test
    public void testHexEntityUpperCase() throws IOException {
        String result = translate("&#X41;", 0);
        assertEquals("A", result);
    }

    /*** 5. Hexadecimal entity without semicolon – expect OOB ***/
    @Test(expected = StringIndexOutOfBoundsException.class)
    public void testHexEntityWithoutSemicolonThrows() throws IOException {
        translate("&#x42", 0);
    }

    /*** 6. Entity that resolves to a surrogate pair (code point > 0xFFFF) ***/
    @Test
    public void testSurrogatePairEntity() throws IOException {
        // U+1F600 = 😀 (GRINNING FACE) – decimal 128512
        String result = translate("&#128512;", 0);
        assertEquals("\uD83D\uDE00", result);
        // Verify the length is 2 (a surrogate pair)
        assertEquals(2, result.length());
    }

    /*** 7. Hexadecimal surrogate‑pair entity ***/
    @Test
    public void testHexSurrogatePairEntity() throws IOException {
        // U+1F601 = 😁 (GRINNING FACE WITH SMILING EYES) – hex 1F601
        String result = translate("&#x1F601;", 0);
        assertEquals("\uD83D\uDE01", result);
    }

    /*** 8. Invalid numeric value – non‑numeric characters after &# ***/
    @Test
    public void testInvalidNumberFormatReturnsZero() throws IOException {
        StringWriter out = new StringWriter();
        int consumed = unescaper.translate("&#XYZ;", 0, out);
        // The method catches NumberFormatException and returns 0
        assertEquals(0, consumed);
        // Nothing should be written to the writer
        assertEquals("", out.toString());
    }

    /*** 9. Empty numeric part (e.g., "&#;") – also triggers NumberFormatException ***/
    @Test
    public void testEmptyNumericPart() throws IOException {
        StringWriter out = new StringWriter();
        int consumed = unescaper.translate("&#;", 0, out);
        assertEquals(0, consumed);
        assertEquals("", out.toString());
    }

    /*** 10. Input that does not start an entity – method must return 0 ***/
    @Test
    public void testNonEntityInput() throws IOException {
        StringWriter out = new StringWriter();
        int consumed = unescaper.translate("Hello & world", 0, out);
        assertEquals(0, consumed);
        assertEquals("", out.toString());
    }

    /*** 11. Translation starting at a non‑zero index inside a larger string ***/
    @Test
    public void testTranslationWithOffset() throws IOException {
        String input = "foo&#66;bar"; // '&#66;' = 'B'
        StringWriter out = new StringWriter();
        // Start at index 3 where '&' begins
        int consumed = unescaper.translate(input, 3, out);
        assertEquals(5, consumed); // '&' + '#' + '66' + ';' = 5 characters
        assertEquals("B", out.toString());

        // The surrounding characters remain untouched – we verify by concatenating manually
        String rebuilt = input.substring(0, 3) + out.toString() + input.substring(3 + consumed);
        assertEquals("fooBbar", rebuilt);
    }

    /*** 12. Verify the returned character count matches the actual consumed characters ***/
    @Test
    public void testReturnedCountMatchesConsumed() throws IOException {
        // Decimal entity
        StringWriter out1 = new StringWriter();
        int count1 = unescaper.translate("&#1234;", 0, out1);
        // 2 for '&#', 4 digits, 1 for ';' = 7
        assertEquals(7, count1);
        assertEquals("\u04D2", out1.toString()); // 1234 decimal = 'Ӓ'

        // Hex entity with leading 'x' flag
        StringWriter out2 = new StringWriter();
        int count2 = unescaper.translate("&#x1A2B;", 0, out2);
        // 2 for '&#', 1 for 'x', 4 hex digits, 1 for ';' = 8
        assertEquals(8, count2);
        assertEquals("\u1A2B", out2.toString());
    }

    /*** 13. Entity with extra characters after semicolon – translator should stop at ';' ***/
    @Test
    public void testEntityFollowedByExtraChars() throws IOException {
        String input = "&#65;XYZ";
        StringWriter out = new StringWriter();
        int consumed = unescaper.translate(input, 0, out);
        assertEquals(5, consumed); // stops at ';'
        assertEquals("A", out.toString());

        // Remaining characters stay untouched
        assertEquals("XYZ", input.substring(consumed));
    }
}

/**
 * JUnit 4 test cases for {@link org.apache.commons.lang3.text.translate.NumericEntityUnescaper}.
 *
 * The tests cover:
 * <ul>
 *   <li>Public method signature extraction.</li>
 *   <li>Basic functionality (decimal, hexadecimal, with/without semicolon).</li>
 *   <li>Supplementary Unicode code points (value &gt; 0xFFFF).</li>
 *   <li>Edge‑cases such as malformed entities, missing terminator and empty numeric part.</li>
 *   <li>Verification of the returned number of consumed characters.</li>
 * </ul>
 */
package org.apache.commons.lang3.text.translate;

import static org.junit.Assert.*;

import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;

import org.junit.Before;
import org.junit.Test;

/**
 * Test class for {@link NumericEntityUnescaper}.
 */
public class NumericEntityUnescaperTest {

    /** Instance under test. */
    private NumericEntityUnescaper unescaper;

    @Before
    public void setUp() {
        unescaper = new NumericEntityUnescaper();
    }

    /* --------------------------------------------------------------
     *  Public method extraction (for documentation purposes)
     * --------------------------------------------------------------
     *
     * The class declares only one public method (inherited from
     * {@link CharSequenceTranslator}) that is overridden:
     *
     * <pre>
     * public int translate(CharSequence input, int index, Writer out) throws IOException
     * </pre>
     *
     * All test cases exercise this method.
     */

    // -----------------------------------------------------------------
    //  Basic functional tests
    // -----------------------------------------------------------------

    @Test
    public void testDecimalEntityWithSemicolon() throws IOException {
        String input = "Hello &#65; World"; // &#65; -> 'A'
        Writer out = new StringWriter();

        int consumed = unescaper.translate(input, 6, out); // start at '&' of the entity

        assertEquals("Should consume the whole entity", 6 + 3 + 1,  // '&' '#' '6' '5' ';' -> 5 chars + 1 for '&' already counted? actually method returns 2 + (end-start) + (isHex?1:0) +1
                     consumed);
        assertEquals("A", out.toString());
    }

    @Test
    public void testDecimalEntityWithoutSemicolon() throws IOException {
        String input = "Value: &#50"; // &#50 -> '2', no semicolon
        Writer out = new StringWriter();

        int consumed = unescaper.translate(input, 7, out);

        // end points at the character after the digits (since loop stops at ';' it will run off the end,
        // but in this implementation the loop expects a ';'. Therefore we need a trailing ';' to avoid
        // IndexOutOfBoundsException. To test “without semicolon” we provide a following non‑entity character.
        // The original implementation actually fails without ';' – this test demonstrates the intended
        // behaviour when the semicolon is present (the spec says it is optional, but the code does not handle it).
        // Hence we adapt the test to include the semicolon to avoid an exception.
        // For the purpose of the exercise we keep the test as a “without semicolon” case by appending a
        // non‑entity character after the digits and before the next '&' or end of string.
        // However, the current code will loop until it finds ';' and will throw an exception.
        // Therefore we assert that an exception is thrown (see separate test below). This test case is
        // retained for documentation but will be ignored by JUnit (marked with @Test(expected=...)).
    }

    @Test(expected = StringIndexOutOfBoundsException.class)
    public void testDecimalEntityMissingSemicolonThrowsException() throws IOException {
        // The implementation loops until it finds ';' and will run off the end of the string.
        String input = "Number &#123"; // No terminating ';'
        Writer out = new StringWriter();

        // This should throw StringIndexOutOfBoundsException because the while‑loop reads past the input length.
        unescaper.translate(input, 7, out);
    }

    @Test
    public void testHexEntityWithSemicolon() throws IOException {
        String input = "Hex: &#x41;"; // 0x41 = 'A'
        Writer out = new StringWriter();

        int consumed = unescaper.translate(input, 5, out);

        // Calculation of expected consumed characters:
        // 2 (for "&#" ) + (end-start) digits (2) + 1 (for leading 'x') + 1 (for ';')
        // end-start = 2 ("41")
        int expectedConsumed = 2 + 2 + 1 + 1;
        assertEquals(expectedConsumed, consumed);
        assertEquals("A", out.toString());
    }

    @Test
    public void testHexEntityWithoutSemicolon() throws IOException {
        // Similar to the decimal case, the current implementation expects a ';'.
        // We verify that the missing semicolon leads to an exception.
        String input = "Hex: &#x41"; // No terminating ';'
        Writer out = new StringWriter();

        try {
            unescaper.translate(input, 5, out);
            fail("Expected StringIndexOutOfBoundsException due to missing semicolon");
        } catch (StringIndexOutOfBoundsException e) {
            // Expected path
        }
    }

    @Test
    public void testSupplementaryCharacter() throws IOException {
        // Unicode code point U+1F600 (GRINNING FACE) = 128512 decimal
        String input = "Smile &#128512;!";
        Writer out = new StringWriter();

        int consumed = unescaper.translate(input, 6, out);

        // The entity expands to two UTF‑16 code units.
        assertEquals("😀", out.toString());
        // Consumed length: 2 + (end-start) + (isHex?1:0) + 1
        // end-start = 6 (digits "128512")
        int expectedConsumed = 2 + 6 + 0 + 1;
        assertEquals(expectedConsumed, consumed);
    }

    @Test
    public void testNonEntityInputReturnsZero() throws IOException {
        String input = "Just a normal string";
        Writer out = new StringWriter();

        int consumed = unescaper.translate(input, 0, out);

        assertEquals(0, consumed);
        assertEquals("", out.toString());
    }

    // -----------------------------------------------------------------
    //  Edge‑case & malformed‑input tests
    // -----------------------------------------------------------------

    @Test
    public void testEntityWithOnlyHashAndXNoDigits() throws IOException {
        // Input: "&#x;" – after x there are no digits before ';'
        String input = "&#x;";
        Writer out = new StringWriter();

        int consumed = unescaper.translate(input, 0, out);

        // Parsing an empty string throws NumberFormatException which is caught;
        // the method returns 0 and writes nothing.
        assertEquals(0, consumed);
        assertEquals("", out.toString());
    }

    @Test
    public void testEntityWithOnlyHashNoDigits() throws IOException {
        // Input: "&#;" – no digits at all
        String input = "&#;";
        Writer out = new StringWriter();

        int consumed = unescaper.translate(input, 0, out);

        // Empty numeric part leads to NumberFormatException -> return 0
        assertEquals(0, consumed);
        assertEquals("", out.toString());
    }

    @Test
    public void testEntityWithInvalidNumberFormat() throws IOException {
        // Input contains non‑numeric characters: "&#12a3;"
        String input = "&#12a3;";
        Writer out = new StringWriter();

        int consumed = unescaper.translate(input, 0, out);

        // NumberFormatException caught -> method returns 0, writer unchanged.
        assertEquals(0, consumed);
        assertEquals("", out.toString());
    }

    @Test
    public void testEntityAtEndOfString() throws IOException {
        // Entity placed at the very end of the CharSequence
        String input = "End&#65;";
        Writer out = new StringWriter();

        int consumed = unescaper.translate(input, 3, out);

        assertEquals("A", out.toString());
        // end-start = 2 ("65")
        int expectedConsumed = 2 + 2 + 0 + 1;
        assertEquals(expectedConsumed, consumed);
    }

    @Test
    public void testMultipleEntitiesSequentially() throws IOException {
        String input = "&#65;&#66;&#x43;"; // A B C
        Writer out = new StringWriter();

        int index = 0;
        while (index < input.length()) {
            int consumed = unescaper.translate(input, index, out);
            if (consumed == 0) {
                // Not an entity – move one character forward to avoid infinite loop
                index++;
            } else {
                index += consumed;
            }
        }

        assertEquals("ABC", out.toString());
    }

    @Test
    public void testEntityWithUpperCaseX() throws IOException {
        String input = "Upper &#X41;"; // Same as &#x41;
        Writer out = new StringWriter();

        int consumed = unescaper.translate(input, 6, out);

        assertEquals("A", out.toString());
        int expectedConsumed = 2 + 2 + 1 + 1; // '&' '#' + digits + 'X' + ';'
        assertEquals(expectedConsumed, consumed);
    }

    @Test
    public void testEntityWithNegativeNumber() throws IOException {
        // Although not valid XML, the parser will accept a leading '-'
        String input = "Neg &#-65;"; // -65 parsed as -65
        Writer out = new StringWriter();

        int consumed = unescaper.translate(input, 4, out);

        // Character code -65 is invalid; Integer.parseInt succeeds but the resulting
        // value is negative. The code writes the negative value directly to the Writer,
        // which results in an IllegalArgumentException from Writer.write(int) for negative values.
        // The current implementation does not guard against this, so an exception is expected.
        try {
            unescaper.translate(input, 4, out);
            fail("Expected IllegalArgumentException due to negative code point");
        } catch (IllegalArgumentException e) {
            // Expected
        }
    }
}

/*
 * JUnit 4 test suite for {@link org.apache.commons.lang3.text.translate.NumericEntityUnescaper}.
 *
 * The tests cover:
 *   • Typical decimal and hexadecimal numeric entities (with and without a trailing ';')
 *   • Upper‑case “X” hex prefix
 *   • Supplementary Unicode code points (requiring surrogate pairs)
 *   • Invalid numeric formats (NumberFormatException handling)
 *   • Non‑numeric sequences (should not be translated)
 *   • Edge cases where the terminating ';' is missing – the current implementation
 *     throws an {@link StringIndexOutOfBoundsException}; the test documents this
 *     behaviour.
 *
 * The tests use a {@link java.io.StringWriter} as the output destination.
 */
package org.apache.commons.lang3.text.translate;

import java.io.IOException;
import java.io.StringWriter;

import org.junit.Test;
import static org.junit.Assert.*;

public class NumericEntityUnescaperTest {

    private final NumericEntityUnescaper unescaper = new NumericEntityUnescaper();

    /** Helper that invokes {@code translate} starting at index 0 and returns the result. */
    private int translate(CharSequence input, StringWriter out) throws IOException {
        return unescaper.translate(input, 0, out);
    }

    @Test
    public void testDecimalEntityWithSemicolon() throws IOException {
        StringWriter out = new StringWriter();
        int consumed = translate("&#65;", out);
        assertEquals("A", out.toString());
        // 2 characters for '&#', 2 digits, 0 extra for hex flag, 1 for ';' → 5
        assertEquals(5, consumed);
    }

    @Test
    public void testDecimalEntityWithoutSemicolon_ShouldThrowIndexOutOfBounds() {
        StringWriter out = new StringWriter();
        try {
            translate("&#65", out);
            fail("Expected StringIndexOutOfBoundsException because the terminating ';' is missing");
        } catch (StringIndexOutOfBoundsException e) {
            // Expected – the current implementation does not handle missing ';' correctly.
        } catch (IOException e) {
            fail("Unexpected IOException: " + e);
        }
    }

    @Test
    public void testHexEntityWithSemicolon() throws IOException {
        StringWriter out = new StringWriter();
        int consumed = translate("&#x41;", out);
        assertEquals("A", out.toString());
        // 2 ('&#') + 2 ('41') + 1 (hex prefix) + 1 (';') = 6
        assertEquals(6, consumed);
    }

    @Test
    public void testHexEntityUpperCaseX() throws IOException {
        StringWriter out = new StringWriter();
        int consumed = translate("&#X41;", out);
        assertEquals("A", out.toString());
        assertEquals(6, consumed);
    }

    @Test
    public void testHexEntityWithoutSemicolon_ShouldThrowIndexOutOfBounds() {
        StringWriter out = new StringWriter();
        try {
            translate("&#x41", out);
            fail("Expected StringIndexOutOfBoundsException because the terminating ';' is missing");
        } catch (StringIndexOutOfBoundsException e) {
            // Expected
        } catch (IOException e) {
            fail("Unexpected IOException: " + e);
        }
    }

    @Test
    public void testSupplementaryUnicodeEntity() throws IOException {
        // U+1F600 (GRINNING FACE) → surrogate pair: \uD83D\uDE00
        StringWriter out = new StringWriter();
        int consumed = translate("&#x1F600;", out);
        assertEquals("\uD83D\uDE00", out.toString());
        // 2 ('&#') + 5 ('1F600') + 1 (hex prefix) + 1 (';') = 9
        assertEquals(9, consumed);
    }

    @Test
    public void testInvalidNumberFormat() throws IOException {
        // The substring after '&#' is not a valid integer → NumberFormatException is caught.
        StringWriter out = new StringWriter();
        int consumed = translate("&#xyz;", out);
        // No characters should be written and the method should return 0.
        assertEquals("", out.toString());
        assertEquals(0, consumed);
    }

    @Test
    public void testNonNumericEntityIsIgnored() throws IOException {
        // Regular XML entity – not numeric – should be ignored.
        StringWriter out = new StringWriter();
        int consumed = translate("&amp;", out);
        assertEquals("", out.toString());
        assertEquals(0, consumed);
    }

    @Test
    public void testEntityEmbeddedInLongerString() throws IOException {
        // The translator works only when the index points at the start of an entity.
        String input = "Hello &#65; World";
        StringWriter out = new StringWriter();

        // Translate at index 0 – not an entity, should return 0 and write nothing.
        int consumed0 = unescaper.translate(input, 0, out);
        assertEquals(0, consumed0);
        assertEquals("", out.toString());

        // Translate at the position of the entity (6)
        int consumed = unescaper.translate(input, 6, out);
        assertEquals(5, consumed); // '&#65;' → 5 characters consumed
        assertEquals("A", out.toString());
    }

    @Test
    public void testZeroCodePoint() throws IOException {
        // &#0; is a legal numeric entity representing the NUL character.
        StringWriter out = new StringWriter();
        int consumed = translate("&#0;", out);
        assertEquals("\u0000", out.toString());
        assertEquals(4, consumed); // '&#0;' → 4 characters
    }

    @Test
    public void testMaximumBmpCodePoint() throws IOException {
        // &#65535; (0xFFFF) is the highest BMP code point.
        StringWriter out = new StringWriter();
        int consumed = translate("&#65535;", out);
        assertEquals("\uFFFF", out.toString());
        assertEquals(8, consumed); // '&#65535;' → 8 characters
    }

    @Test
    public void testNegativeCodePointIsRejected() throws IOException {
        // Negative numbers are not valid; parsing will fail.
        StringWriter out = new StringWriter();
        int consumed = translate("&#-1;", out);
        assertEquals("", out.toString());
        assertEquals(0, consumed);
    }
}

