        ParsePosition pos = new ParsePosition(0);
        // Position after the comma that starts the format description
        pos.setIndex(3);
        String desc = (String) invokePrivate(emf, "parseFormatDescription",
                new Class[]{String.class, ParsePosition.class},
                "{0,number}", pos);
        assertEquals("number", desc);
    }

    @Test
    public void testParseFormatDescriptionNestedBraces() throws Exception {
        ExtendedMessageFormat emf = new ExtendedMessageFormat("{0,choice,0#zero|1#{0}}");
        ParsePosition pos = new ParsePosition(0);
        // Position after the first comma (start of the format description)
        pos.setIndex(3);
        String desc = (String) invokePrivate(emf, "parseFormatDescription",
                new Class[]{String.class, ParsePosition.class},
                "{0,choice,0#zero|1#{0}}", pos);
        assertEquals("choice,0#zero|1#{0}", desc);
    }

    @Test
    public void testInsertFormatsReconstruction() throws Exception {
        ExtendedMessageFormat emf = new ExtendedMessageFormat("{0}");
        // Simulate a pattern that after core parsing became "Hello {0}"
        String basePattern = "Hello {0}";
        // custom description for the first format element
        ArrayList<String> custom = new ArrayList<>();
        custom.add("myfmt");
        String rebuilt = (String) invokePrivate(emf, "insertFormats",
                new Class[]{String.class, ArrayList.class},
                basePattern, custom);
        assertEquals("Hello {0, myfmt}", rebuilt);
    }

    @Test
    public void testSeekNonWsSkipsSpacesAndTabs() throws Exception {
        ExtendedMessageFormat emf = new ExtendedMessageFormat("{0}");
        ParsePosition pos = new ParsePosition(0);
        String pattern = "  \t  123";
        // Position starts at 0; after calling seekNonWs it should point at '1'
        invokePrivate(emf, "seekNonWs",
                new Class[]{String.class, ParsePosition.class},
                pattern, pos);
        assertEquals(5, pos.getIndex()); // three spaces + tab + two spaces = 5
        assertEquals('1', pattern.charAt(pos.getIndex()));
    }

    @Test
    public void testNextAdvancesByOne() throws Exception {
        ExtendedMessageFormat emf = new ExtendedMessageFormat("{0}");
        ParsePosition pos = new ParsePosition(2);
        invokePrivate(emf, "next",
                new Class[]{ParsePosition.class},
                pos);
        assertEquals(3, pos.getIndex());
    }

    @Test
    public void testAppendQuotedStringEscaping() throws Exception {
        ExtendedMessageFormat emf = new ExtendedMessageFormat("{0}");
        ParsePosition pos = new ParsePosition(0);
        // pattern contains a quoted string with escaped quote:  'it''s'
        String pattern = "'it''s'";
        StringBuffer sb = new StringBuffer();
        invokePrivate(emf, "appendQuotedString",
                new Class[]{String.class, ParsePosition.class,
                        StringBuffer.class, boolean.class},
                pattern, pos, sb, true);
        // The result should be the unescaped content: it's
        assertEquals("it's", sb.toString());
        // Position should be after the closing quote
        assertEquals(pattern.length(), pos.getIndex());
    }

    @Test
    public void testGetQuotedStringJustConsumes() throws Exception {
        ExtendedMessageFormat emf = new ExtendedMessageFormat("{0}");
        ParsePosition pos = new ParsePosition(0);
        String pattern = "'quoted'";
        // Should complete without exception and leave pos after the closing quote
        invokePrivate(emf, "getQuotedString",
                new Class[]{String.class, ParsePosition.class, boolean.class},
                pattern, pos, true);
        assertEquals(pattern.length(), pos.getIndex());
    }

    @Test
    public void testContainsElementsDetectsNonNull() throws Exception {
        ExtendedMessageFormat emf = new ExtendedMessageFormat("{0}");
        ArrayList<Object> coll = new ArrayList<>();
        coll.add(null);
        coll.add("value");
        boolean result = (boolean) invokePrivate(emf, "containsElements",
                new Class[]{Collection.class}, coll);
        assertTrue(result);
    }

    @Test
    public void testContainsElementsAllNullOrEmpty() throws Exception {
        ExtendedMessageFormat emf = new ExtendedMessageFormat("{0}");
        ArrayList<Object> coll = new ArrayList<>();
        coll.add(null);
        coll.add(null);
        boolean result = (boolean) invokePrivate(emf, "containsElements",
                new Class[]{Collection.class}, coll);
        assertFalse(result);
    }

    // -----------------------------------------------------------------------
    // Ensure toPattern reflects custom formats after applyPattern is called again
    // -----------------------------------------------------------------------
    @Test
    public void testReapplyPatternKeepsCustomFormats() {
        Map<String, FormatFactory> reg = new HashMap<>();
        reg.put("upper", new SimpleFactory());
        ExtendedMessageFormat emf = new ExtendedMessageFormat(
                "Start {0,upper} End", Locale.US, reg);
        // First formatting
        assertEquals("Start upper:hello End", emf.format(new Object[]{"hello"}));
        // Re‑apply a different pattern that still uses the same custom format
        emf.applyPattern("Again {0,upper}");
        assertEquals("Again upper:world", emf.format(new Object[]{"world"}));
        // toPattern must contain the custom description again
        assertEquals("Again {0, upper}", emf.toPattern());
    }
}

/**********************************************************************
 * JUnit 4 test cases for org.apache.commons.lang.text.ExtendedMessageFormat
 *
 * The tests cover:
 *  • Public API methods (toPattern, applyPattern, and the mutators that
 *    must throw UnsupportedOperationException)
 *  • Normal usage with and without a custom FormatFactory registry
 *  • Edge‑case handling for malformed patterns (invalid argument index,
 *    unterminated format elements, and quoted‑string handling)
 *
 * These tests are written for JUnit 4 and require only the standard
 * JDK and the Commons‑Lang library that contains ExtendedMessageFormat.
 **********************************************************************/
package org.apache.commons.lang.text;

import static org.junit.Assert.*;

import java.text.Format;
import java.text.ParsePosition;
import java.util.Collections;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

import org.junit.Before;
import org.junit.Test;

/**
 * Test suite for {@link ExtendedMessageFormat}.
 */
public class ExtendedMessageFormatTest {

    /** Simple {@link FormatFactory} that creates an {@link UpperCaseFormat}. */
    private static class UpperCaseFormatFactory implements FormatFactory {
        @Override
        public Format getFormat(String name, String arguments, Locale locale) {
            // arguments are ignored – we only need a format that upper‑cases strings
            return new UpperCaseFormat();
        }
    }

    /** A {@link Format} implementation that upper‑cases a {@link String}. */
    private static class UpperCaseFormat extends Format {
        private static final long serialVersionUID = 1L;

        @Override
        public StringBuffer format(Object obj, StringBuffer toAppendTo,
                                   java.text.FieldPosition pos) {
            if (obj == null) {
                return toAppendTo;
            }
            return toAppendTo.append(String.valueOf(obj).toUpperCase(Locale.ROOT));
        }

        @Override
        public Object parseObject(String source, ParsePosition pos) {
            // parsing is not required for the tests – just return the raw string
            int start = pos.getIndex();
            pos.setIndex(source.length());
            return source.substring(start);
        }
    }

    /** Registry used for the tests that require a custom format. */
    private Map<String, FormatFactory> registry;

    @Before
    public void setUp() {
        registry = new HashMap<String, FormatFactory>();
        registry.put("upper", new UpperCaseFormatFactory());
    }

    /** --------------------------------------------------------------------
     *  Basic behaviour of toPattern() when no custom formats are supplied.
     * -------------------------------------------------------------------- */
    @Test
    public void testToPatternWithoutCustomFormats() {
        ExtendedMessageFormat emf = new ExtendedMessageFormat("Hello {0}");
        assertEquals("Hello {0}", emf.toPattern());

        // Verify that the format works like a normal MessageFormat
        assertEquals("Hello world", emf.format(new Object[] {"world"}));
    }

    /** --------------------------------------------------------------------
     *  applyPattern() with a custom registry – the custom format must be
     *  inserted back into the pattern returned by toPattern() and must affect
     *  the output of format().
     * -------------------------------------------------------------------- */
    @Test
    public void testApplyPatternWithCustomRegistry() {
        String pattern = "Value: {0,upper}";
        ExtendedMessageFormat emf = new ExtendedMessageFormat(pattern, Locale.US, registry);

        // The pattern returned by toPattern() must contain the custom format name.
        assertEquals(pattern, emf.toPattern());

        // Formatting must use the UpperCaseFormat supplied by the registry.
        String result = emf.format(new Object[] {"test"});
        assertEquals("Value: TEST", result);
    }

    /** --------------------------------------------------------------------
     *  Whitespace around the format name should be tolerated.
     * -------------------------------------------------------------------- */
    @Test
    public void testWhitespaceAroundFormatName() {
        String pattern = "Value: {0, upper }";
        ExtendedMessageFormat emf = new ExtendedMessageFormat(pattern, Locale.US, registry);
        assertEquals("Value: {0, upper }", emf.toPattern());

        String result = emf.format(new Object[] {"abc"});
        assertEquals("Value: ABC", result);
    }

    /** --------------------------------------------------------------------
     *  The mutator methods inherited from MessageFormat must throw
     *  UnsupportedOperationException as documented.
     * -------------------------------------------------------------------- */
    @Test(expected = UnsupportedOperationException.class)
    public void testSetFormatThrowsException() {
        ExtendedMessageFormat emf = new ExtendedMessageFormat("{0}");
        emf.setFormat(0, new UpperCaseFormat());
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testSetFormatByArgumentIndexThrowsException() {
        ExtendedMessageFormat emf = new ExtendedMessageFormat("{0}");
        emf.setFormatByArgumentIndex(0, new UpperCaseFormat());
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testSetFormatsThrowsException() {
        ExtendedMessageFormat emf = new ExtendedMessageFormat("{0}");
        emf.setFormats(new Format[] { new UpperCaseFormat() });
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testSetFormatsByArgumentIndexThrowsException() {
        ExtendedMessageFormat emf = new ExtendedMessageFormat("{0}");
        emf.setFormatsByArgumentIndex(new Format[] { new UpperCaseFormat() });
    }

    /** --------------------------------------------------------------------
     *  Invalid argument index – e.g. non‑numeric characters – must cause
     *  IllegalArgumentException during pattern parsing.
     * -------------------------------------------------------------------- */
    @Test
    public void testInvalidArgumentIndexThrowsException() {
        try {
            new ExtendedMessageFormat("{abc}");
            fail("Expected IllegalArgumentException because argument index is not numeric");
        } catch (IllegalArgumentException e) {
            // expected – message contains the offending pattern fragment
            assertTrue(e.getMessage().contains("Invalid format argument index"));
        }
    }

    /** --------------------------------------------------------------------
     *  Unterminated format element (missing closing '}') must cause
     *  IllegalArgumentException.
     * -------------------------------------------------------------------- */
    @Test
    public void testUnterminatedFormatElementThrowsException() {
        try {
            new ExtendedMessageFormat("{0,upper");
            fail("Expected IllegalArgumentException because the format element is not closed");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("Unterminated format element"));
        }
    }

    /** --------------------------------------------------------------------
     *  Quoted‑string handling – escaped single quotes (two consecutive
     *  quotes) should be interpreted as a literal quote character.
     * -------------------------------------------------------------------- */
    @Test
    public void testEscapedQuotesInPattern() {
        // Pattern:  '\''{0}'\''  -> literal quote, argument, literal quote
        String pattern = "'''{0}'''";
        ExtendedMessageFormat emf = new ExtendedMessageFormat(pattern);
        assertEquals("'''{0}'''", emf.toPattern());

        String result = emf.format(new Object[] {"quoted"});
        // Expected output: 'quoted'
        assertEquals("'quoted'", result);
    }

    /** --------------------------------------------------------------------
     *  When the registry is null, ExtendedMessageFormat must behave exactly
     *  like java.text.MessageFormat.  This test uses a built‑in date format.
     * -------------------------------------------------------------------- */
    @Test
    public void testApplyPatternWithoutRegistryFallsBackToMessageFormat() {
        // Using the built‑in date format "date" to ensure the fallback path works.
        ExtendedMessageFormat emf = new ExtendedMessageFormat("{0,date,short}", Locale.US, null);
        assertEquals("{0,date,short}", emf.toPattern());

        // The result depends on the default locale; we just verify that formatting
        // does not throw and returns a non‑null string.
        String formatted = emf.format(new Object[] { new java.util.Date(0L) });
        assertNotNull(formatted);
    }
}

/**
 * JUnit 4 test suite for {@link org.apache.commons.lang.text.ExtendedMessageFormat}.
 *
 * The tests cover:
 * <ul>
 *   <li>Construction with and without a registry.</li>
 *   <li>Basic pattern handling (toPattern, applyPattern).</li>
 *   <li>Custom format factories.</li>
 *   <li>Parsing helpers (readArgumentIndex, parseFormatDescription, insertFormats,
 *       seekNonWs, next, appendQuotedString, getQuotedString, containsElements).</li>
 *   <li>Unsupported mutator methods.</li>
 *   <li>Error scenarios (unterminated elements, illegal argument indexes, etc.).</li>
 * </ul>
 *
 * The test class is deliberately exhaustive – each public method (and each
 * private helper that can be exercised indirectly) gets at least one positive
 * test and one negative test where appropriate.
 */
package org.apache.commons.lang.text;

import static org.junit.Assert.*;

import java.text.Format;
import java.text.MessageFormat;
import java.text.ParsePosition;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

import org.junit.Before;
import org.junit.Test;

/**
 * Test cases for {@link ExtendedMessageFormat}.
 */
public class ExtendedMessageFormatTest {

    /** Simple {@link FormatFactory} that creates a format which upper‑cases strings. */
    private static class UpperCaseFormatFactory implements FormatFactory {
        @Override
        public Format getFormat(String name, String arguments, Locale locale) {
            // arguments are ignored – we only need a format that upper‑cases.
            return new Format() {
                @Override
                public StringBuffer format(Object obj, StringBuffer toAppendTo,
                        java.text.FieldPosition pos) {
                    return toAppendTo.append(String.valueOf(obj).toUpperCase(locale));
                }

                @Override
                public Object parseObject(String source, ParsePosition pos) {
                    // parsing is not needed for the tests – just return the raw string.
                    int start = pos.getIndex();
                    pos.setIndex(source.length());
                    return source.substring(start);
                }
            };
        }
    }

    private Map<String, FormatFactory> registry;

    @Before
    public void setUp() {
        registry = new HashMap<>();
        registry.put("upper", new UpperCaseFormatFactory());
    }

    /* ---------------------------------------------------------------------- */
    /*  Constructors & basic toPattern / applyPattern behavior                */
    /* ---------------------------------------------------------------------- */

    @Test
    public void testDefaultConstructorUsesSuperPattern() {
        String pattern = "Hello {0}";
        ExtendedMessageFormat emf = new ExtendedMessageFormat(pattern);
        assertEquals(pattern, emf.toPattern());
        assertEquals("Hello World", emf.format(new Object[] { "World" }));
    }

    @Test
    public void testConstructorWithLocaleAndRegistry() {
        String pattern = "Value: {0,upper}";
        ExtendedMessageFormat emf = new ExtendedMessageFormat(pattern, Locale.US, registry);
        assertEquals(pattern, emf.toPattern());
        assertEquals("Value: TEST", emf.format(new Object[] { "test" }));
    }

    @Test
    public void testApplyPatternReplacesCustomFormats() {
        String pattern = "A:{0,upper} B:{1}";
        ExtendedMessageFormat emf = new ExtendedMessageFormat(pattern, Locale.US, registry);
        // toPattern must contain the original custom format description
        assertEquals(pattern, emf.toPattern());

        // The underlying MessageFormat (without custom factories) would have
        // left the format description out – ensure the custom format still works.
        assertEquals("A:FOO B:bar", emf.format(new Object[] { "foo", "bar" }));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testApplyPatternThrowsOnUnreadableElement() {
        // Missing closing brace after custom format description
        new ExtendedMessageFormat("Broken {0,upper", Locale.US, registry);
    }

    @Test
    public void testApplyPatternWithoutRegistryFallsBackToSuper() {
        String pattern = "Number: {0,number}";
        ExtendedMessageFormat emf = new ExtendedMessageFormat(pattern, Locale.US, null);
        // MessageFormat would format the number according to the locale.
        assertEquals("Number: 1,234.56", emf.format(new Object[] { 1234.56 }));
    }

    /* ---------------------------------------------------------------------- */
    /*  Unsupported mutator methods                                            */
    /* ---------------------------------------------------------------------- */

    @Test(expected = UnsupportedOperationException.class)
    public void testSetFormatIsUnsupported() {
        ExtendedMessageFormat emf = new ExtendedMessageFormat("{0}");
        emf.setFormat(0, new MessageFormat("{0}"));
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testSetFormatByArgumentIndexIsUnsupported() {
        ExtendedMessageFormat emf = new ExtendedMessageFormat("{0}");
        emf.setFormatByArgumentIndex(0, new MessageFormat("{0}"));
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testSetFormatsIsUnsupported() {
        ExtendedMessageFormat emf = new ExtendedMessageFormat("{0}");
        emf.setFormats(new Format[] { new MessageFormat("{0}") });
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testSetFormatsByArgumentIndexIsUnsupported() {
        ExtendedMessageFormat emf = new ExtendedMessageFormat("{0}");
        emf.setFormatsByArgumentIndex(new Format[] { new MessageFormat("{0}") });
    }

    /* ---------------------------------------------------------------------- */
    /*  Private helper methods – exercised via reflection or indirect calls   */
    /* ---------------------------------------------------------------------- */

    /**
     * Helper to invoke the private {@code readArgumentIndex} method.
     */
    private int invokeReadArgumentIndex(String pattern, int startPos) throws Exception {
        java.lang.reflect.Method m = ExtendedMessageFormat.class
                .getDeclaredMethod("readArgumentIndex", String.class, ParsePosition.class);
        m.setAccessible(true);
        ParsePosition pos = new ParsePosition(startPos);
        return (Integer) m.invoke(new ExtendedMessageFormat("{0}"), pattern, pos);
    }

    /**
     * Helper to invoke the private {@code parseFormatDescription} method.
     */
    private String invokeParseFormatDescription(String pattern, int startPos) throws Exception {
        java.lang.reflect.Method m = ExtendedMessageFormat.class
                .getDeclaredMethod("parseFormatDescription", String.class, ParsePosition.class);
        m.setAccessible(true);
        ParsePosition pos = new ParsePosition(startPos);
        return (String) m.invoke(new ExtendedMessageFormat("{0}"), pattern, pos);
    }

    @Test
    public void testReadArgumentIndexSimple() throws Exception {
        assertEquals(0, invokeReadArgumentIndex("{0}", 1));
        assertEquals(12, invokeReadArgumentIndex("{  12 }", 1));
    }

    @Test
    public void testReadArgumentIndexWithWhitespaceAndComma() throws Exception {
        // Pattern: {  5 ,upper}
        assertEquals(5, invokeReadArgumentIndex("{ 5 ,upper}", 1));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testReadArgumentIndexInvalidNumber() throws Exception {
        // Non‑numeric argument index triggers an IllegalArgumentException.
        invokeReadArgumentIndex("{abc}", 1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testReadArgumentIndexUnterminated() throws Exception {
        // Missing closing brace – the parser runs off the end.
        invokeReadArgumentIndex("{123", 1);
    }

    @Test
    public void testParseFormatDescriptionSimple() throws Exception {
        // Pattern: {0,upper}
        String desc = invokeParseFormatDescription("{0,upper}", 3);
        assertEquals("upper", desc);
    }

    @Test
    public void testParseFormatDescriptionWithNestedBraces() throws Exception {
        // Pattern: {0,choice{0#zero|1#one{inner}}}
        String pattern = "{0,choice{0#zero|1#one{inner}}}";
        String desc = invokeParseFormatDescription(pattern, 3);
        assertEquals("choice{0#zero|1#one{inner}}", desc);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseFormatDescriptionUnterminated() throws Exception {
        // No closing '}'
        invokeParseFormatDescription("{0,upper", 3);
    }

    @Test
    public void testInsertFormatsNoCustomPatterns() throws Exception {
        java.lang.reflect.Method m = ExtendedMessageFormat.class
                .getDeclaredMethod("insertFormats", String.class, ArrayList.class);
        m.setAccessible(true);
        String result = (String) m.invoke(new ExtendedMessageFormat("{0}"),
                "Hello {0}", new ArrayList<>());
        assertEquals("Hello {0}", result);
    }

    @Test
    public void testInsertFormatsWithCustomPatterns() throws Exception {
        java.lang.reflect.Method m = ExtendedMessageFormat.class
                .getDeclaredMethod("insertFormats", String.class, ArrayList.class);
        m.setAccessible(true);
        ArrayList<String> custom = new ArrayList<>();
        custom.add("upper");
        String result = (String) m.invoke(new ExtendedMessageFormat("{0,upper}"),
                "Test {0}", custom);
        assertEquals("Test {0,upper}", result);
    }

    @Test
    public void testSeekNonWsSkipsSpacesAndTabs() throws Exception {
        java.lang.reflect.Method m = ExtendedMessageFormat.class
                .getDeclaredMethod("seekNonWs", String.class, ParsePosition.class);
        m.setAccessible(true);
        ParsePosition pos = new ParsePosition(0);
        m.invoke(new ExtendedMessageFormat("{0}"), " \t  abc", pos);
        assertEquals(4, pos.getIndex()); // points at 'a'
    }

    @Test
    public void testNextAdvancesByOne() throws Exception {
        java.lang.reflect.Method m = ExtendedMessageFormat.class
                .getDeclaredMethod("next", ParsePosition.class);
        m.setAccessible(true);
        ParsePosition pos = new ParsePosition(5);
        m.invoke(new ExtendedMessageFormat("{0}"), pos);
        assertEquals(6, pos.getIndex());
    }

    @Test
    public void testAppendQuotedStringSimple() throws Exception {
        java.lang.reflect.Method m = ExtendedMessageFormat.class
                .getDeclaredMethod("appendQuotedString",
                        String.class, ParsePosition.class, StringBuffer.class, boolean.class);
        m.setAccessible(true);
        ParsePosition pos = new ParsePosition(0);
        StringBuffer sb = new StringBuffer();
        // pattern: 'abc'xyz   -> quoted part is abc, then we stop at closing quote.
        m.invoke(new ExtendedMessageFormat("{0}"), "'abc'xyz", pos, sb, true);
        assertEquals("abc", sb.toString());
        // Position should now be after the closing quote (index 5)
        assertEquals(5, pos.getIndex());
    }

    @Test
    public void testAppendQuotedStringEscapedQuote() throws Exception {
        java.lang.reflect.Method m = ExtendedMessageFormat.class
                .getDeclaredMethod("appendQuotedString",
                        String.class, ParsePosition.class, StringBuffer.class, boolean.class);
        m.setAccessible(true);
        ParsePosition pos = new ParsePosition(0);
        StringBuffer sb = new StringBuffer();
        // pattern: '' becomes a single quote when escapingOn==true
        m.invoke(new ExtendedMessageFormat("{0}"), "''", pos, sb, true);
        assertEquals("'", sb.toString());
        assertEquals(2, pos.getIndex());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testAppendQuotedStringUnterminatedThrows() throws Exception {
        java.lang.reflect.Method m = ExtendedMessageFormat.class
                .getDeclaredMethod("appendQuotedString",
                        String.class, ParsePosition.class, StringBuffer.class, boolean.class);
        m.setAccessible(true);
        ParsePosition pos = new ParsePosition(0);
        // missing closing quote
        m.invoke(new ExtendedMessageFormat("{0}"), "'unclosed", pos, new StringBuffer(), true);
    }

    @Test
    public void testGetQuotedStringConsumesWithoutAppending() throws Exception {
        java.lang.reflect.Method m = ExtendedMessageFormat.class
                .getDeclaredMethod("getQuotedString",
                        String.class, ParsePosition.class, boolean.class);
        m.setAccessible(true);
        ParsePosition pos = new ParsePosition(0);
        // pattern: 'text'
        m.invoke(new ExtendedMessageFormat("{0}"), "'text'", pos, true);
        // After consuming, index should be after the closing quote (5)
        assertEquals(5, pos.getIndex());
    }

    @Test
    public void testContainsElementsVariousScenarios() throws Exception {
        java.lang.reflect.Method m = ExtendedMessageFormat.class
                .getDeclaredMethod("containsElements", java.util.Collection.class);
        m.setAccessible(true);
        // null collection
        assertFalse((Boolean) m.invoke(new ExtendedMessageFormat("{0}"), (Object) null));
        // empty collection
        assertFalse((Boolean) m.invoke(new ExtendedMessageFormat("{0}"), Collections.emptyList()));
        // collection with all nulls
        ArrayList<Object> allNull = new ArrayList<>();
        allNull.add(null);
        allNull.add(null);
        assertFalse((Boolean) m.invoke(new ExtendedMessageFormat("{0}"), allNull));
        // collection with a non‑null element
        ArrayList<Object> mixed = new ArrayList<>();
        mixed.add(null);
        mixed.add("something");
        assertTrue((Boolean) m.invoke(new ExtendedMessageFormat("{0}"), mixed));
    }

    /* ---------------------------------------------------------------------- */
    /*  Integration style tests – real usage of custom formats                */
    /* ---------------------------------------------------------------------- */

    @Test
    public void testMultipleCustomFormatsInOnePattern() {
        String pattern = "{0,upper} - {1,upper}";
        ExtendedMessageFormat emf = new ExtendedMessageFormat(pattern, Locale.US, registry);
        assertEquals("HELLO - WORLD", emf.format(new Object[] { "hello", "world" }));
    }

    @Test
    public void testCustomFormatWithArguments() {
        // Register a factory that accepts an argument (prefix) and adds it.
        registry.put("prefixed", new FormatFactory() {
            @Override
            public Format getFormat(String name, String arguments, Locale locale) {
                final String prefix = arguments == null ? "" : arguments;
                return new Format() {
                    @Override
                    public StringBuffer format(Object obj, StringBuffer toAppendTo,
                            java.text.FieldPosition pos) {
                        return toAppendTo.append(prefix).append(String.valueOf(obj));
                    }

                    @Override
                    public Object parseObject(String source, ParsePosition pos) {
                        int start = pos.getIndex();
                        pos.setIndex(source.length());
                        return source.substring(start);
                    }
                };
            }
        });

        String pattern = "Value: {0,prefixed,>> }";
        ExtendedMessageFormat emf = new ExtendedMessageFormat(pattern, Locale.US, registry);
        assertEquals("Value: >> test", emf.format(new Object[] { "test" }));
        // Ensure toPattern returns the original pattern (including arguments)
        assertEquals(pattern, emf.toPattern());
    }

    @Test
    public void testQuotedLiteralsAndEscapedQuotesInPattern() {
        // Pattern contains a quoted literal and an escaped quote.
        String pattern = "He said ''{0}'' and then \"{1}\"";
        ExtendedMessageFormat emf = new ExtendedMessageFormat(pattern);
        String result = emf.format(new Object[] { "X", "Y" });
        // The doubled single quotes become a single quote literal.
        assertEquals("He said 'X' and then \"Y\"", result);
    }

    @Test
    public void testPatternWithNestedChoiceAndCustomFormat() {
        // Choose between two formats, the second uses a custom format.
        registry.put("upper", new UpperCaseFormatFactory());
        String pattern = "{0,choice,0#none|1#{1,upper}}";
        ExtendedMessageFormat emf = new ExtendedMessageFormat(pattern, Locale.US, registry);
        assertEquals("none", emf.format(new Object[] { 0, "ignored" }));
        assertEquals("HELLO", emf.format(new Object[] { 1, "hello" }));
    }
}

/**
 * JUnit 4 test suite for {@link org.apache.commons.lang.text.ExtendedMessageFormat}.
 *
 * The tests cover:
 * <ul>
 *   <li>Public API extraction and basic functionality</li>
 *   <li>Edge‑case handling (invalid patterns, illegal argument indexes, quoting)</li>
 *   <li>Custom {@code FormatFactory} integration</li>
 *   <li>Verification that mutator methods throw {@code UnsupportedOperationException}</li>
 * </ul>
 *
 * The test class is deliberately self‑contained – a minimal {@code FormatFactory}
 * and a couple of simple {@code Format} implementations are defined as inner classes
 * so that the suite can be compiled and executed without external dependencies.
 */
package org.apache.commons.lang.text;

import static org.junit.Assert.*;

import java.text.Format;
import java.text.FieldPosition;
import java.text.ParsePosition;
import java.util.Collections;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

import org.junit.Test;

/**
 * Test cases for {@link ExtendedMessageFormat}.
 */
public class ExtendedMessageFormatTest {

    // ------------------------------------------------------------------------
    //  Helper classes used in the tests
    // ------------------------------------------------------------------------

    /**
     * Simple {@code FormatFactory} that knows two custom formats:
     * <ul>
     *   <li>"upper" – returns an {@link UpperCaseFormat}</li>
     *   <li>"repeat" – returns a {@link RepeatFormat} using the argument supplied after a comma</li>
     * </ul>
     */
    private static class DummyFactory implements FormatFactory {
        @Override
        public Format getFormat(String name, String arguments, Locale locale) {
            if ("upper".equals(name)) {
                return new UpperCaseFormat();
            }
            if ("repeat".equals(name)) {
                int times = 1;
                if (arguments != null) {
                    try {
                        times = Integer.parseInt(arguments.trim());
                    } catch (NumberFormatException e) {
                        // ignore – fall back to default 1
                    }
                }
                return new RepeatFormat(times);
            }
            return null;
        }
    }

    /** {@code Format} that converts a string to upper case. */
    private static class UpperCaseFormat extends Format {
        private static final long serialVersionUID = 1L;

        @Override
        public StringBuffer format(Object obj, StringBuffer toAppendTo,
                FieldPosition pos) {
            return toAppendTo.append(String.valueOf(obj).toUpperCase(Locale.ROOT));
        }

        @Override
        public Object parseObject(String source, ParsePosition pos) {
            // parsing not needed for the tests
            return source;
        }
    }

    /** {@code Format} that repeats the string a given number of times. */
    private static class RepeatFormat extends Format {
        private static final long serialVersionUID = 1L;
        private final int repeat;

        RepeatFormat(int repeat) {
            this.repeat = repeat;
        }

        @Override
        public StringBuffer format(Object obj, StringBuffer toAppendTo,
                FieldPosition pos) {
            String s = String.valueOf(obj);
            for (int i = 0; i < repeat; i++) {
                toAppendTo.append(s);
            }
            return toAppendTo;
        }

        @Override
        public Object parseObject(String source, ParsePosition pos) {
            // parsing not needed for the tests
            return source;
        }
    }

    // ------------------------------------------------------------------------
    //  1. Extraction of public API (constructors + public methods)
    // ------------------------------------------------------------------------
    // Constructors (all are public):
    //   ExtendedMessageFormat(String pattern)
    //   ExtendedMessageFormat(String pattern, Locale locale)
    //   ExtendedMessageFormat(String pattern, Map registry)
    //   ExtendedMessageFormat(String pattern, Locale locale, Map registry)
    //
    // Public methods declared in this class:
    //   String toPattern()
    //   void applyPattern(String pattern)
    //   void setFormat(int formatElementIndex, Format newFormat)      // throws UnsupportedOperationException
    //   void setFormatByArgumentIndex(int argumentIndex, Format newFormat) // throws UnsupportedOperationException
    //   void setFormats(Format[] newFormats)                        // throws UnsupportedOperationException
    //   void setFormatsByArgumentIndex(Format[] newFormats)        // throws UnsupportedOperationException

    // ------------------------------------------------------------------------
    //  2. Basic functional tests for each public method
    // ------------------------------------------------------------------------

    @Test
    public void testToPattern_SimplePattern() {
        ExtendedMessageFormat emf = new ExtendedMessageFormat("Hello {0}");
        assertEquals("Hello {0}", emf.toPattern());
    }

    @Test
    public void testApplyPattern_WithoutRegistry() {
        ExtendedMessageFormat emf = new ExtendedMessageFormat("Number: {0,number}");
        // Changing the pattern should be reflected in toPattern()
        emf.applyPattern("Number: {0,number,#.##}");
        assertEquals("Number: {0,number,#.##}", emf.toPattern());
    }

    @Test
    public void testCustomFormat_UpperCase() {
        Map<String, FormatFactory> registry = new HashMap<String, FormatFactory>();
        registry.put("upper", new DummyFactory());

        ExtendedMessageFormat emf = new ExtendedMessageFormat("{0,upper}", registry);
        assertEquals("{0,upper}", emf.toPattern());

        Object[] args = new Object[] { "test" };
        String result = emf.format(args);
        assertEquals("TEST", result);
    }

    @Test
    public void testCustomFormat_RepeatWithArgument() {
        Map<String, FormatFactory> registry = new HashMap<String, FormatFactory>();
        registry.put("repeat", new DummyFactory());

        // pattern uses a custom format "repeat" with argument "3"
        ExtendedMessageFormat emf = new ExtendedMessageFormat("{0,repeat,3}", registry);
        assertEquals("{0,repeat,3}", emf.toPattern());

        String result = emf.format(new Object[] { "ab" });
        assertEquals("ababab", result);
    }

    @Test
    public void testSetFormat_UnsupportedOperation() {
        ExtendedMessageFormat emf = new ExtendedMessageFormat("{0}");
        try {
            emf.setFormat(0, new UpperCaseFormat());
            fail("Expected UnsupportedOperationException");
        } catch (UnsupportedOperationException e) {
            // expected
        }
    }

    @Test
    public void testSetFormatByArgumentIndex_UnsupportedOperation() {
        ExtendedMessageFormat emf = new ExtendedMessageFormat("{0}");
        try {
            emf.setFormatByArgumentIndex(0, new UpperCaseFormat());
            fail("Expected UnsupportedOperationException");
        } catch (UnsupportedOperationException e) {
            // expected
        }
    }

    @Test
    public void testSetFormats_UnsupportedOperation() {
        ExtendedMessageFormat emf = new ExtendedMessageFormat("{0}");
        try {
            emf.setFormats(new Format[] { new UpperCaseFormat() });
            fail("Expected UnsupportedOperationException");
        } catch (UnsupportedOperationException e) {
            // expected
        }
    }

    @Test
    public void testSetFormatsByArgumentIndex_UnsupportedOperation() {
        ExtendedMessageFormat emf = new ExtendedMessageFormat("{0}");
        try {
            emf.setFormatsByArgumentIndex(new Format[] { new UpperCaseFormat() });
            fail("Expected UnsupportedOperationException");
        } catch (UnsupportedOperationException e) {
            // expected
        }
    }

    // ------------------------------------------------------------------------
    //  3. Edge‑case and exception handling tests
    // ------------------------------------------------------------------------

    /** Pattern missing a closing brace should cause IllegalArgumentException. */
    @Test(expected = IllegalArgumentException.class)
    public void testInvalidPattern_UnterminatedBrace() {
        new ExtendedMessageFormat("{0");
    }

    /** Pattern with a non‑numeric argument index should cause IllegalArgumentException. */
    @Test(expected = IllegalArgumentException.class)
    public void testInvalidPattern_NonNumericArgumentIndex() {
        new ExtendedMessageFormat("{abc}");
    }

    /** Pattern where the format description is not closed with '}' should throw. */
    @Test(expected = IllegalArgumentException.class)
    public void testInvalidPattern_UnterminatedFormatDescription() {
        new ExtendedMessageFormat("{0,upper");
    }

    /** Verify that escaped single quotes are handled correctly. */
    @Test
    public void testEscapedQuote_InPattern() {
        // In MessageFormat, two consecutive single quotes become one literal quote.
        ExtendedMessageFormat emf = new ExtendedMessageFormat("He''llo {0}");
        assertEquals("He''llo {0}", emf.toPattern());

        String result = emf.format(new Object[] { "world" });
        assertEquals("He'llo world", result);
    }

    /** Verify that a quoted literal brace is treated as a literal, not a format element. */
    @Test
    public void testQuotedLiteralBrace() {
        ExtendedMessageFormat emf = new ExtendedMessageFormat("'{0}'");
        assertEquals("'{0}'", emf.toPattern());

        String result = emf.format(new Object[] { "ignored" });
        assertEquals("{0}", result);
    }

    /** Empty pattern should be accepted and toPattern() should return empty string. */
    @Test
    public void testEmptyPattern() {
        ExtendedMessageFormat emf = new ExtendedMessageFormat("");
        assertEquals("", emf.toPattern());
        assertEquals("", emf.format(new Object[0]));
    }

    /** Null registry should behave like the base MessageFormat (no custom formats). */
    @Test
    public void testNullRegistryFallsBackToBaseBehavior() {
        ExtendedMessageFormat emf = new ExtendedMessageFormat("{0,number,#.##}", null);
        assertEquals("{0,number,#.##}", emf.toPattern());

        String result = emf.format(new Object[] { 1234.567 });
        // default number format for Locale.US (default locale of the test runner)
        // we don't assert exact locale‑dependent representation; just ensure no exception.
        assertNotNull(result);
    }

    /** Verify that whitespace around format name and arguments is ignored. */
    @Test
    public void testWhitespaceAroundCustomFormat() {
        Map<String, FormatFactory> registry = Collections.singletonMap("upper", new DummyFactory());
        ExtendedMessageFormat emf = new ExtendedMessageFormat("{0,  upper   }", registry);
        assertEquals("{0,  upper   }", emf.toPattern());

        String result = emf.format(new Object[] { "spAce" });
        assertEquals("SPACE", result);
    }

    /** Verify that a custom format returning null is ignored (fallback to default). */
    @Test
    public void testCustomFormatFactoryReturnsNull() {
        // Registry contains a factory that returns null for unknown names.
        Map<String, FormatFactory> registry = Collections.singletonMap("dummy", new DummyFactory());

        // "unknown" is not present in the registry – should be treated as a normal format name.
        ExtendedMessageFormat emf = new ExtendedMessageFormat("{0,unknown}", registry);
        assertEquals("{0,unknown}", emf.toPattern());

        // Since "unknown" is not a standard MessageFormat format, MessageFormat will treat it as a literal.
        String result = emf.format(new Object[] { "value" });
        assertEquals("{0,unknown}", result);
    }

    // ------------------------------------------------------------------------
    //  4. Integration test – round‑trip pattern reconstruction
    // ------------------------------------------------------------------------

    @Test
    public void testRoundTripPatternWithMultipleCustomFormats() {
        Map<String, FormatFactory> registry = new HashMap<String, FormatFactory>();
        registry.put("upper", new DummyFactory());
        registry.put("repeat", new DummyFactory());

        String pattern = "Start {0,upper} middle {1,repeat,2} end";
        ExtendedMessageFormat emf = new ExtendedMessageFormat(pattern, registry);

        // toPattern should reproduce the original pattern (including whitespace)
        assertEquals(pattern, emf.toPattern());

        Object[] args = new Object[] { "a", "b" };
        String formatted = emf.format(args);
        // upper -> "A", repeat 2 -> "bb"
        assertEquals("Start A middle bb end", formatted);
    }
}

/*
 * JUnit 4 test cases for {@link org.apache.commons.lang.LocaleUtils}.
 *
 * These tests cover all public static methods, checking normal operation,
 * edge cases, exception handling and the immutability / caching behaviour
 * of the utility class.
 */
package org.apache.commons.lang;

import org.junit.Test;
import org.junit.BeforeClass;

import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Set;

import static org.junit.Assert.*;

public class LocaleUtilsTest {

    // -----------------------------------------------------------------------
    // toLocale tests
    // -----------------------------------------------------------------------
    @Test
    public void testToLocale_nullInput() {
        assertNull(LocaleUtils.toLocale(null));
    }

    @Test
    public void testToLocale_languageOnly() {
        Locale locale = LocaleUtils.toLocale("en");
        assertEquals("en", locale.getLanguage());
        assertEquals("", locale.getCountry());
        assertEquals("", locale.getVariant());
    }

    @Test
    public void testToLocale_languageAndCountry() {
        Locale locale = LocaleUtils.toLocale("en_GB");
        assertEquals("en", locale.getLanguage());
        assertEquals("GB", locale.getCountry());
        assertEquals("", locale.getVariant());
    }

    @Test
    public void testToLocale_withVariant() {
        Locale locale = LocaleUtils.toLocale("fr_CA_xxx");
        assertEquals("fr", locale.getLanguage());
        assertEquals("CA", locale.getCountry());
        assertEquals("xxx", locale.getVariant());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testToLocale_invalidLength_oneChar() {
        LocaleUtils.toLocale("e");
    }

    @Test(expected = IllegalArgumentException.class)
    public void testToLocale_invalidLength_threeChars() {
        LocaleUtils.toLocale("eng");
    }

    @Test(expected = IllegalArgumentException.class)
    public void testToLocale_invalidLanguageUpperCase() {
        LocaleUtils.toLocale("En");
    }

    @Test(expected = IllegalArgumentException.class)
    public void testToLocale_invalidCountryLowerCase() {
        LocaleUtils.toLocale("en_gb");
    }

    @Test(expected = IllegalArgumentException.class)
    public void testToLocale_missingUnderscore() {
        LocaleUtils.toLocale("engb");
    }

    @Test(expected = IllegalArgumentException.class)
    public void testToLocale_missingSecondUnderscoreForVariant() {
        LocaleUtils.toLocale("en_GBx");
    }

    // -----------------------------------------------------------------------
    // localeLookupList tests (both overloads)
    // -----------------------------------------------------------------------
    @Test
    public void testLocaleLookupList_nullLocale() {
        List list = LocaleUtils.localeLookupList(null);
        assertNotNull(list);
        assertTrue(list.isEmpty());
    }

    @Test
    public void testLocaleLookupList_simpleLocale() {
        Locale locale = new Locale("de", "DE");
        List list = LocaleUtils.localeLookupList(locale);
        assertEquals(3, list.size());
        assertEquals(locale, list.get(0));
        assertEquals(new Locale("de", ""), list.get(1));
        // default locale is added as the third element (same as passed locale)
        assertEquals(Locale.getDefault(), list.get(2));
    }

    @Test
    public void testLocaleLookupList_withVariantAndDefault() {
        Locale specific = new Locale("fr", "CA", "xxx");
        Locale defaultLoc = Locale.CANADA_FRENCH;
        List list = LocaleUtils.localeLookupList(specific, defaultLoc);
        assertEquals(4, list.size());
        assertEquals(specific, list.get(0));
        assertEquals(new Locale("fr", "CA"), list.get(1)); // without variant
        assertEquals(new Locale("fr", ""), list.get(2));   // language only
        assertEquals(defaultLoc, list.get(3));            // default supplied
    }

    @Test
    public void testLocaleLookupList_defaultAlreadyInList() {
        Locale locale = new Locale("it", "IT");
        List list = LocaleUtils.localeLookupList(locale, locale);
        // default (=locale) should not be added twice
        assertEquals(3, list.size());
        assertEquals(locale, list.get(0));
        assertEquals(new Locale("it", ""), list.get(1));
        assertEquals(locale, list.get(2));
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testLocaleLookupList_isUnmodifiable() {
        Locale locale = new Locale("es", "ES");
        List list = LocaleUtils.localeLookupList(locale);
        list.add(Locale.JAPAN); // should throw
    }

    // -----------------------------------------------------------------------
    // availableLocaleList / Set tests
    // -----------------------------------------------------------------------
    @Test
    public void testAvailableLocaleList_isUnmodifiableAndContainsKnownLocale() {
        List list = LocaleUtils.availableLocaleList();
        assertNotNull(list);
        assertFalse(list.isEmpty());
        assertTrue(list.contains(Locale.US));

        try {
            list.add(Locale.CHINA);
            fail("expected UnsupportedOperationException");
        } catch (UnsupportedOperationException ignored) {
        }
    }

    @Test
    public void testAvailableLocaleSet_isSingletonAndUnmodifiable() {
        Set set1 = LocaleUtils.availableLocaleSet();
        Set set2 = LocaleUtils.availableLocaleSet();

        // The method should cache the set and return the same instance
        assertSame(set1, set2);
        assertTrue(set1.contains(Locale.US));

        try {
            set1.add(Locale.CANADA);
            fail("expected UnsupportedOperationException");
        } catch (UnsupportedOperationException ignored) {
        }
    }

    @Test
    public void testIsAvailableLocale() {
        assertTrue(LocaleUtils.isAvailableLocale(Locale.US));
        assertTrue(LocaleUtils.isAvailableLocale(Locale.ROOT)); // always present
        // Build a locale that is very unlikely to exist
        Locale bogus = new Locale("zz", "ZZ");
        // It may exist on some exotic JDKs, so we test the method's contract
        // by checking that the result matches the list content
        boolean inList = LocaleUtils.availableLocaleList().contains(bogus);
        assertEquals(inList, LocaleUtils.isAvailableLocale(bogus));
    }

    // -----------------------------------------------------------------------
    // languagesByCountry tests
    // -----------------------------------------------------------------------
    @Test
    public void testLanguagesByCountry_nullInput() {
        List list = LocaleUtils.languagesByCountry(null);
        assertNotNull(list);
        assertTrue(list.isEmpty());
    }

    @Test
    public void testLanguagesByCountry_knownCountry() {
        // Use "US" – most JDKs have a handful of locales for this country.
        List usLangs = LocaleUtils.languagesByCountry("US");
        assertNotNull(usLangs);
        assertFalse(usLangs.isEmpty());

        // All returned locales must have country "US" and no variant.
        for (Object obj : usLangs) {
            Locale loc = (Locale) obj;
            assertEquals("US", loc.getCountry());
            assertEquals("", loc.getVariant());
        }

        // Cache test – second call should return the same (unmodifiable) list instance
        List usLangs2 = LocaleUtils.languagesByCountry("US");
        assertSame(usLangs, usLangs2);
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testLanguagesByCountry_isUnmodifiable() {
        List list = LocaleUtils.languagesByCountry("GB");
        list.add(Locale.GERMANY);
    }

    @Test
    public void testLanguagesByCountry_excludesVariantLocales() {
        // Find a locale with a variant for a known country (e.g., "en_US_POSIX")
        Locale variant = null;
        for (Locale l : Locale.getAvailableLocales()) {
            if ("US".equals(l.getCountry()) && l.getVariant().length() > 0) {
                variant = l;
                break;
            }
        }
        if (variant != null) {
            List usLangs = LocaleUtils.languagesByCountry("US");
            assertFalse("Variant locale should be excluded", usLangs.contains(variant));
        }
    }

    // -----------------------------------------------------------------------
    // countriesByLanguage tests
    // -----------------------------------------------------------------------
    @Test
    public void testCountriesByLanguage_nullInput() {
        List list = LocaleUtils.countriesByLanguage(null);
        assertNotNull(list);
        assertTrue(list.isEmpty());
    }

    @Test
    public void testCountriesByLanguage_knownLanguage() {
        // Use "en" – should have many locales with non‑empty country.
        List enCountries = LocaleUtils.countriesByLanguage("en");
        assertNotNull(enCountries);
        assertFalse(enCountries.isEmpty());

        for (Object obj : enCountries) {
            Locale loc = (Locale) obj;
            assertEquals("en", loc.getLanguage());
            assertFalse(loc.getCountry().isEmpty());
            assertEquals("", loc.getVariant());
        }

        // Cache test – second call returns same instance.
        List enCountries2 = LocaleUtils.countriesByLanguage("en");
        assertSame(enCountries, enCountries2);
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testCountriesByLanguage_isUnmodifiable() {
        List list = LocaleUtils.countriesByLanguage("fr");
        list.add(Locale.JAPAN);
    }

    @Test
    public void testCountriesByLanguage_excludesVariantLocales() {
        // Find a variant locale for language "en"
        Locale variant = null;
        for (Locale l : Locale.getAvailableLocales()) {
            if ("en".equals(l.getLanguage()) && l.getVariant().length() > 0) {
                variant = l;
                break;
            }
        }
        if (variant != null) {
            List enCountries = LocaleUtils.countriesByLanguage("en");
            assertFalse("Variant locale should be excluded", enCountries.contains(variant));
        }
    }

    // -----------------------------------------------------------------------
    // Helper to avoid test ordering issues (JUnit does not guarantee order)
    // -----------------------------------------------------------------------
    @BeforeClass
    public static void setUpClass() {
        // Ensure the default locale is not null; it is used in some lookup list tests.
        assertNotNull(Locale.getDefault());
    }
}

package org.apache.commons.lang;

import static org.junit.Assert.*;

import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Set;

import org.junit.Before;
import org.junit.Test;

/**
 * Comprehensive JUnit4 tests for {@link LocaleUtils}.
 */
public class LocaleUtilsTest {

    // -----------------------------------------------------------------------
    // toLocale tests
    // -----------------------------------------------------------------------

    @Test
    public void testToLocale_NullInput() {
        assertNull(LocaleUtils.toLocale(null));
    }

    @Test
    public void testToLocale_LanguageOnly() {
        Locale locale = LocaleUtils.toLocale("en");
        assertEquals("en", locale.getLanguage());
        assertEquals("", locale.getCountry());
        assertEquals("", locale.getVariant());
    }

    @Test
    public void testToLocale_LanguageAndCountry() {
        Locale locale = LocaleUtils.toLocale("en_GB");
        assertEquals("en", locale.getLanguage());
        assertEquals("GB", locale.getCountry());
        assertEquals("", locale.getVariant());
    }

    @Test
    public void testToLocale_WithVariant() {
        Locale locale = LocaleUtils.toLocale("en_GB_xxx");
        assertEquals("en", locale.getLanguage());
        assertEquals("GB", locale.getCountry());
        // Variant is taken as‑is (no upper‑casing enforced by LocaleUtils)
        assertEquals("xxx", locale.getVariant());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testToLocale_InvalidLength_OneChar() {
        LocaleUtils.toLocale("e");
    }

    @Test(expected = IllegalArgumentException.class)
    public void testToLocale_InvalidLength_ThreeChars() {
        LocaleUtils.toLocale("eng");
    }

    @Test(expected = IllegalArgumentException.class)
    public void testToLocale_LowercaseCountry() {
        LocaleUtils.toLocale("en_gb");
    }

    @Test(expected = IllegalArgumentException.class)
    public void testToLocale_UppercaseLanguage() {
        LocaleUtils.toLocale("EN_gb");
    }

    @Test(expected = IllegalArgumentException.class)
    public void testToLocale_MissingUnderscore() {
        LocaleUtils.toLocale("engb");
    }

    @Test(expected = IllegalArgumentException.class)
    public void testToLocale_TooShortVariant() {
        LocaleUtils.toLocale("en_GB_");
    }

    // -----------------------------------------------------------------------
    // localeLookupList tests
    // -----------------------------------------------------------------------

    @Test
    public void testLocaleLookupList_Simple() {
        Locale start = new Locale("fr", "CA", "xxx");
        List list = LocaleUtils.localeLookupList(start);
        assertEquals(3, list.size());
        assertEquals(start, list.get(0));
        assertEquals(new Locale("fr", "CA"), list.get(1));
        assertEquals(new Locale("fr", ""), list.get(2));
    }

    @Test
    public void testLocaleLookupList_WithDefault_NotDuplicated() {
        Locale start = new Locale("fr", "CA", "xxx");
        Locale def = new Locale("fr", "CA"); // already present as second element
        List list = LocaleUtils.localeLookupList(start, def);
        // default should not be added a second time
        assertEquals(3, list.size());
        assertTrue(list.contains(def));
    }

    @Test
    public void testLocaleLookupList_WithDefault_AddedAtEnd() {
        Locale start = new Locale("fr", "CA", "xxx");
        Locale def = new Locale("en", "US");
        List list = LocaleUtils.localeLookupList(start, def);
        assertEquals(4, list.size());
        assertEquals(def, list.get(3));
    }

    @Test
    public void testLocaleLookupList_NullLocale() {
        List list = LocaleUtils.localeLookupList(null);
        assertTrue(list.isEmpty());
    }

    @Test
    public void testLocaleLookupList_NullLocaleWithDefault() {
        Locale def = new Locale("de", "DE");
        List list = LocaleUtils.localeLookupList(null, def);
        // According to implementation, null locale leads to empty list (default not added)
        assertTrue(list.isEmpty());
    }

    // -----------------------------------------------------------------------
    // availableLocaleList / availableLocaleSet tests
    // -----------------------------------------------------------------------

    @Test
    public void testAvailableLocaleList_NotModifiable() {
        List list = LocaleUtils.availableLocaleList();
        assertNotNull(list);
        try {
            list.add(Locale.CANADA);
            fail("expected UnsupportedOperationException");
        } catch (UnsupportedOperationException expected) {
            // ok
        }
        // The list should still contain the original locales
        assertTrue(list.contains(Locale.CANADA) || Locale.getAvailableLocales().length == 0);
    }

    @Test
    public void testAvailableLocaleSet_NotModifiable() {
        Set set = LocaleUtils.availableLocaleSet();
        assertNotNull(set);
        try {
            set.add(Locale.CANADA);
            fail("expected UnsupportedOperationException");
        } catch (UnsupportedOperationException expected) {
            // ok
        }
        // Ensure the set matches the underlying list
        assertEquals(LocaleUtils.availableLocaleList().size(), set.size());
        assertTrue(set.containsAll(LocaleUtils.availableLocaleList()));
    }

    @Test
    public void testAvailableLocaleSet_CachesResult() {
        Set first = LocaleUtils.availableLocaleSet();
        Set second = LocaleUtils.availableLocaleSet();
        assertSame(first, second);
    }

    // -----------------------------------------------------------------------
    // isAvailableLocale tests
    // -----------------------------------------------------------------------

    @Test
    public void testIsAvailableLocale_KnownLocale() {
        Locale known = Locale.US; // always present on a JDK
        assertTrue(LocaleUtils.isAvailableLocale(known));
    }

    @Test
    public void testIsAvailableLocale_UnknownLocale() {
        Locale unknown = new Locale("xx", "YY");
        // Not guaranteed to be present – assert false unless the JDK oddly provides it
        assertFalse(LocaleUtils.isAvailableLocale(unknown));
    }

    // -----------------------------------------------------------------------
    // languagesByCountry tests
    // -----------------------------------------------------------------------

    @Test
    public void testLanguagesByCountry_Null() {
        List list = LocaleUtils.languagesByCountry(null);
        assertNotNull(list);
        assertTrue(list.isEmpty());
    }

    @Test
    public void testLanguagesByCountry_ValidCountry() {
        // Use a country code that is guaranteed to exist on any JDK, e.g., "US"
        List langs = LocaleUtils.languagesByCountry("US");
        assertNotNull(langs);
        // At least English ("en") should be present
        boolean containsEnglish = false;
        for (Object o : langs) {
            Locale l = (Locale) o;
            if ("en".equals(l.getLanguage())) {
                containsEnglish = true;
                break;
            }
        }
        assertTrue("Expected to find English for US", containsEnglish);
        // Ensure no variant locales are present
        for (Object o : langs) {
            Locale l = (Locale) o;
            assertEquals("Variant should be empty", "", l.getVariant());
        }
    }

